export default " \\\"provider\\\": \\\"OpenAI\\\",\\n            \\\"icon\\\": \\\"OpenAI\\\",\\n            \\\"models\\\": [{\\\"model_name\\\": openai_model, \\\"metadata\\\": {\\\"default\\\": True, \\\"model_type\\\": model_type}}],\\n        },\\n        {\\n            \\\"provider\\\": \\\"Anthropic\\\",\\n            \\\"icon\\\": \\\"Anthropic\\\",\\n            \\\"models\\\": [{\\\"model_name\\\": \\\"blocked-static\\\", \\\"metadata\\\": {\\\"default\\\": True, \\\"model_type\\\": model_type}}],\\n        },\\n    ]\\n    live_enabled_providers = []\\n    policy = _restricted_snapshot(\\\"openai\\\")\\n    fetch_enabled = AsyncMock(return_value={\\\"OpenAI\\\", \\\"Anthropic\\\"})\\n\\n    def _replace_with_live_models(groups, _user_id, enabled_providers, *_args, **_kwargs):\\n        live_enabled_providers.append(set(enabled_providers))\\n        groups.append(\\n            {\\n                \\\"provider\\\": \\\"Anthropic\\\",\\n                \\\"models\\\": [{\\\"model_name\\\": \\\"blocked-live\\\", \\\"metadata\\\": {\\\"default\\\": True, \\\"model_type\\\": model_type}}],\\n            }\\n        )\\n\\n    def _inject_custom(groups, *_args, **_kwargs):\\n        groups.append(\\n            {\\n                \\\"provider\\\": \\\"Anthropic\\\",\\n                \\\"models\\\": [{\\\"model_name\\\": \\\"blocked-custom\\\", \\\"metadata\\\": {\\\"default\\\": True, \\\"model_type\\\": model_type}}],\\n            }\\n        )\\n\\n    with (\\n        patch.object(model_catalog, \\\"get_unified_models_detailed\\\", return_value=catalog),\\n        patch.object(model_catalog, \\\"_get_model_status\\\", new=AsyncMock(return_value=(set(), set()))),\\n        patch.object(\\n            model_catalog,\\n            \\\"_fetch_enabled_providers_for_user\\\",\\n            new=fetch_enabled,\\n        ),\\n        patch.object(model_catalog, \\\"replace_with_live_models\\\", side_effect=_replace_with_live_models),\\n        patch.object(model_catalog, \\\"inject_custom_enabled_models\\\", side_effect=_inject_custom),\\n    ):\\n        options = getattr(model_catalog, option_builder)(\\n            user_id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            provider_policy=policy,\\n        )\\n\\n    fetch_enabled.assert_awaited_once_with(\\n        \\\"00000000-0000-0000-0000-000000000001\\\",\\n        provider_policy=policy,\\n    )\\n    assert live_enabled_providers == [{\\\"OpenAI\\\"}]\\n    assert {(option[\\\"provider\\\"], option[\\\"name\\\"]) for option in options} == {(\\\"OpenAI\\\", openai_model)}\\n\\n\\ndef _snapshot_with_blocked(*blocked: str, allowed: tuple[str, ...] = (\\\"openai\\\", \\\"anthropic\\\", \\\"ollama\\\")):\\n    return ModelProviderPolicySnapshot(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n        candidate_provider_ids=frozenset({\\\"openai\\\", \\\"anthropic\\\", \\\"ollama\\\"}),\\n        allowed_provider_ids=frozenset(allowed),\\n        blocked_model_keys=frozenset(blocked),\\n    )\\n\\n\\ndef test_model_policy_key_grammar_matches_persisted_model_status_grammar():\\n    from lfx.base.models.unified_models.credentials import MODEL_STATUS_KEY_SEPARATOR, MODEL_STATUS_TYPES\\n    from lfx.services.model_provider_policy import MODEL_POLICY_KEY_SEPARATOR, MODEL_POLICY_KEY_TYPES\\n\\n    assert MODEL_POLICY_KEY_SEPARATOR == MODEL_STATUS_KEY_SEPARATOR\\n    assert MODEL_POLICY_KEY_TYPES == MODEL_STATUS_TYPES\\n\\n\\ndef test_snapshot_blocks_model_by_bare_qualified_and_typed_key():\\n    snapshot = _snapshot_with_blocked(\\n        \\\"bare-model\\\",\\n        \\\"anthropic::claude-blocked\\\",\\n        \\\"openai::llm::gpt-blocked\\\",\\n    )\\n\\n    assert not snapshot.allows_model(\\\"OpenAI\\\", \\\"bare-model\\\", model_type=\\\"llm\\\")\\n    assert not snapshot.allows_model(\\\"Anthropic\\\", \\\"claude-blocked\\\", model_type=\\\"llm\\\")\\n    assert not snapshot.allows_model(\\\"Anthropic\\\", \\\"claude-blocked\\\")\\n    assert not snapshot.allows_model(\\\"OpenAI\\\", \\\"gpt-blocked\\\", model_type=\\\"llm\\\")\\n    # A typed block never leaks onto the same name in the other modality.\\n    assert snapshot.allows_model(\\\"OpenAI\\\", \\\"gpt-blocked\\\", model_type=\\\"embeddings\\\")\\n    # An unknown row type cannot dodge a typed block.\\n    assert not snapshot.allows_model(\\\"OpenAI\\\", \\\"gpt-blocked\\\")\\n    # A qualified block never reaches another provider's models.\\n    assert snapshot.allows_model(\\\"OpenAI\\\", \\\"claude-blocked\\\", model_type=\\\"llm\\\")\\n    assert snapshot.allows_model(\\\"OpenAI\\\", \\\"gpt-ok\\\", model_type=\\\"llm\\\")\\n\\n\\ndef test_snapshot_with_no_blocked_keys_allows_every_model_of_allowed_providers():\\n    snapshot = _restricted_snapshot(\\\"openai\\\")\\n\\n    assert snapshot.blocked_model_keys == frozenset()\\n    assert snapshot.allows_model(\\\"OpenAI\\\", \\\"gpt-anything\\\", model_type=\\\"llm\\\")\\n    assert not snapshot.allows_model(\\\"Anthropic\\\", \\\"claude-anything\\\", model_type=\\\"llm\\\")\\n\\n\\ndef test_require_model_raises_generic_reason_coded_error():\\n    snapshot = _snapshot_with_blocked(\\\"anthropic::claude-blocked\\\")\\n\\n    snapshot.require_model(\\\"Anthropic\\\", \\\"claude-ok\\\", model_type=\\\"llm\\\")\\n    with pytest.raises(ModelProviderPolicyError) as exc_info:\\n        snapshot.require_model(\\\"Anthropic\\\", \\\"claude-blocked\\\", model_type=\\\"llm\\\")\\n\\n    assert exc_info.value.code == \\\"policy_blocked\\\"\\n    assert exc_info.value.provider_id == \\\"anthropic\\\"\\n    assert exc_info.value.model_name == \\\"claude-blocked\\\"\\n    assert str(exc_info.value) == (\\n        \\\"The requested model is not available: 'claude-blocked' (anthropic) is blocked by the \\\"\\n        \\\"current model provider policy. Ask an administrator to enable it.\\\"\\n    )\\n\\n\\ndef test_require_model_still_reports_denied_provider_without_model_detail():\\n    snapshot = _snapshot_with_blocked(\\\"anthropic::claude-blocked\\\", allowed=(\\\"openai\\\",))\\n\\n    with pytest.raises(ModelProviderPolicyError) as exc_info:\\n        snapshot.require_model(\\\"Anthropic\\\", \\\"claude-ok\\\", model_type=\\\"llm\\\")\\n\\n    assert exc_info.value.model_name is None\\n    assert str(exc_info.value) == \\\"The requested model provider is not available\\\"\\n\\n\\ndef test_base_service_resolves_blocked_model_keys_into_snapshot():\\n    class _BlockingPolicy(BaseModelProviderPolicyService):\\n        def __init__(self) -> None:\\n            super().__init__()\\n            self.set_ready()\\n\\n        def get_allowed_provider_ids(self, *, context, candidate_provider_ids, purpose):\\n            _ = (context, purpose)\\n            return candidate_provider_ids\\n\\n        def get_blocked_model_keys(self, *, context, purpose):\\n            _ = (context, purpose)\\n            return {\\\"openai::llm::gpt-blocked\\\"}\\n\\n    snapshot = _BlockingPolicy().resolve(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        candidate_provider_ids=frozenset({\\\"openai\\\"}),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n\\n    assert snapshot.blocked_model_keys == frozenset({\\\"openai::llm::gpt-blocked\\\"})\\n    assert not snapshot.allows_model(\\\"OpenAI\\\", \\\"gpt-blocked\\\", model_type=\\\"llm\\\")\\n\\n\\ndef test_default_service_surfaces_bundle_blocked_model_keys():\\n    bundle_service = PolicyBundleService()\\n    bundle_service.publish(\\n        PolicyBundleSnapshot(\\n            revision=1,\\n            initialized=True,\\n            source=\\\"api\\\",\\n            blocked_model_keys=frozenset({\\\"openai::gpt-blocked\\\"}),\\n            content_hash=\\\"0\\\" * 64,\\n        )\\n    )\\n    service = ModelProviderPolicyService(policy_bundle_service=bundle_service)\\n\\n    snapshot = service.resolve(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        candidate_provider_ids=frozenset({\\\"openai\\\"}),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n\\n    assert snapshot.allows(\\\"OpenAI\\\")\\n    assert not snapshot.allows_model(\\\"OpenAI\\\", \\\"gpt-blocked\\\", model_type=\\\"llm\\\")\\n    assert snapshot.allows_model(\\\"OpenAI\\\", \\\"gpt-ok\\\", model_type=\\\"llm\\\")\\n\\n\\ndef test_bundle_content_hash_is_stable_when_no_models_are_blocked():\\n    legacy_hash = policy_bundle_content_hash(\\n        approved_provider_ids={\\\"openai\\\"},\\n        blocked_component_keys={\\\"OldComponent\\\"},\\n        blocked_template_keys={\\\"old-template\\\"},\\n    )\\n    explicit_empty_hash = policy_bundle_content_hash(\\n        approved_provider_ids={\\\"openai\\\"},\\n        blocked_component_keys={\\\"OldComponent\\\"},\\n        blocked_template_keys={\\\"old-template\\\"},\\n        blocked_model_keys=(),\\n    )\\n    blocking_hash = policy_bundle_content_hash(\\n        approved_provider_ids={\\\"openai\\\"},\\n        blocked_component_keys={\\\"OldComponent\\\"},\\n        blocked_template_keys={\\\"old-template\\\"},\\n        blocked_model_keys={\\\"openai::gpt-blocked\\\"},\\n    )\\n\\n    assert legacy_hash == explicit_empty_hash\\n    assert blocking_hash != legacy_hash\\n\\n\\ndef test_normalize_blocked_model_key_canonicalizes_provider_segment():\\n    from lfx.services.model_provider_policy import normalize_blocked_model_key\\n\\n    assert normalize_blocked_model_key(\\\"bare-model\\\") == \\\"bare-model\\\"\\n    assert normalize_blocked_model_key(\\\"OpenAI::gpt-4o\\\") == \\\"openai::gpt-4o\\\"\\n    assert normalize_blocked_model_key(\\\" OpenAI :: gpt-4o \\\") == \\\"openai::gpt-4o\\\"\\n    assert normalize_blocked_model_key(\\\"OpenAI::llm::gpt-4o\\\") == \\\"openai::llm::gpt-4o\\\"\\n    # A non-typed second segment is part of one model name containing the separator.\\n    assert normalize_blocked_model_key(\\\"OpenAI::my::deployment\\\") == \\\"openai::my::deployment\\\"\\n    for invalid in (\\\"\\\", \\\"  \\\", \\\"::gpt-4o\\\", \\\"OpenAI::\\\", \\\"OpenAI::llm::\\\"):\\n        with pytest.raises(ValueError, match=\\\"Blocked-model key\\\"):\\n            normalize_blocked_model_key(invalid)\\n\\n\\ndef test_runtime_denies_blocked_model_before_credential_resolution(monkeypatch):\\n    credential_lookup_called = False\\n\\n    def _credential_lookup(*_args, **_kwargs):\\n        nonlocal credential_lookup_called\\n        credential_lookup_called = True\\n        return \\\"key\\\"\\n\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\", _credential_lookup)\\n\\n    with pytest.raises(ModelProviderPolicyError) as exc_info:\\n        get_llm(\\n            [{\\\"name\\\": \\\"claude-blocked\\\", \\\"provider\\\": \\\"Anthropic\\\", \\\"metadata\\\": {}}],\\n            user_id=\\\"user-1\\\",\\n            provider_policy=_snapshot_with_blocked(\\\"anthropic::llm::claude-blocked\\\"),\\n        )\\n\\n    assert exc_info.value.code == \\\"policy_blocked\\\"\\n    assert exc_info.value.model_name == \\\"claude-blocked\\\"\\n    assert credential_lookup_called is False\\n\\n\\ndef test_embedding_runtime_denies_blocked_model_before_credential_resolution(monkeypatch):\\n    credential_lookup_called = False\\n\\n    def _credential_lookup(*_args, **_kwargs):\\n        nonlocal credential_lookup_called\\n        credential_lookup_called = True\\n        return \\\"key\\\"\\n\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\", _credential_lookup)\\n\\n    with pytest.raises(ModelProviderPolicyError) as exc_info:\\n        get_embeddings(\\n            [{\\\"name\\\": \\\"embed-blocked\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}],\\n            user_id=\\\"user-1\\\",\\n            provider_policy=_snapshot_with_blocked(\\\"openai::embeddings::embed-blocked\\\"),\\n        )\\n\\n    assert exc_info.value.code == \\\"policy_blocked\\\"\\n    assert exc_info.value.model_name == \\\"embed-blocked\\\"\\n    assert credential_lookup_called is False\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"option_builder\\\", \\\"model_type\\\", \\\"blocked_key\\\"),\\n    [\\n        (\\\"get_language_model_options\\\", \\\"llm\\\", \\\"openai::llm::gpt-blocked\\\"),\\n        (\\\"get_language_model_options\\\", \\\"llm\\\", \\\"openai::gpt-blocked\\\"),\\n        (\\\"get_language_model_options\\\", \\\"llm\\\", \\\"gpt-blocked\\\"),\\n        (\\\"get_embedding_model_options\\\", \\\"embeddings\\\", \\\"openai::embeddings::gpt-blocked\\\"),\\n    ],\\n)\\ndef test_model_options_hide_blocked_models(option_builder, model_type, blocked_key):\\n    from lfx.base.models.unified_models import model_catalog\\n\\n    catalog = [\\n        {\\n            \\\"provider\\\": \\\"OpenAI\\\",\\n            \\\"icon\\\": \\\"OpenAI\\\",\\n            \\\"models\\\": [\\n                {\\\"model_name\\\": \\\"gpt-blocked\\\", \\\"metadata\\\": {\\\"default\\\": True, \\\"model_type\\\": model_type}},\\n                {\\\"model_name\\\": \\\"gpt-visible\\\", \\\"metadata\\\": {\\\"default\\\": True, \\\"model_type\\\": model_type}},\\n            ],\\n        },\\n    ]\\n    policy = _snapshot_with_blocked(blocked_key)\\n\\n    with (\\n        patch.object(model_catalog, \\\"get_unified_models_detailed\\\", return_value=catalog),\\n        patch.object(model_catalog, \\\"_get_model_status\\\", new=AsyncMock(return_value=(set(), set()))),\\n        patch.object(\\n            model_catalog,\\n            \\\"_fetch_enabled_providers_for_user\\\",\\n            new=AsyncMock(return_value={\\\"OpenAI\\\"}),\\n        ),\\n        patch.object(model_catalog, \\\"replace_with_live_models\\\", side_effect=lambda *_a, **_k: None),\\n        patch.object(model_catalog, \\\"inject_custom_enabled_models\\\", side_effect=lambda *_a, **_k: None),\\n    ):\\n        options = getattr(model_catalog, option_builder)(\\n            user_id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n            provider_policy=policy,\\n        )\\n\\n    assert {(option[\\\"provider\\\"], option[\\\"name\\\"]) for option in options} == {(\\\"OpenAI\\\", \\\"gpt-visible\\\")}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1abe63ed778002b988cf5000f623fa78b4cd6e0f8efe44b32892b7069cfd6fb8\",\"content\":\"\\\"\\\"\\\"Tests for settings services.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_agentic_variables_gate.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"161345a50228cd07df34eb8a8070784d2bb6a8fffba0f102d9157794e9cca170\",\"content\":\"\\\"\\\"\\\"The agentic global variables must follow the `agentic_experience` gate.\\n\\n`variables_to_get_from_environment` is populated by a field validator, which cannot read the\\nsibling `agentic_experience` field and therefore re-reads `LANGFLOW_AGENTIC_EXPERIENCE` from the\\nenvironment. These tests pin the two defaults together: a drift between them makes the agentic\\nvariables disagree with the setting -- the shipped code once read the env with a \\\"true\\\" default\\nwhile the field said False, so FLOW_ID / COMPONENT_ID / FIELD_NAME / ASTRA_TOKEN were imported\\ninto a deployment whose settings reported the Assistant off.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.services.settings.base import Settings\\nfrom lfx.services.settings.constants import AGENTIC_VARIABLES, VARIABLES_TO_GET_FROM_ENVIRONMENT\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _clear_agentic_env(monkeypatch):\\n    monkeypatch.delenv(\\\"LANGFLOW_AGENTIC_EXPERIENCE\\\", raising=False)\\n\\n\\ndef test_should_enable_the_assistant_by_default():\\n    \\\"\\\"\\\"The Assistant is the primary way into the product; opt-in would hide it behind an env var.\\\"\\\"\\\"\\n    settings = Settings()\\n\\n    assert settings.agentic_experience is True\\n\\n\\ndef test_should_import_agentic_variables_by_default():\\n    settings = Settings()\\n\\n    assert set(AGENTIC_VARIABLES) <= set(settings.variables_to_get_from_environment)\\n\\n\\ndef test_should_import_agentic_variables_when_experience_is_explicitly_enabled(monkeypatch):\\n    monkeypatch.setenv(\\\"LANGFLOW_AGENTIC_EXPERIENCE\\\", \\\"true\\\")\\n\\n    settings = Settings()\\n\\n    assert settings.agentic_experience is True\\n    assert set(AGENTIC_VARIABLES) <= set(settings.variables_to_get_from_environment)\\n\\n\\ndef test_should_not_import_agentic_variables_when_experience_is_explicitly_disabled(monkeypatch):\\n    monkeypatch.setenv(\\\"LANGFLOW_AGENTIC_EXPERIENCE\\\", \\\"false\\\")\\n\\n    settings = Settings()\\n\\n    assert settings.agentic_experience is False\\n    assert not set(AGENTIC_VARIABLES) & set(settings.variables_to_get_from_environment)\\n\\n\\n@pytest.mark.parametrize(\\\"enabled\\\", [\\\"true\\\", \\\"false\\\"])\\ndef test_should_always_keep_the_baseline_environment_variables(monkeypatch, enabled):\\n    monkeypatch.setenv(\\\"LANGFLOW_AGENTIC_EXPERIENCE\\\", enabled)\\n\\n    settings = Settings()\\n\\n    assert set(VARIABLES_TO_GET_FROM_ENVIRONMENT) <= set(settings.variables_to_get_from_environment)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_allow_components_paths_override.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a763de838d3705b965d3144c6ccfb181a22ee0675a248021b6c50cdcd55302b3\",\"content\":\"\\\"\\\"\\\"Tests for allow_components_paths_override enforcement in Settings.\\\"\\\"\\\"\\n\\nimport tempfile\\n\\nfrom lfx.services.settings.base import Settings\\n\\n\\ndef _clear_env(monkeypatch):\\n    for var in (\\n        \\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS\\\",\\n        \\\"LANGFLOW_ALLOW_COMPONENTS_PATHS_OVERRIDE\\\",\\n        \\\"LANGFLOW_COMPONENTS_PATH\\\",\\n        \\\"LANGFLOW_COMPONENTS_INDEX_PATH\\\",\\n    ):\\n        monkeypatch.delenv(var, raising=False)\\n\\n\\ndef test_defaults_are_permissive(monkeypatch):\\n    _clear_env(monkeypatch)\\n    settings = Settings()\\n    assert settings.allow_custom_components is True\\n    assert settings.allow_components_paths_override is True\\n\\n\\ndef test_env_paths_bypass_when_override_true(monkeypatch):\\n    \\\"\\\"\\\"Existing behavior: env-var paths act as an allow-list even when custom is False.\\\"\\\"\\\"\\n    _clear_env(monkeypatch)\\n    with tempfile.TemporaryDirectory() as tmp:\\n        monkeypatch.setenv(\\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS\\\", \\\"false\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_ALLOW_COMPONENTS_PATHS_OVERRIDE\\\", \\\"true\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_COMPONENTS_PATH\\\", tmp)\\n        monkeypatch.setenv(\\\"LANGFLOW_COMPONENTS_INDEX_PATH\\\", \\\"/nonexistent/index.json\\\")\\n\\n        settings = Settings()\\n        assert tmp in settings.components_path\\n        assert settings.components_index_path == \\\"/nonexistent/index.json\\\"\\n\\n\\ndef test_env_paths_stripped_when_override_false(monkeypatch):\\n    \\\"\\\"\\\"When both flags are off, env-var paths must not bypass the restriction.\\\"\\\"\\\"\\n    _clear_env(monkeypatch)\\n    with tempfile.TemporaryDirectory() as tmp:\\n        monkeypatch.setenv(\\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS\\\", \\\"false\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_ALLOW_COMPONENTS_PATHS_OVERRIDE\\\", \\\"false\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_COMPONENTS_PATH\\\", tmp)\\n        monkeypatch.setenv(\\\"LANGFLOW_COMPONENTS_INDEX_PATH\\\", \\\"/nonexistent/index.json\\\")\\n\\n        settings = Settings()\\n        assert tmp not in settings.components_path\\n        assert settings.components_index_path is None\\n\\n\\ndef test_override_false_has_no_effect_when_custom_allowed(monkeypatch):\\n    \\\"\\\"\\\"If allow_custom_components is True, the override flag is a no-op \u2014 nothing to bypass.\\\"\\\"\\\"\\n    _clear_env(monkeypatch)\\n    with tempfile.TemporaryDirectory() as tmp:\\n        monkeypatch.setenv(\\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS\\\", \\\"true\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_ALLOW_COMPONENTS_PATHS_OVERRIDE\\\", \\\"false\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_COMPONENTS_PATH\\\", tmp)\\n        monkeypatch.setenv(\\\"LANGFLOW_COMPONENTS_INDEX_PATH\\\", \\\"/nonexistent/index.json\\\")\\n\\n        settings = Settings()\\n        assert tmp in settings.components_path\\n        assert settings.components_index_path == \\\"/nonexistent/index.json\\\"\\n\\n\\ndef test_index_path_preserved_when_env_var_unset(monkeypatch):\\n    \\\"\\\"\\\"The index path is only stripped when it came from LANGFLOW_COMPONENTS_INDEX_PATH.\\n\\n    If that env var is unset, the enforcer must not touch components_index_path even\\n    when both flags are off.\\n    \\\"\\\"\\\"\\n    _clear_env(monkeypatch)\\n    monkeypatch.setenv(\\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS\\\", \\\"false\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_ALLOW_COMPONENTS_PATHS_OVERRIDE\\\", \\\"false\\\")\\n\\n    settings = Settings()\\n    # No env var set, so the default (built-in index) must be left intact.\\n    assert settings.components_index_path is None\\n\\n\\ndef test_multi_path_env_var_stripped_when_override_false(monkeypatch):\\n    \\\"\\\"\\\"Comma-separated LANGFLOW_COMPONENTS_PATH entries are each stripped when override is off.\\\"\\\"\\\"\\n    _clear_env(monkeypatch)\\n    with tempfile.TemporaryDirectory() as tmp1, tempfile.TemporaryDirectory() as tmp2:\\n        monkeypatch.setenv(\\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS\\\", \\\"false\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_ALLOW_COMPONENTS_PATHS_OVERRIDE\\\", \\\"false\\\")\\n        monkeypatch.setenv(\\\"LANGFLOW_COMPONENTS_PATH\\\", f\\\"{tmp1},{tmp2}\\\")\\n\\n        settings = Settings()\\n        assert tmp1 not in settings.components_path\\n        assert tmp2 not in settings.components_path\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_background_scaled_settings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"68f5ead35149d05af66d9fe4857b3380b423f0a09f2ae8544087b6649f80fca8\",\"content\":\"\\\"\\\"\\\"Scaled-backend settings: test-redis URL + backend selection follows job_queue_type.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom lfx.services.settings.base import Settings\\n\\n\\ndef test_test_redis_url_defaults_none():\\n    settings = Settings()\\n    assert settings.test_redis_url is None\\n\\n\\ndef test_test_redis_url_reads_env(monkeypatch):\\n    monkeypatch.setenv(\\\"LANGFLOW_TEST_REDIS_URL\\\", \\\"redis://localhost:6379/15\\\")\\n    settings = Settings()\\n    assert settings.test_redis_url == \\\"redis://localhost:6379/15\\\"\\n\\n\\ndef test_scaled_backend_follows_job_queue_type(monkeypatch):\\n    # redis job_queue_type => scaled background backend is selected.\\n    # Settings reads job_queue_type from the env (CustomSource drops init kwargs),\\n    # so drive the selection through LANGFLOW_JOB_QUEUE_TYPE the way deploys do.\\n    monkeypatch.setenv(\\\"LANGFLOW_JOB_QUEUE_TYPE\\\", \\\"redis\\\")\\n    assert Settings().background_backend_is_scaled is True\\n\\n    monkeypatch.setenv(\\\"LANGFLOW_JOB_QUEUE_TYPE\\\", \\\"asyncio\\\")\\n    assert Settings().background_backend_is_scaled is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_background_settings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"525a5a12238ce65955be431d7a672fbda026fbf89c17614549c46fd23c6f30c4\",\"content\":\"\\\"\\\"\\\"Background-execution settings defaults and env override.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom lfx.services.settings.base import Settings\\n\\n\\ndef test_background_max_concurrency_default():\\n    settings = Settings()\\n    assert settings.background_max_concurrency == 5\\n\\n\\ndef test_background_job_timeout_default_is_none():\\n    settings = Settings()\\n    assert settings.background_job_timeout is None\\n\\n\\ndef test_background_max_concurrency_env_override(monkeypatch):\\n    monkeypatch.setenv(\\\"LANGFLOW_BACKGROUND_MAX_CONCURRENCY\\\", \\\"12\\\")\\n    settings = Settings()\\n    assert settings.background_max_concurrency == 12\\n\\n\\ndef test_background_job_timeout_env_override(monkeypatch):\\n    monkeypatch.setenv(\\\"LANGFLOW_BACKGROUND_JOB_TIMEOUT\\\", \\\"600\\\")\\n    settings = Settings()\\n    assert settings.background_job_timeout == 600\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_event_delivery_multi_worker_warning.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"13399bf17a4b110e8163455e7974a2f9f8ed22f60822dbd07f7730e1bb6de36f\",\"content\":\"\\\"\\\"\\\"Tests for the multi-worker fallback in Settings.set_event_delivery.\\n\\nA deployment that sets ``workers > 1`` without configuring a Redis-backed\\njob queue cannot deliver ``polling`` or ``streaming`` events across workers\\n(events live in the in-process queue of whichever worker started the\\nbuild).  The validator silently flips event_delivery to ``direct`` in that\\ncase \u2014 but the log message must spell out the requested mode, the forced\\nfallback, and how to keep the original mode (LANGFLOW_JOB_QUEUE_TYPE=redis)\\nso a user diagnosing missing events can fix it without spelunking source.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.services.settings.base import Settings\\n\\nif TYPE_CHECKING:\\n    import pytest\\n\\n\\ndef _isolate_env(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"Clear all env vars the validator inspects so tests are deterministic.\\\"\\\"\\\"\\n    for name in (\\\"LANGFLOW_WORKERS\\\", \\\"LANGFLOW_JOB_QUEUE_TYPE\\\", \\\"LANGFLOW_EVENT_DELIVERY\\\"):\\n        monkeypatch.delenv(name, raising=False)\\n\\n\\ndef _capture_warnings(monkeypatch: pytest.MonkeyPatch) -> list[str]:\\n    \\\"\\\"\\\"Capture warnings the settings validator emits.\\n\\n    Settings uses ``lfx.log.logger.logger`` (a structlog BoundLogger that may\\n    be filtered at the configured log level).  ``set_event_delivery`` lives in\\n    the ``RuntimeSettings`` mixin, so replace the module-level ``logger`` symbol\\n    in ``lfx.services.settings.groups.runtime`` with a tiny stand-in that records\\n    ``warning`` calls so the test inspects exactly the messages the validator\\n    emits, regardless of structlog's filter level.\\n    \\\"\\\"\\\"\\n    captured: list[str] = []\\n\\n    class _Recorder:\\n        def warning(self, msg: str, *args: object, **_kwargs: object) -> None:\\n            captured.append(msg % args if args else msg)\\n\\n        def __getattr__(self, _name: str):  # pragma: no cover - swallow other levels\\n            return lambda *_a, **_k: None\\n\\n    import lfx.services.settings.groups.runtime as settings_runtime\\n\\n    monkeypatch.setattr(settings_runtime, \\\"logger\\\", _Recorder())\\n    return captured\\n\\n\\ndef test_multi_worker_without_redis_forces_direct_delivery(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"With workers=2 and the in-memory job queue, polling is rewritten to direct.\\\"\\\"\\\"\\n    _isolate_env(monkeypatch)\\n    monkeypatch.setenv(\\\"LANGFLOW_WORKERS\\\", \\\"2\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_JOB_QUEUE_TYPE\\\", \\\"asyncio\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_EVENT_DELIVERY\\\", \\\"polling\\\")\\n\\n    warnings = _capture_warnings(monkeypatch)\\n    settings = Settings()\\n\\n    assert settings.event_delivery == \\\"direct\\\"\\n    combined = \\\" \\\".join(warnings)\\n    # The warning must name BOTH the requested mode and the env var users need\\n    # to set to keep that mode \u2014 without these, the operator has no way to\\n    # connect a missing-events symptom to the root cause.\\n    assert \\\"polling\\\" in combined\\n    assert \\\"LANGFLOW_JOB_QUEUE_TYPE\\\" in combined\\n\\n\\ndef test_multi_worker_with_redis_keeps_requested_delivery(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"With workers=2 and job_queue_type=redis, the requested delivery is preserved.\\\"\\\"\\\"\\n    _isolate_env(monkeypatch)\\n    monkeypatch.setenv(\\\"LANGFLOW_WORKERS\\\", \\\"2\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_JOB_QUEUE_TYPE\\\", \\\"redis\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_EVENT_DELIVERY\\\", \\\"streaming\\\")\\n\\n    settings = Settings()\\n\\n    assert settings.event_delivery == \\\"streaming\\\"\\n\\n\\ndef test_single_worker_keeps_requested_delivery(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"The override only applies when workers > 1 \u2014 single-worker setups are left alone.\\\"\\\"\\\"\\n    _isolate_env(monkeypatch)\\n    monkeypatch.setenv(\\\"LANGFLOW_WORKERS\\\", \\\"1\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_JOB_QUEUE_TYPE\\\", \\\"asyncio\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_EVENT_DELIVERY\\\", \\\"polling\\\")\\n\\n    settings = Settings()\\n\\n    assert settings.event_delivery == \\\"polling\\\"\\n\\n\\ndef test_multi_worker_no_warning_when_already_direct(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"When the operator already set event_delivery=direct, no warning fires.\\n\\n    The warning exists to flag a silent override; if the configured value is\\n    already the forced fallback, there is nothing to flag.\\n    \\\"\\\"\\\"\\n    _isolate_env(monkeypatch)\\n    monkeypatch.setenv(\\\"LANGFLOW_WORKERS\\\", \\\"2\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_JOB_QUEUE_TYPE\\\", \\\"asyncio\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_EVENT_DELIVERY\\\", \\\"direct\\\")\\n\\n    warnings = _capture_warnings(monkeypatch)\\n    settings = Settings()\\n\\n    assert settings.event_delivery == \\\"direct\\\"\\n    combined = \\\" \\\".join(warnings)\\n    assert \\\"LANGFLOW_JOB_QUEUE_TYPE\\\" not in combined\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_kb_allowed_folder_roots.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5230843551aa2b3296a0f7dd5ae510d25e0368fd661f6e490425a1b63ab028fa\",\"content\":\"\\\"\\\"\\\"Tests for the server-owned Knowledge Base folder security settings.\\n\\nThe folder-ingestion route (``POST /{kb_name}/ingest/folder``) gates which\\nserver-side directories it may read via ``settings.kb_allowed_folder_roots``.\\nBefore this field was declared on the model, the attribute did not exist:\\nreading it raised ``AttributeError`` (re-raised by the route as a generic\\nHTTP 500), and ``LANGFLOW_KB_ALLOWED_FOLDER_ROOTS`` bound to nothing because\\n``model_config`` uses ``extra=\\\"ignore\\\"`` \u2014 so the allow-list could never be\\nconfigured and the endpoint was unusable.\\n\\nThese tests exercise the *real* Settings model (the endpoint unit tests inject\\na mocked settings object, so they never caught the missing root field). The\\nfile-size tests likewise pin the operator-owned default and environment binding.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.services.settings.base import Settings\\nfrom pydantic import ValidationError\\n\\n\\ndef test_kb_allowed_folder_roots_field_is_declared(monkeypatch):\\n    \\\"\\\"\\\"The field must exist on the model \u2014 guards against the 1.10.0 regression.\\\"\\\"\\\"\\n    monkeypatch.delenv(\\\"LANGFLOW_KB_ALLOWED_FOLDER_ROOTS\\\", raising=False)\\n    settings = Settings()\\n    # Accessing the attribute must not raise AttributeError.\\n    assert hasattr(settings, \\\"kb_allowed_folder_roots\\\")\\n\\n\\ndef test_kb_allowed_folder_roots_defaults_to_empty_list(monkeypatch):\\n    \\\"\\\"\\\"With no env var configured the allow-list is empty (operators opt in).\\\"\\\"\\\"\\n    monkeypatch.delenv(\\\"LANGFLOW_KB_ALLOWED_FOLDER_ROOTS\\\", raising=False)\\n    settings = Settings()\\n    assert settings.kb_allowed_folder_roots == []\\n\\n\\ndef test_kb_allowed_folder_roots_binds_single_value_from_env(monkeypatch):\\n    \\\"\\\"\\\"A single directory binds from the LANGFLOW_-prefixed env var.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_KB_ALLOWED_FOLDER_ROOTS\\\", \\\"/srv/docs\\\")\\n    settings = Settings()\\n    assert settings.kb_allowed_folder_roots == [\\\"/srv/docs\\\"]\\n\\n\\ndef test_kb_allowed_folder_roots_parses_comma_separated_env(monkeypatch):\\n    \\\"\\\"\\\"Multiple roots are comma-separated, like the other list settings.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_KB_ALLOWED_FOLDER_ROOTS\\\", \\\"/srv/docs,/data/shared\\\")\\n    settings = Settings()\\n    assert settings.kb_allowed_folder_roots == [\\\"/srv/docs\\\", \\\"/data/shared\\\"]\\n\\n\\ndef test_kb_folder_max_file_size_bytes_defaults_to_25_mib(monkeypatch):\\n    monkeypatch.delenv(\\\"LANGFLOW_KB_FOLDER_MAX_FILE_SIZE_BYTES\\\", raising=False)\\n    settings = Settings()\\n    assert settings.kb_folder_max_file_size_bytes == 25 * 1024 * 1024\\n\\n\\ndef test_kb_folder_max_file_size_bytes_binds_from_env(monkeypatch):\\n    monkeypatch.setenv(\\\"LANGFLOW_KB_FOLDER_MAX_FILE_SIZE_BYTES\\\", \\\"1048576\\\")\\n    settings = Settings()\\n    assert settings.kb_folder_max_file_size_bytes == 1_048_576\\n\\n\\ndef test_kb_folder_max_file_size_bytes_must_be_positive(monkeypatch):\\n    monkeypatch.setenv(\\\"LANGFLOW_KB_FOLDER_MAX_FILE_SIZE_BYTES\\\", \\\"0\\\")\\n    with pytest.raises(ValidationError):\\n        Settings()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_mcp_composer.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8c02be0f1d27f094e6d21a8965a4f4ff83c0363545c4e8ee29a9c613226e9c5e\",\"content\":\"\\\"\\\"\\\"Unit tests for MCP Composer Service port management and process killing.\\\"\\\"\\\"\\n\\nimport asyncio\\nimport contextlib\\nimport socket\\nfrom pathlib import Path\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom lfx.services.mcp_composer.service import (\\n    COMPOSER_BACKEND_AUTH_HEADER,\\n    MCPComposerPortError,\\n    MCPComposerService,\\n)\\n\\n\\n@pytest.fixture\\ndef mcp_service():\\n    \\\"\\\"\\\"Create an MCP Composer service instance for testing.\\\"\\\"\\\"\\n    return MCPComposerService()\\n\\n\\ndef get_available_local_port() -> int:\\n    \\\"\\\"\\\"Ask the OS for a currently available localhost TCP port.\\\"\\\"\\\"\\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:\\n        sock.bind((\\\"127.0.0.1\\\", 0))\\n        return sock.getsockname()[1]\\n\\n\\nclass TestPortAvailability:\\n    \\\"\\\"\\\"Test port availability checking.\\\"\\\"\\\"\\n\\n    def test_is_port_available_when_free(self, mcp_service):\\n        \\\"\\\"\\\"Test that is_port_available returns True for an available port.\\\"\\\"\\\"\\n        test_port = get_available_local_port()\\n        assert mcp_service._is_port_available(test_port, host=\\\"127.0.0.1\\\") is True\\n\\n    def test_is_port_available_when_in_use(self, mcp_service):\\n        \\\"\\\"\\\"Test that is_port_available returns False when port is in use.\\\"\\\"\\\"\\n        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\\n        try:\\n            sock.bind((\\\"127.0.0.1\\\", 0))\\n            test_port = sock.getsockname()[1]\\n            sock.listen(1)\\n            # Port should now be unavailable\\n            assert mcp_service._is_port_available(test_port, host=\\\"127.0.0.1\\\") is False\\n        finally:\\n            sock.close()\\n\\n\\nclass TestBackendAuthToken:\\n    \\\"\\\"\\\"Test internal Composer-to-Langflow backend authentication config.\\\"\\\"\\\"\\n\\n    def test_backend_auth_member_config_adds_internal_header(self, mcp_service):\\n        project_id = \\\"backend-auth-test\\\"\\n\\n        config = mcp_service._build_backend_auth_member_config(\\n            project_id,\\n            \\\"http://localhost:7860/api/v1/mcp/project/test/streamable\\\",\\n            legacy_sse_url=\\\"http://localhost:7860/api/v1/mcp/project/test/sse\\\",\\n        )\\n\\n        token = mcp_service.get_or_create_backend_auth_token(project_id)\\n        assert mcp_service.validate_backend_auth_token(project_id, token)\\n        assert [entry[\\\"type\\\"] for entry in config] == [\\\"http\\\", \\\"sse\\\"]\\n        assert config[0][\\\"headers\\\"] == {COMPOSER_BACKEND_AUTH_HEADER: token}\\n        assert config[1][\\\"headers\\\"] == {COMPOSER_BACKEND_AUTH_HEADER: token}\\n\\n    @pytest.mark.asyncio\\n    async def test_oauth_startup_uses_config_path_for_backend_auth(self, mcp_service):\\n        project_id = \\\"backend-auth-process-test\\\"\\n        auth_config = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": \\\"9000\\\",\\n            \\\"oauth_server_url\\\": \\\"http://localhost:9000\\\",\\n            \\\"oauth_client_id\\\": \\\"cid\\\",\\n            \\\"oauth_client_secret\\\": \\\"csecret\\\",  # pragma: allowlist secret\\n            \\\"oauth_auth_url\\\": \\\"http://auth\\\",\\n            \\\"oauth_token_url\\\": \\\"http://token\\\",\\n        }\\n\\n        mock_settings = MagicMock()\\n        mock_settings.settings.mcp_composer_version = \\\"==0.1.0.8.10\\\"\\n        mock_process = MagicMock(pid=2222, poll=MagicMock(return_value=None))\\n\\n        with (\\n            patch(\\\"lfx.services.mcp_composer.service.get_settings_service\\\", return_value=mock_settings),\\n            patch.object(\\n                mcp_service,\\n                \\\"_write_backend_auth_member_config\\\",\\n                return_value=Path(\\\"/tmp/mcp-composer-test-config.json\\\"),\\n            ) as mock_write_config,\\n            patch(\\\"subprocess.Popen\\\", return_value=mock_process) as mock_popen,\\n            patch.object(mcp_service, \\\"_is_port_available\\\", return_value=False),\\n        ):\\n            await mcp_service._start_project_composer_process(\\n                project_id=project_id,\\n                host=\\\"localhost\\\",\\n                port=9000,\\n                streamable_http_url=\\\"http://test/mcp\\\",\\n                auth_config=auth_config,\\n                max_startup_checks=1,\\n                startup_delay=0.01,\\n                legacy_sse_url=\\\"http://test/sse\\\",\\n            )\\n\\n        cmd = mock_popen.call_args[0][0]\\n        assert \\\"--config_path\\\" in cmd\\n        assert \\\"--endpoint\\\" not in cmd\\n        assert \\\"--sse-url\\\" not in cmd\\n        assert COMPOSER_BACKEND_AUTH_HEADER not in cmd\\n        mock_write_config.assert_called_once_with(\\n            project_id,\\n            \\\"http://test/mcp\\\",\\n            legacy_sse_url=\\\"http://test/sse\\\",\\n        )\\n\\n\\nclass TestKillProcessOnPort:\\n    \\\"\\\"\\\"Test process killing functionality.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_process_on_port_no_process(self, mcp_service):\\n        \\\"\\\"\\\"Test that _kill_process_on_port returns False when no process is found.\\\"\\\"\\\"\\n        with patch(\\\"asyncio.to_thread\\\") as mock_to_thread:\\n            # Mock lsof returning no processes\\n            mock_result = MagicMock()\\n            mock_result.returncode = 1  # lsof returns 1 when no matches\\n            mock_result.stdout = \\\"\\\"\\n            mock_result.stderr = \\\"\\\"\\n            mock_to_thread.return_value = mock_result\\n\\n            result = await mcp_service._kill_process_on_port(9999)\\n            assert result is False\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_process_on_port_success(self, mcp_service):\\n        \\\"\\\"\\\"Test that _kill_process_on_port successfully kills a process.\\\"\\\"\\\"\\n        with patch(\\\"asyncio.to_thread\\\") as mock_to_thread:\\n            # Mock lsof returning a PID\\n            mock_lsof_result = MagicMock()\\n            mock_lsof_result.returncode = 0\\n            mock_lsof_result.stdout = \\\"12345\\\\n\\\"\\n            mock_lsof_result.stderr = \\\"\\\"\\n\\n            # Mock kill command succeeding\\n            mock_kill_result = MagicMock()\\n            mock_kill_result.returncode = 0\\n            mock_kill_result.stdout = \\\"\\\"\\n            mock_kill_result.stderr = \\\"\\\"\\n\\n            # Set up side effects for two calls: lsof, then kill\\n            mock_to_thread.side_effect = [mock_lsof_result, mock_kill_result]\\n\\n            result = await mcp_service._kill_process_on_port(9000)\\n            assert result is True\\n            assert mock_to_thread.call_count == 2\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_process_on_port_multiple_pids(self, mcp_service):\\n        \\\"\\\"\\\"Test that _kill_process_on_port handles multiple PIDs.\\\"\\\"\\\"\\n        with patch(\\\"asyncio.to_thread\\\") as mock_to_thread:\\n            # Mock lsof returning multiple PIDs\\n            mock_lsof_result = MagicMock()\\n            mock_lsof_result.returncode = 0\\n            mock_lsof_result.stdout = \\\"12345\\\\n67890\\\\n\\\"\\n            mock_lsof_result.stderr = \\\"\\\"\\n\\n            # Mock kill command succeeding for first PID\\n            mock_kill_result = MagicMock()\\n            mock_kill_result.returncode = 0\\n\\n            mock_to_thread.side_effect = [mock_lsof_result, mock_kill_result]\\n\\n            result = await mcp_service._kill_process_on_port(9000)\\n            assert result is True\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_process_on_port_kill_fails(self, mcp_service):\\n        \\\"\\\"\\\"Test that _kill_process_on_port handles kill command failure.\\\"\\\"\\\"\\n        with patch(\\\"asyncio.to_thread\\\") as mock_to_thread:\\n            # Mock lsof returning a PID\\n            mock_lsof_result = MagicMock()\\n            mock_lsof_result.returncode = 0\\n            mock_lsof_result.stdout = \\\"12345\\\\n\\\"\\n            mock_lsof_result.stderr = \\\"\\\"\\n\\n            # Mock kill command failing\\n            mock_kill_result = MagicMock()\\n            mock_kill_result.returncode = 1\\n\\n            mock_to_thread.side_effect = [mock_lsof_result, mock_kill_result]\\n\\n            result = await mcp_service._kill_process_on_port(9000)\\n            assert result is False\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_process_on_port_exception_handling(self, mcp_service):\\n        \\\"\\\"\\\"Test that _kill_process_on_port handles exceptions gracefully.\\\"\\\"\\\"\\n        with patch(\\\"asyncio.to_thread\\\", side_effect=Exception(\\\"Test error\\\")):\\n            result = await mcp_service._kill_process_on_port(9000)\\n            assert result is False\\n\\n\\nclass TestAuthConfigChanges:\\n    \\\"\\\"\\\"Test authentication configuration change detection.\\\"\\\"\\\"\\n\\n    def test_has_auth_config_changed_port_changed(self, mcp_service):\\n        \\\"\\\"\\\"Test that port change is detected.\\\"\\\"\\\"\\n        existing_auth = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": \\\"9000\\\",\\n            \\\"oauth_server_url\\\": \\\"http://localhost:9000\\\",\\n        }\\n        new_auth = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": \\\"9001\\\",\\n            \\\"oauth_server_url\\\": \\\"http://localhost:9001\\\",\\n        }\\n\\n        assert mcp_service._has_auth_config_changed(existing_auth, new_auth) is True\\n\\n    def test_has_auth_config_changed_no_change(self, mcp_service):\\n        \\\"\\\"\\\"Test that identical configs are not detected as changed.\\\"\\\"\\\"\\n        existing_auth = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": \\\"9000\\\",\\n            \\\"oauth_server_url\\\": \\\"http://localhost:9000\\\",\\n        }\\n        new_auth = existing_auth.copy()\\n\\n        assert mcp_service._has_auth_config_changed(existing_auth, new_auth) is False\\n\\n    def test_has_auth_config_changed_auth_type_changed(self, mcp_service):\\n        \\\"\\\"\\\"Test that auth type change is detected.\\\"\\\"\\\"\\n        existing_auth = {\\\"auth_type\\\": \\\"oauth\\\", \\\"oauth_port\\\": \\\"9000\\\"}\\n        new_auth = {\\\"auth_type\\\": \\\"apikey\\\", \\\"api_key\\\": \\\"test_key\\\"}\\n\\n        assert mcp_service._has_auth_config_changed(existing_auth, new_auth) is True\\n\\n    def test_has_auth_config_changed_both_none(self, mcp_service):\\n        \\\"\\\"\\\"Test that two None configs are not detected as changed.\\\"\\\"\\\"\\n        assert mcp_service._has_auth_config_changed(None, None) is False\\n\\n    def test_has_auth_config_changed_one_none(self, mcp_service):\\n        \\\"\\\"\\\"Test that changing from None to config is detected.\\\"\\\"\\\"\\n        existing_auth = None\\n        new_auth = {\\\"auth_type\\\": \\\"oauth\\\", \\\"oauth_port\\\": \\\"9000\\\"}\\n\\n        assert mcp_service._has_auth_config_changed(existing_auth, new_auth) is True\\n\\n\\nclass TestPortChangeHandling:\\n    \\\"\\\"\\\"Test handling of port changes in composer restart.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_port_change_triggers_restart(self, mcp_service):\\n        \\\"\\\"\\\"Test that changing ports triggers a restart via auth config change detection.\\\"\\\"\\\"\\n        project_id = \\\"test-project\\\"\\n        old_port = 9000\\n        new_port = 9001\\n\\n        # Set up existing composer\\n        mock_process = MagicMock(poll=MagicMock(return_value=None), pid=12345)\\n        mcp_service.project_composers[project_id] = {\\n            \\\"process\\\": mock_process,\\n            \\\"host\\\": \\\"localhost\\\",\\n            \\\"port\\\": old_port,\\n            \\\"streamable_http_url\\\": \\\"http://test\\\",\\n            \\\"legacy_sse_url\\\": \\\"http://test/sse\\\",\\n            \\\"auth_config\\\": {\\n                \\\"auth_type\\\": \\\"oauth\\\",\\n                \\\"oauth_host\\\": \\\"localhost\\\",\\n                \\\"oauth_port\\\": str(old_port),\\n                \\\"oauth_server_url\\\": f\\\"http://localhost:{old_port}\\\",\\n                \\\"oauth_client_id\\\": \\\"test\\\",\\n                \\\"oauth_client_secret\\\": \\\"test\\\",\\n                \\\"oauth_auth_url\\\": \\\"http://test\\\",\\n                \\\"oauth_token_url\\\": \\\"http://test\\\",\\n            },\\n        }\\n        mcp_service._port_to_project[old_port] = project_id\\n        mcp_service._pid_to_project[12345] = project_id\\n\\n        new_auth_config = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": str(new_port),\\n            \\\"oauth_server_url\\\": f\\\"http://localhost:{new_port}\\\",\\n            \\\"oauth_client_id\\\": \\\"test\\\",\\n            \\\"oauth_client_secret\\\": \\\"test\\\",\\n            \\\"oauth_auth_url\\\": \\\"http://test\\\",\\n            \\\"oauth_token_url\\\": \\\"http://test\\\",\\n        }\\n\\n        with (\\n            patch.object(mcp_service, \\\"_do_stop_project_composer\\\", new=AsyncMock()) as mock_stop,\\n            patch.object(mcp_service, \\\"_is_port_available\\\", return_value=True),\\n            patch.object(mcp_service, \\\"_start_project_composer_process\\\", new=AsyncMock()),\\n        ):\\n            # Initialize locks\\n            mcp_service._start_locks[project_id] = asyncio.Lock()\\n\\n            with contextlib.suppress(Exception):\\n                await mcp_service._do_start_project_composer(\\n                    project_id=project_id,\\n                    streamable_http_url=\\\"http://test\\\",\\n                    auth_config=new_auth_config,\\n                    max_retries=1,\\n                    max_startup_checks=1,\\n                    startup_delay=0.1,\\n                )\\n\\n            # Verify composer was stopped (because config changed)\\n            mock_stop.assert_called_once_with(project_id)\\n\\n    @pytest.mark.asyncio\\n    async def test_port_in_use_by_own_project_triggers_kill(self, mcp_service):\\n        \\\"\\\"\\\"Test that when port is in use by the current project, it kills the process.\\\"\\\"\\\"\\n        project_id = \\\"test-project\\\"\\n        test_port = 9001\\n\\n        # Register the port as owned by this project\\n        mcp_service._port_to_project[test_port] = project_id\\n\\n        auth_config = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": str(test_port),\\n            \\\"oauth_server_url\\\": f\\\"http://localhost:{test_port}\\\",\\n            \\\"oauth_client_id\\\": \\\"test\\\",\\n            \\\"oauth_client_secret\\\": \\\"test\\\",\\n            \\\"oauth_auth_url\\\": \\\"http://test\\\",\\n            \\\"oauth_token_url\\\": \\\"http://test\\\",\\n        }\\n\\n        with (\\n            patch.object(mcp_service, \\\"_is_port_available\\\") as mock_port_check,\\n            patch.object(mcp_service, \\\"_kill_process_on_port\\\", new=AsyncMock(return_value=True)) as mock_kill,\\n        ):\\n            # First check: port is in use, second check after kill: port is free\\n            mock_port_check.side_effect = [False, True]\\n\\n            # Initialize locks\\n            mcp_service._start_locks[project_id] = asyncio.Lock()\\n\\n            with (\\n                patch.object(mcp_service, \\\"_start_project_composer_process\\\", new=AsyncMock()),\\n                contextlib.suppress(Exception),\\n            ):\\n                await mcp_service._do_start_project_composer(\\n                    project_id=project_id,\\n                    streamable_http_url=\\\"http://test\\\",\\n                    auth_config=auth_config,\\n                    max_retries=1,\\n                    max_startup_checks=1,\\n                    startup_delay=0.1,\\n                )\\n\\n            # Verify kill was attempted on own project's port\\n            mock_kill.assert_called_with(test_port)\\n\\n    @pytest.mark.asyncio\\n    async def test_port_in_use_by_unknown_process_raises_error(self, mcp_service):\\n        \\\"\\\"\\\"Test that error is raised when port is in use by unknown process (security).\\\"\\\"\\\"\\n        project_id = \\\"test-project\\\"\\n        test_port = 9001\\n\\n        # Port is NOT tracked (unknown process)\\n        # mcp_service._port_to_project does NOT contain test_port\\n\\n        auth_config = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": str(test_port),\\n            \\\"oauth_server_url\\\": f\\\"http://localhost:{test_port}\\\",\\n            \\\"oauth_client_id\\\": \\\"test\\\",\\n            \\\"oauth_client_secret\\\": \\\"test\\\",\\n            \\\"oauth_auth_url\\\": \\\"http://test\\\",\\n            \\\"oauth_token_url\\\": \\\"http://test\\\",\\n        }\\n\\n        with patch.object(mcp_service, \\\"_is_port_available\\\", return_value=False):  # Port in use\\n            # Initialize locks\\n            mcp_service._start_locks[project_id] = asyncio.Lock()\\n\\n            with pytest.raises(MCPComposerPortError) as exc_info:\\n                await mcp_service._do_start_project_composer(\\n                    project_id=project_id,\\n                    streamable_http_url=\\\"http://test\\\",\\n                    auth_config=auth_config,\\n                    max_retries=1,\\n                    max_startup_checks=1,\\n                    startup_delay=0.1,\\n                )\\n\\n            # New security message: won't kill unknown processes\\n            assert \\\"already in use by another application\\\" in str(exc_info.value)\\n\\n    @pytest.mark.asyncio\\n    async def test_legacy_sse_url_preserved_in_composer_state(self, mcp_service):\\n        \\\"\\\"\\\"Ensure legacy SSE URLs are passed through to the composer process and stored.\\\"\\\"\\\"\\n        project_id = \\\"legacy-project\\\"\\n        auth_config = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": \\\"9100\\\",\\n            \\\"oauth_server_url\\\": \\\"http://localhost:9100\\\",\\n            \\\"oauth_client_id\\\": \\\"legacy\\\",\\n            \\\"oauth_client_secret\\\": \\\"secret\\\",\\n            \\\"oauth_auth_url\\\": \\\"http://auth\\\",\\n            \\\"oauth_token_url\\\": \\\"http://token\\\",\\n        }\\n        legacy_url = \\\"http://test/legacy-sse\\\"\\n        streamable_url = \\\"http://test/streamable\\\"\\n\\n        mcp_service._start_locks[project_id] = asyncio.Lock()\\n\\n        mock_process = MagicMock(pid=4321)\\n        with (\\n            patch.object(mcp_service, \\\"_is_port_available\\\", return_value=True),\\n            patch.object(\\n                mcp_service,\\n                \\\"_start_project_composer_process\\\",\\n                new=AsyncMock(return_value=mock_process),\\n            ) as mock_start,\\n        ):\\n            await mcp_service._do_start_project_composer(\\n                project_id=project_id,\\n                streamable_http_url=streamable_url,\\n                auth_config=auth_config,\\n                max_retries=1,\\n                max_startup_checks=1,\\n                startup_delay=0.1,\\n                legacy_sse_url=legacy_url,\\n            )\\n\\n        mock_start.assert_awaited()\\n        kwargs = mock_start.call_args.kwargs\\n        assert kwargs[\\\"legacy_sse_url\\\"] == legacy_url\\n        assert mcp_service.project_composers[project_id][\\\"legacy_sse_url\\\"] == legacy_url\\n        assert mcp_service.project_composers[project_id][\\\"streamable_http_url\\\"] == streamable_url\\n\\n    @pytest.mark.asyncio\\n    async def test_legacy_sse_url_defaults_when_not_provided(self, mcp_service):\\n        \\\"\\\"\\\"Verify that a default SSE URL is derived when none is supplied.\\\"\\\"\\\"\\n        project_id = \\\"legacy-default\\\"\\n        streamable_url = \\\"http://test/default\\\"\\n        auth_config = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": \\\"9200\\\",\\n            \\\"oauth_server_url\\\": \\\"http://localhost:9200\\\",\\n            \\\"oauth_client_id\\\": \\\"legacy\\\",\\n            \\\"oauth_client_secret\\\": \\\"secret\\\",\\n            \\\"oauth_auth_url\\\": \\\"http://auth\\\",\\n            \\\"oauth_token_url\\\": \\\"http://token\\\",\\n        }\\n\\n        mcp_service._start_locks[project_id] = asyncio.Lock()\\n\\n        mock_process = MagicMock(pid=9876)\\n        with (\\n            patch.object(mcp_service, \\\"_is_port_available\\\", return_value=True),\\n            patch.object(\\n                mcp_service,\\n                \\\"_start_project_composer_process\\\",\\n                new=AsyncMock(return_value=mock_process),\\n            ) as mock_start,\\n        ):\\n            await mcp_service._do_start_project_composer(\\n                project_id=project_id,\\n                streamable_http_url=streamable_url,\\n                auth_config=auth_config,\\n                max_retries=1,\\n                max_startup_checks=1,\\n                startup_delay=0.1,\\n            )\\n\\n        mock_start.assert_awaited()\\n        kwargs = mock_start.call_args.kwargs\\n        assert kwargs[\\\"legacy_sse_url\\\"] == f\\\"{streamable_url}/sse\\\"\\n\\n\\nclass TestOAuthCallbackConfigForwarding:\\n    \\\"\\\"\\\"Test that OAuth callback config is forwarded to process startup unchanged.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_callback_url_forwarded_to_start_process_auth_config(self, mcp_service):\\n        \\\"\\\"\\\"Verify oauth_callback_url is preserved when passed to process startup.\\n\\n        This test patches _start_project_composer_process, so it does not verify\\n        env-var mapping such as OAUTH_CALLBACK_PATH vs OAUTH_CALLBACK_URL. It\\n        only verifies that _do_start_project_composer forwards the callback URL\\n        in auth_config to the process-start method unchanged.\\n        \\\"\\\"\\\"\\n        project_id = \\\"callback-test\\\"\\n        callback = \\\"http://localhost:9000/auth/idaas/callback\\\"\\n        auth_config = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": \\\"9000\\\",\\n            \\\"oauth_server_url\\\": \\\"http://localhost:9000\\\",\\n            \\\"oauth_callback_url\\\": callback,\\n            \\\"oauth_client_id\\\": \\\"cid\\\",\\n            \\\"oauth_client_secret\\\": \\\"csecret\\\",  # pragma: allowlist secret\\n            \\\"oauth_auth_url\\\": \\\"http://auth\\\",\\n            \\\"oauth_token_url\\\": \\\"http://token\\\",\\n            \\\"oauth_mcp_scope\\\": \\\"mcp\\\",\\n            \\\"oauth_provider_scope\\\": \\\"openid\\\",\\n        }\\n\\n        mcp_service._start_locks[project_id] = asyncio.Lock()\\n\\n        mock_process = MagicMock(pid=1111)\\n        with (\\n            patch.object(mcp_service, \\\"_is_port_available\\\", return_value=True),\\n            patch.object(\\n                mcp_service,\\n                \\\"_start_project_composer_process\\\",\\n                new=AsyncMock(return_value=mock_process),\\n            ) as mock_start,\\n        ):\\n            await mcp_service._do_start_project_composer(\\n                project_id=project_id,\\n                streamable_http_url=\\\"http://test/mcp\\\",\\n                auth_config=auth_config,\\n                max_retries=1,\\n                max_startup_checks=1,\\n                startup_delay=0.1,\\n            )\\n\\n        mock_start.assert_awaited()\\n        # auth_config is the 5th positional arg (index 4)\\n        passed_auth = mock_start.call_args[0][4]\\n\\n        # The auth_config should still carry the value under oauth_callback_url.\\n        assert passed_auth[\\\"oauth_callback_url\\\"] == callback\\n\\n    @pytest.mark.asyncio\\n    async def test_callback_url_backwards_compat(self, mcp_service):\\n        \\\"\\\"\\\"Verify legacy oauth_callback_url is promoted and sent as OAUTH_CALLBACK_PATH.\\\"\\\"\\\"\\n        project_id = \\\"compat-test\\\"\\n        callback_url = \\\"http://localhost:9000/auth/callback\\\"\\n        auth_config = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": \\\"9000\\\",\\n            \\\"oauth_server_url\\\": \\\"http://localhost:9000\\\",\\n            \\\"oauth_callback_url\\\": callback_url,\\n            \\\"oauth_client_id\\\": \\\"cid\\\",\\n            \\\"oauth_client_secret\\\": \\\"csecret\\\",  # pragma: allowlist secret\\n            \\\"oauth_auth_url\\\": \\\"http://auth\\\",\\n            \\\"oauth_token_url\\\": \\\"http://token\\\",\\n        }\\n\\n        mock_settings = MagicMock()\\n        mock_settings.settings.mcp_composer_version = \\\"==0.1.0.8.10\\\"\\n\\n        mock_process = MagicMock(pid=2222, poll=MagicMock(return_value=None))\\n\\n        with (\\n            patch(\\\"lfx.services.mcp_composer.service.get_settings_service\\\", return_value=mock_settings),\\n            patch(\\\"subprocess.Popen\\\", return_value=mock_process) as mock_popen,\\n            patch.object(mcp_service, \\\"_is_port_available\\\", return_value=False),\\n        ):\\n            await mcp_service._start_project_composer_process(\\n                project_id=project_id,\\n                host=\\\"localhost\\\",\\n                port=9000,\\n                streamable_http_url=\\\"http://test/mcp\\\",\\n                auth_config=auth_config,\\n                max_startup_checks=1,\\n                startup_delay=0.01,\\n            )\\n\\n        cmd = mock_popen.call_args[0][0]\\n\\n        # Legacy oauth_callback_url should be promoted and sent as OAUTH_CALLBACK_PATH\\n        assert \\\"OAUTH_CALLBACK_PATH\\\" in cmd, f\\\"Expected OAUTH_CALLBACK_PATH in command but got: {cmd}\\\"\\n        idx = cmd.index(\\\"OAUTH_CALLBACK_PATH\\\")\\n        assert cmd[idx + 1] == callback_url\\n\\n    @pytest.mark.asyncio\\n    async def test_callback_url_wins_when_both_callback_fields_are_present(self, mcp_service):\\n        \\\"\\\"\\\"Verify canonical oauth_callback_url takes precedence over deprecated oauth_callback_path.\\\"\\\"\\\"\\n        project_id = \\\"canonical-callback-test\\\"\\n        callback_url = \\\"http://localhost:9000/auth/idaas/callback\\\"\\n        stale_callback_path = \\\"http://localhost:9999/stale/callback\\\"\\n        auth_config = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": \\\"9000\\\",\\n            \\\"oauth_server_url\\\": \\\"http://localhost:9000\\\",\\n            \\\"oauth_callback_url\\\": callback_url,\\n            \\\"oauth_callback_path\\\": stale_callback_path,\\n            \\\"oauth_client_id\\\": \\\"cid\\\",\\n            \\\"oauth_client_secret\\\": \\\"csecret\\\",  # pragma: allowlist secret\\n            \\\"oauth_auth_url\\\": \\\"http://auth\\\",\\n            \\\"oauth_token_url\\\": \\\"http://token\\\",\\n        }\\n\\n        mock_settings = MagicMock()\\n        mock_settings.settings.mcp_composer_version = \\\"==0.1.0.8.10\\\"\\n\\n        mock_process = MagicMock(pid=4444, poll=MagicMock(return_value=None))\\n\\n        with (\\n            patch(\\\"lfx.services.mcp_composer.service.get_settings_service\\\", return_value=mock_settings),\\n            patch(\\\"subprocess.Popen\\\", return_value=mock_process) as mock_popen,\\n            patch.object(mcp_service, \\\"_is_port_available\\\", return_value=False),\\n        ):\\n            await mcp_service._start_project_composer_process(\\n                project_id=project_id,\\n                host=\\\"localhost\\\",\\n                port=9000,\\n                streamable_http_url=\\\"http://test/mcp\\\",\\n                auth_config=auth_config,\\n                max_startup_checks=1,\\n                startup_delay=0.01,\\n            )\\n\\n        cmd = mock_popen.call_args[0][0]\\n        idx = cmd.index(\\\"OAUTH_CALLBACK_PATH\\\")\\n        assert cmd[idx + 1] == callback_url\\n\\n    @pytest.mark.asyncio\\n    async def test_subprocess_receives_callback_path_env_var(self, mcp_service):\\n        \\\"\\\"\\\"Verify the subprocess command uses OAUTH_CALLBACK_PATH, not OAUTH_CALLBACK_URL.\\n\\n        This is the core regression test: mcp-composer's ServerSettings has a\\n        'callback_path' field (env_prefix='OAUTH_'), so the env var must be\\n        OAUTH_CALLBACK_PATH.  Sending OAUTH_CALLBACK_URL causes a Pydantic\\n        'extra_forbidden' validation error.\\n        \\\"\\\"\\\"\\n        project_id = \\\"env-var-test\\\"\\n        callback = \\\"http://localhost:9000/auth/idaas/callback\\\"\\n        auth_config = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": \\\"9000\\\",\\n            \\\"oauth_server_url\\\": \\\"http://localhost:9000\\\",\\n            \\\"oauth_callback_url\\\": callback,\\n            \\\"oauth_client_id\\\": \\\"cid\\\",\\n            \\\"oauth_client_secret\\\": \\\"csecret\\\",  # pragma: allowlist secret\\n            \\\"oauth_auth_url\\\": \\\"http://auth\\\",\\n            \\\"oauth_token_url\\\": \\\"http://token\\\",\\n            \\\"oauth_mcp_scope\\\": \\\"mcp\\\",\\n            \\\"oauth_provider_scope\\\": \\\"openid\\\",\\n        }\\n\\n        mock_settings = MagicMock()\\n        mock_settings.settings.mcp_composer_version = \\\"==0.1.0.8.10\\\"\\n\\n        mock_process = MagicMock(pid=3333, poll=MagicMock(return_value=None))\\n\\n        with (\\n            patch(\\\"lfx.services.mcp_composer.service.get_settings_service\\\", return_value=mock_settings),\\n            patch(\\\"subprocess.Popen\\\", return_value=mock_process) as mock_popen,\\n            patch.object(mcp_service, \\\"_is_port_available\\\", return_value=False),\\n        ):\\n            await mcp_service._start_project_composer_process(\\n                project_id=project_id,\\n                host=\\\"localhost\\\",\\n                port=9000,\\n                streamable_http_url=\\\"http://test/mcp\\\",\\n                auth_config=auth_config,\\n                max_startup_checks=1,\\n                startup_delay=0.01,\\n            )\\n\\n        cmd = mock_popen.call_args[0][0]\\n\\n        # OAUTH_CALLBACK_PATH must appear in the command\\n        assert \\\"OAUTH_CALLBACK_PATH\\\" in cmd, f\\\"Expected OAUTH_CALLBACK_PATH in command but got: {cmd}\\\"\\n        # The callback value should follow the env key\\n        idx = cmd.index(\\\"OAUTH_CALLBACK_PATH\\\")\\n        assert cmd[idx + 1] == callback\\n\\n        # OAUTH_CALLBACK_URL must NOT appear (would cause extra_forbidden error)\\n        assert \\\"OAUTH_CALLBACK_URL\\\" not in cmd, (\\n            f\\\"OAUTH_CALLBACK_URL should not be in command (mcp-composer rejects it): {cmd}\\\"\\n        )\\n\\n    def test_callback_aliases_do_not_trigger_restart_when_effective_value_matches(self, mcp_service):\\n        \\\"\\\"\\\"Alias-only callback field changes should not force composer restarts.\\\"\\\"\\\"\\n        existing_auth = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": \\\"9000\\\",\\n            \\\"oauth_server_url\\\": \\\"http://localhost:9000\\\",\\n            \\\"oauth_callback_path\\\": \\\"http://localhost:9000/auth/idaas/callback\\\",\\n            \\\"oauth_client_id\\\": \\\"cid\\\",\\n            \\\"oauth_client_secret\\\": \\\"csecret\\\",  # pragma: allowlist secret\\n            \\\"oauth_auth_url\\\": \\\"http://auth\\\",\\n            \\\"oauth_token_url\\\": \\\"http://token\\\",\\n        }\\n        new_auth = {\\n            \\\"auth_type\\\": \\\"oauth\\\",\\n            \\\"oauth_host\\\": \\\"localhost\\\",\\n            \\\"oauth_port\\\": \\\"9000\\\",\\n            \\\"oauth_server_url\\\": \\\"http://localhost:9000\\\",\\n            \\\"oauth_callback_url\\\": \\\"http://localhost:9000/auth/idaas/callback\\\",\\n            \\\"oauth_client_id\\\": \\\"cid\\\",\\n            \\\"oauth_client_secret\\\": \\\"csecret\\\",  # pragma: allowlist secret\\n            \\\"oauth_auth_url\\\": \\\"http://auth\\\",\\n            \\\"oauth_token_url\\\": \\\"http://token\\\",\\n        }\\n\\n        assert mcp_service._has_auth_config_changed(existing_auth, new_auth) is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_mcp_composer_version.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6715947865ccd5ace281c479d4fa2a5263c6b3493fbf6a38546dcfb27ff8e18a\",\"content\":\"\\\"\\\"\\\"Tests for mcp_composer_version validator in Settings.\\\"\\\"\\\"\\n\\nfrom lfx.services.settings.base import Settings\\n\\n\\ndef test_bare_version_gets_tilde_equals_prefix(monkeypatch):\\n    \\\"\\\"\\\"Test that a bare version like '0.1.0.7' gets ~= prefix added.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\"0.1.0.7\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\"~=0.1.0.7\\\"\\n\\n\\ndef test_version_with_tilde_equals_is_preserved(monkeypatch):\\n    \\\"\\\"\\\"Test that a version with ~= is preserved as-is.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\"~=0.1.0.7\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\"~=0.1.0.7\\\"\\n\\n\\ndef test_version_with_greater_than_or_equal_is_preserved(monkeypatch):\\n    \\\"\\\"\\\"Test that a version with >= is preserved as-is.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\">=0.1.0.7\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\">=0.1.0.7\\\"\\n\\n\\ndef test_version_with_exact_match_is_preserved(monkeypatch):\\n    \\\"\\\"\\\"Test that a version with == is preserved as-is.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\"==0.1.0.7\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\"==0.1.0.7\\\"\\n\\n\\ndef test_version_with_less_than_or_equal_is_preserved(monkeypatch):\\n    \\\"\\\"\\\"Test that a version with <= is preserved as-is.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\"<=0.1.0.7\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\"<=0.1.0.7\\\"\\n\\n\\ndef test_version_with_not_equal_is_preserved(monkeypatch):\\n    \\\"\\\"\\\"Test that a version with != is preserved as-is.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\"!=0.1.0.7\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\"!=0.1.0.7\\\"\\n\\n\\ndef test_version_with_less_than_is_preserved(monkeypatch):\\n    \\\"\\\"\\\"Test that a version with < is preserved as-is.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\"<0.1.0.7\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\"<0.1.0.7\\\"\\n\\n\\ndef test_version_with_greater_than_is_preserved(monkeypatch):\\n    \\\"\\\"\\\"Test that a version with > is preserved as-is.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\">0.1.0.7\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\">0.1.0.7\\\"\\n\\n\\ndef test_version_with_arbitrary_equality_is_preserved(monkeypatch):\\n    \\\"\\\"\\\"Test that a version with === is preserved as-is.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\"===0.1.0.7\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\"===0.1.0.7\\\"\\n\\n\\ndef test_empty_version_gets_default(monkeypatch):\\n    \\\"\\\"\\\"Test that empty string gets default value.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\"\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\"==0.1.0.8.10\\\"\\n\\n\\ndef test_no_env_var_uses_default(monkeypatch):\\n    \\\"\\\"\\\"Test that missing env var uses default value.\\\"\\\"\\\"\\n    monkeypatch.delenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", raising=False)\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\"==0.1.0.8.10\\\"\\n\\n\\ndef test_three_part_version_gets_prefix(monkeypatch):\\n    \\\"\\\"\\\"Test that a 3-part version like '1.2.3' gets ~= prefix.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\"1.2.3\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\"~=1.2.3\\\"\\n\\n\\ndef test_two_part_version_gets_prefix(monkeypatch):\\n    \\\"\\\"\\\"Test that a 2-part version like '1.2' gets ~= prefix.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\"1.2\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\"~=1.2\\\"\\n\\n\\ndef test_single_digit_version_gets_prefix(monkeypatch):\\n    \\\"\\\"\\\"Test that a single digit version like '1' gets ~= prefix.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_MCP_COMPOSER_VERSION\\\", \\\"1\\\")\\n    settings = Settings()\\n    assert settings.mcp_composer_version == \\\"~=1\\\"\\n\\n\\ndef test_validator_directly():\\n    \\\"\\\"\\\"Test calling the validator method directly.\\\"\\\"\\\"\\n    # Test bare version\\n    result = Settings.validate_mcp_composer_version(\\\"0.1.0.7\\\")\\n    assert result == \\\"~=0.1.0.7\\\"\\n\\n    # Test with specifier\\n    result = Settings.validate_mcp_composer_version(\\\">=0.1.0.7\\\")\\n    assert result == \\\">=0.1.0.7\\\"\\n\\n    # Test empty\\n    result = Settings.validate_mcp_composer_version(\\\"\\\")\\n    assert result == \\\"==0.1.0.8.10\\\"\\n\\n    # Test None\\n    result = Settings.validate_mcp_composer_version(None)\\n    assert result == \\\"==0.1.0.8.10\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_mcp_composer_windows.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2ecd53c1423ee8d9ccc2744c144f4b2b37fd1f3dc57663be0127cb1b0d1203c5\",\"content\":\"\\\"\\\"\\\"Unit tests for MCP Composer Service Windows-specific functionality.\\\"\\\"\\\"\\n\\n# ruff: noqa: SIM115, SIM117\\n\\nimport asyncio\\nimport contextlib\\nimport json\\nimport subprocess\\nimport tempfile\\nfrom pathlib import Path\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom lfx.services.mcp_composer.service import MCPComposerService, MCPComposerStartupError\\n\\n\\n@pytest.fixture\\ndef mcp_service():\\n    \\\"\\\"\\\"Create an MCP Composer service instance for testing.\\\"\\\"\\\"\\n    return MCPComposerService()\\n\\n\\nclass TestWindowsZombieProcessDetection:\\n    \\\"\\\"\\\"Test Windows-specific zombie process detection using PowerShell.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_zombie_mcp_processes_windows_no_processes(self, mcp_service):\\n        \\\"\\\"\\\"Test that PowerShell command runs when no zombie processes found.\\\"\\\"\\\"\\n        with patch(\\\"platform.system\\\", return_value=\\\"Windows\\\"), patch(\\\"asyncio.to_thread\\\") as mock_to_thread:\\n            # Mock PowerShell returning empty result (no processes)\\n            mock_result = MagicMock()\\n            mock_result.returncode = 0\\n            mock_result.stdout = \\\"\\\"\\n            mock_to_thread.return_value = mock_result\\n\\n            result = await mcp_service._kill_zombie_mcp_processes(2000)\\n\\n            # Should return False since no processes were killed\\n            assert result is False\\n            # Verify PowerShell was called (not wmic)\\n            assert mock_to_thread.called\\n            # Access args correctly - call_args is a tuple (args, kwargs)\\n            call_args = mock_to_thread.call_args.args\\n            assert call_args[1][0] == \\\"powershell.exe\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_zombie_mcp_processes_windows_single_process(self, mcp_service):\\n        \\\"\\\"\\\"Test that single zombie process is detected and killed via PowerShell.\\\"\\\"\\\"\\n        with patch(\\\"platform.system\\\", return_value=\\\"Windows\\\"), patch(\\\"asyncio.to_thread\\\") as mock_to_thread:\\n            # Mock PowerShell returning single process as JSON object\\n            zombie_pid = 12345\\n            ps_output = json.dumps({\\\"ProcessId\\\": zombie_pid, \\\"CommandLine\\\": \\\"python mcp-composer --port 2000\\\"})\\n\\n            # First call: netstat (no processes on port)\\n            mock_netstat_result = MagicMock()\\n            mock_netstat_result.returncode = 0\\n            mock_netstat_result.stdout = \\\"\\\"\\n\\n            # Second call: PowerShell Get-WmiObject\\n            mock_ps_result = MagicMock()\\n            mock_ps_result.returncode = 0\\n            mock_ps_result.stdout = ps_output\\n\\n            # Third call: taskkill\\n            mock_kill_result = MagicMock()\\n            mock_kill_result.returncode = 0\\n\\n            mock_to_thread.side_effect = [mock_netstat_result, mock_ps_result, mock_kill_result]\\n\\n            result = await mcp_service._kill_zombie_mcp_processes(2000)\\n\\n            # Should return True since process was killed\\n            assert result is True\\n            # Verify three calls: netstat + PowerShell + taskkill\\n            assert mock_to_thread.call_count == 3\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_zombie_mcp_processes_windows_multiple_processes(self, mcp_service):\\n        \\\"\\\"\\\"Test that multiple zombie processes are detected and killed.\\\"\\\"\\\"\\n        with patch(\\\"platform.system\\\", return_value=\\\"Windows\\\"), patch(\\\"asyncio.to_thread\\\") as mock_to_thread:\\n            # Mock PowerShell returning multiple processes as JSON array\\n            ps_output = json.dumps(\\n                [\\n                    {\\\"ProcessId\\\": 12345, \\\"CommandLine\\\": \\\"python mcp-composer --port 2000\\\"},\\n                    {\\\"ProcessId\\\": 67890, \\\"CommandLine\\\": \\\"python mcp-composer --port=2000\\\"},\\n                ]\\n            )\\n\\n            # First call: netstat (no processes on port)\\n            mock_netstat_result = MagicMock()\\n            mock_netstat_result.returncode = 0\\n            mock_netstat_result.stdout = \\\"\\\"\\n\\n            # Second call: PowerShell Get-WmiObject\\n            mock_ps_result = MagicMock()\\n            mock_ps_result.returncode = 0\\n            mock_ps_result.stdout = ps_output\\n\\n            # Mock successful kills\\n            mock_kill_result = MagicMock()\\n            mock_kill_result.returncode = 0\\n\\n            mock_to_thread.side_effect = [\\n                mock_netstat_result,\\n                mock_ps_result,\\n                mock_kill_result,\\n                mock_kill_result,\\n            ]\\n\\n            result = await mcp_service._kill_zombie_mcp_processes(2000)\\n\\n            assert result is True\\n            # Verify netstat + PowerShell + 2 taskkill calls\\n            assert mock_to_thread.call_count == 4\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_zombie_mcp_processes_windows_powershell_timeout(self, mcp_service):\\n        \\\"\\\"\\\"Test that PowerShell timeout is handled gracefully.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"platform.system\\\", return_value=\\\"Windows\\\"),\\n            patch(\\\"asyncio.to_thread\\\", side_effect=asyncio.TimeoutError(\\\"PowerShell timed out\\\")),\\n        ):\\n            # Should not raise, just return False\\n            result = await mcp_service._kill_zombie_mcp_processes(2000)\\n            assert result is False\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_zombie_mcp_processes_windows_invalid_json(self, mcp_service):\\n        \\\"\\\"\\\"Test that invalid JSON from PowerShell is handled gracefully.\\\"\\\"\\\"\\n        with patch(\\\"platform.system\\\", return_value=\\\"Windows\\\"), patch(\\\"asyncio.to_thread\\\") as mock_to_thread:\\n            mock_ps_result = MagicMock()\\n            mock_ps_result.returncode = 0\\n            mock_ps_result.stdout = \\\"invalid json {{\\\"\\n            mock_to_thread.return_value = mock_ps_result\\n\\n            # Should not raise, just return False\\n            result = await mcp_service._kill_zombie_mcp_processes(2000)\\n            assert result is False\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_zombie_mcp_processes_windows_skips_tracked_pids(self, mcp_service):\\n        \\\"\\\"\\\"Test that processes tracked by service are not killed.\\\"\\\"\\\"\\n        with patch(\\\"platform.system\\\", return_value=\\\"Windows\\\"):\\n            tracked_pid = 12345\\n            # Register PID as tracked\\n            mcp_service._pid_to_project[tracked_pid] = \\\"test-project\\\"\\n\\n            with patch(\\\"asyncio.to_thread\\\") as mock_to_thread:\\n                ps_output = json.dumps({\\\"ProcessId\\\": tracked_pid, \\\"CommandLine\\\": \\\"python mcp-composer --port 2000\\\"})\\n\\n                # First call: netstat (no processes on port)\\n                mock_netstat_result = MagicMock()\\n                mock_netstat_result.returncode = 0\\n                mock_netstat_result.stdout = \\\"\\\"\\n\\n                # Second call: PowerShell Get-WmiObject\\n                mock_ps_result = MagicMock()\\n                mock_ps_result.returncode = 0\\n                mock_ps_result.stdout = ps_output\\n\\n                mock_to_thread.side_effect = [mock_netstat_result, mock_ps_result]\\n\\n                result = await mcp_service._kill_zombie_mcp_processes(2000)\\n\\n                # Should return False since tracked PID was skipped\\n                assert result is False\\n                # netstat + PowerShell call, no taskkill (because PID is tracked)\\n                assert mock_to_thread.call_count == 2\\n\\n    @pytest.mark.asyncio\\n    async def test_kill_zombie_mcp_processes_non_fatal_on_error(self, mcp_service):\\n        \\\"\\\"\\\"Test that zombie cleanup errors are non-fatal (wrapped in try-catch).\\\"\\\"\\\"\\n        with (\\n            patch(\\\"platform.system\\\", return_value=\\\"Windows\\\"),\\n            patch(\\\"asyncio.to_thread\\\", side_effect=Exception(\\\"Test error\\\")),\\n        ):\\n            # Should not raise exception\\n            result = await mcp_service._kill_zombie_mcp_processes(2000)\\n            assert result is False\\n\\n\\nclass TestWindowsTempFileHandling:\\n    \\\"\\\"\\\"Test Windows-specific temp file handling for stdout/stderr.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_windows_uses_temp_files_instead_of_pipes(self, mcp_service):\\n        \\\"\\\"\\\"Test that Windows creates temp files for stdout/stderr instead of pipes.\\\"\\\"\\\"\\n        project_id = \\\"test-project\\\"\\n        port = 2000\\n\\n        with (\\n            patch(\\\"platform.system\\\", return_value=\\\"Windows\\\"),\\n            patch(\\\"subprocess.Popen\\\") as mock_popen,\\n            patch(\\\"tempfile.NamedTemporaryFile\\\") as mock_tempfile,\\n        ):\\n            # Mock temp file creation\\n            mock_stdout_file = MagicMock()\\n            mock_stdout_file.name = tempfile.gettempdir() + \\\"/mcp_composer_test_stdout.log\\\"\\n            mock_stderr_file = MagicMock()\\n            mock_stderr_file.name = tempfile.gettempdir() + \\\"/mcp_composer_test_stderr.log\\\"\\n\\n            mock_tempfile.side_effect = [mock_stdout_file, mock_stderr_file]\\n\\n            # Mock process\\n            mock_process = MagicMock()\\n            mock_process.pid = 12345\\n            mock_process.poll.return_value = None  # Process running\\n            mock_popen.return_value = mock_process\\n\\n            with patch.object(mcp_service, \\\"_is_port_available\\\", return_value=True):\\n                auth_config = {\\n                    \\\"auth_type\\\": \\\"oauth\\\",\\n                    \\\"oauth_host\\\": \\\"localhost\\\",\\n                    \\\"oauth_port\\\": str(port),\\n                    \\\"oauth_server_url\\\": f\\\"http://localhost:{port}\\\",\\n                    \\\"oauth_client_id\\\": \\\"test\\\",\\n                    \\\"oauth_client_secret\\\": \\\"test\\\",\\n                    \\\"oauth_auth_url\\\": \\\"http://test\\\",\\n                    \\\"oauth_token_url\\\": \\\"http://test\\\",\\n                }\\n\\n                with contextlib.suppress(Exception):\\n                    await mcp_service._start_project_composer_process(\\n                        project_id=project_id,\\n                        host=\\\"localhost\\\",\\n                        port=port,\\n                        streamable_http_url=\\\"http://test\\\",\\n                        auth_config=auth_config,\\n                        max_startup_checks=1,\\n                        startup_delay=0.1,\\n                    )\\n\\n                # Verify temp files were created\\n                assert mock_tempfile.call_count == 2\\n                # Verify Popen was called with file handles, not PIPE\\n                popen_call = mock_popen.call_args\\n                assert popen_call[1][\\\"stdout\\\"] == mock_stdout_file\\n                assert popen_call[1][\\\"stderr\\\"] == mock_stderr_file\\n\\n    @pytest.mark.asyncio\\n    async def test_windows_temp_files_are_read_async(self, mcp_service):\\n        \\\"\\\"\\\"Test that temp files are read using asyncio.to_thread (non-blocking).\\\"\\\"\\\"\\n        mock_process = MagicMock()\\n        mock_process.poll.return_value = 1  # Process died\\n\\n        # Create real temp files to test reading\\n        stdout_file = tempfile.NamedTemporaryFile(mode=\\\"w+b\\\", delete=False, suffix=\\\".log\\\")\\n        stderr_file = tempfile.NamedTemporaryFile(mode=\\\"w+b\\\", delete=False, suffix=\\\".log\\\")\\n\\n        try:\\n            # Write test data\\n            stdout_file.write(b\\\"stdout test data\\\")\\n            stderr_file.write(b\\\"stderr test data\\\")\\n            stdout_file.close()\\n            stderr_file.close()\\n\\n            stdout, stderr, _error_msg = await mcp_service._read_process_output_and_extract_error(\\n                mock_process, oauth_server_url=None, timeout=2.0, stdout_file=stdout_file, stderr_file=stderr_file\\n            )\\n\\n            # Verify content was read\\n            assert \\\"stdout test data\\\" in stdout\\n            assert \\\"stderr test data\\\" in stderr\\n\\n            # Verify files were cleaned up\\n            assert not Path(stdout_file.name).exists()\\n            assert not Path(stderr_file.name).exists()\\n\\n        finally:\\n            # Cleanup in case test fails\\n            for f in [stdout_file.name, stderr_file.name]:\\n                with contextlib.suppress(FileNotFoundError):\\n                    Path(f).unlink()\\n\\n    @pytest.mark.asyncio\\n    async def test_windows_temp_files_cleanup_on_success(self, mcp_service):\\n        \\\"\\\"\\\"Test that temp files are cleaned up when process starts successfully.\\\"\\\"\\\"\\n        project_id = \\\"test-project\\\"\\n        port = 2000\\n\\n        with patch(\\\"platform.system\\\", return_value=\\\"Windows\\\"):\\n            # Create real temp files\\n            stdout_file = tempfile.NamedTemporaryFile(mode=\\\"w+b\\\", delete=False)\\n            stderr_file = tempfile.NamedTemporaryFile(mode=\\\"w+b\\\", delete=False)\\n            stdout_file.close()\\n            stderr_file.close()\\n\\n            try:\\n                with patch(\\\"subprocess.Popen\\\") as mock_popen:\\n                    with patch(\\\"tempfile.NamedTemporaryFile\\\") as mock_tempfile:\\n                        mock_tempfile.side_effect = [stdout_file, stderr_file]\\n\\n                        # Mock successful process startup\\n                        mock_process = MagicMock()\\n                        mock_process.pid = 12345\\n                        mock_process.poll.return_value = None\\n                        mock_popen.return_value = mock_process\\n\\n                        with patch.object(mcp_service, \\\"_is_port_available\\\") as mock_port:\\n                            # First checks: not bound, then bound\\n                            mock_port.side_effect = [True, False]\\n\\n                            auth_config = {\\n                                \\\"auth_type\\\": \\\"oauth\\\",\\n                                \\\"oauth_host\\\": \\\"localhost\\\",\\n                                \\\"oauth_port\\\": str(port),\\n                                \\\"oauth_server_url\\\": f\\\"http://localhost:{port}\\\",\\n                                \\\"oauth_client_id\\\": \\\"test\\\",\\n                                \\\"oauth_client_secret\\\": \\\"test\\\",\\n                                \\\"oauth_auth_url\\\": \\\"http://test\\\",\\n                                \\\"oauth_token_url\\\": \\\"http://test\\\",\\n                            }\\n\\n                            process = await mcp_service._start_project_composer_process(\\n                                project_id=project_id,\\n                                host=\\\"localhost\\\",\\n                                port=port,\\n                                streamable_http_url=\\\"http://test\\\",\\n                                auth_config=auth_config,\\n                                max_startup_checks=2,\\n                                startup_delay=0.1,\\n                            )\\n\\n                            # Verify files were cleaned up\\n                            assert not Path(stdout_file.name).exists()\\n                            assert not Path(stderr_file.name).exists()\\n                            assert process == mock_process\\n\\n            finally:\\n                # Cleanup\\n                for f in [stdout_file.name, stderr_file.name]:\\n                    with contextlib.suppress(FileNotFoundError):\\n                        Path(f).unlink()\\n\\n    @pytest.mark.asyncio\\n    async def test_non_windows_uses_pipes(self, mcp_service):\\n        \\\"\\\"\\\"Test that non-Windows systems still use pipes (not temp files).\\\"\\\"\\\"\\n        project_id = \\\"test-project\\\"\\n        port = 2000\\n\\n        with patch(\\\"platform.system\\\", return_value=\\\"Linux\\\"), patch(\\\"subprocess.Popen\\\") as mock_popen:\\n            mock_process = MagicMock()\\n            mock_process.pid = 12345\\n            mock_process.poll.return_value = None\\n            mock_popen.return_value = mock_process\\n\\n            with patch.object(mcp_service, \\\"_is_port_available\\\", return_value=True):\\n                auth_config = {\\n                    \\\"auth_type\\\": \\\"oauth\\\",\\n                    \\\"oauth_host\\\": \\\"localhost\\\",\\n                    \\\"oauth_port\\\": str(port),\\n                    \\\"oauth_server_url\\\": f\\\"http://localhost:{port}\\\",\\n                    \\\"oauth_client_id\\\": \\\"test\\\",\\n                    \\\"oauth_client_secret\\\": \\\"test\\\",\\n                    \\\"oauth_auth_url\\\": \\\"http://test\\\",\\n                    \\\"oauth_token_url\\\": \\\"http://test\\\",\\n                }\\n\\n                with contextlib.suppress(Exception):\\n                    await mcp_service._start_project_composer_process(\\n                        project_id=project_id,\\n                        host=\\\"localhost\\\",\\n                        port=port,\\n                        streamable_http_url=\\\"http://test\\\",\\n                        auth_config=auth_config,\\n                        max_startup_checks=1,\\n                        startup_delay=0.1,\\n                    )\\n\\n                # Verify Popen was called with subprocess.PIPE\\n                popen_call = mock_popen.call_args\\n                assert popen_call[1][\\\"stdout\\\"] == subprocess.PIPE\\n                assert popen_call[1][\\\"stderr\\\"] == subprocess.PIPE\\n\\n\\nclass TestIncreasedStartupTimeout:\\n    \\\"\\\"\\\"Test that startup timeout was increased for Windows.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_startup_timeout_is_80_seconds(self, mcp_service):\\n        \\\"\\\"\\\"Test that max_startup_checks default is 40 * 2s = 80 seconds.\\\"\\\"\\\"\\n        # Check default parameters\\n        import inspect\\n\\n        sig = inspect.signature(mcp_service.start_project_composer)\\n        assert sig.parameters[\\\"max_startup_checks\\\"].default == 40\\n        assert sig.parameters[\\\"startup_delay\\\"].default == 2.0\\n\\n        # Verify total timeout is 80 seconds\\n        assert 40 * 2.0 == 80.0\\n\\n    @pytest.mark.asyncio\\n    async def test_retry_with_increased_timeout(self, mcp_service):\\n        \\\"\\\"\\\"Test that retries use increased timeout (80s total per attempt).\\\"\\\"\\\"\\n        project_id = \\\"test-project\\\"\\n\\n        with patch.object(mcp_service, \\\"_start_project_composer_process\\\") as mock_start:\\n            # Simulate failure\\n            mock_start.side_effect = MCPComposerStartupError(\\\"Test error\\\", project_id)\\n\\n            with patch.object(mcp_service, \\\"_kill_zombie_mcp_processes\\\", new=AsyncMock()):\\n                with patch.object(mcp_service, \\\"_is_port_available\\\", return_value=True):\\n                    mcp_service._start_locks[project_id] = asyncio.Lock()\\n\\n                    auth_config = {\\n                        \\\"auth_type\\\": \\\"oauth\\\",\\n                        \\\"oauth_host\\\": \\\"localhost\\\",\\n                        \\\"oauth_port\\\": \\\"2000\\\",\\n                        \\\"oauth_server_url\\\": \\\"http://localhost:2000\\\",\\n                        \\\"oauth_client_id\\\": \\\"test\\\",\\n                        \\\"oauth_client_secret\\\": \\\"test\\\",\\n                        \\\"oauth_auth_url\\\": \\\"http://test\\\",\\n                        \\\"oauth_token_url\\\": \\\"http://test\\\",\\n                    }\\n\\n                    with contextlib.suppress(Exception):\\n                        await mcp_service._do_start_project_composer(\\n                            project_id=project_id,\\n                            streamable_http_url=\\\"http://test\\\",\\n                            auth_config=auth_config,\\n                            max_retries=3,\\n                        )\\n\\n                    # Verify _start_project_composer_process was called with correct defaults\\n                    assert mock_start.call_count == 3\\n                    for call in mock_start.call_args_list:\\n                        # Check positional arguments (args) and keyword arguments (kwargs)\\n                        # max_startup_checks is the 6th argument (index 5) or in kwargs\\n                        # startup_delay is the 7th argument (index 6) or in kwargs\\n                        if \\\"max_startup_checks\\\" in call.kwargs:\\n                            assert call.kwargs[\\\"max_startup_checks\\\"] == 40\\n                        else:\\n                            assert call.args[5] == 40\\n\\n                        if \\\"startup_delay\\\" in call.kwargs:\\n                            assert call.kwargs[\\\"startup_delay\\\"] == 2.0\\n                        else:\\n                            assert call.args[6] == 2.0\\n\\n\\nclass TestStreamReadingAvoidance:\\n    \\\"\\\"\\\"Test that stream.peek() blocking issue is avoided on Windows.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_read_stream_non_blocking_returns_empty_on_windows(self, mcp_service):\\n        \\\"\\\"\\\"Test that _read_stream_non_blocking returns empty string on Windows.\\\"\\\"\\\"\\n        with patch(\\\"platform.system\\\", return_value=\\\"Windows\\\"):\\n            mock_stream = MagicMock()\\n\\n            result = await mcp_service._read_stream_non_blocking(mock_stream, \\\"stdout\\\")\\n\\n            # Should return empty string without trying to read\\n            assert result == \\\"\\\"\\n            # Verify no peek() or readline() was called\\n            assert not mock_stream.peek.called\\n            assert not mock_stream.readline.called\\n\\n    @pytest.mark.asyncio\\n    async def test_read_stream_non_blocking_uses_select_on_unix(self, mcp_service):\\n        \\\"\\\"\\\"Test that Unix systems use select.select() for non-blocking read.\\\"\\\"\\\"\\n        with patch(\\\"platform.system\\\", return_value=\\\"Linux\\\"):\\n            with patch(\\\"select.select\\\", return_value=([True], [], [])) as mock_select:\\n                mock_stream = MagicMock()\\n                mock_stream.readline.return_value = b\\\"test output\\\\n\\\"\\n\\n                result = await mcp_service._read_stream_non_blocking(mock_stream, \\\"stdout\\\")\\n\\n                # Should use select and read line\\n                assert mock_select.called\\n                assert \\\"test output\\\" in result\\n\\n\\nclass TestRetryRobustness:\\n    \\\"\\\"\\\"Test that retry logic handles Windows-specific errors gracefully.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_zombie_cleanup_failure_is_non_fatal_during_retry(self, mcp_service):\\n        \\\"\\\"\\\"Test that zombie cleanup failure during retry doesn't stop retry attempts.\\\"\\\"\\\"\\n        project_id = \\\"test-project\\\"\\n\\n        call_count = 0\\n\\n        async def mock_start_raises_once(*_args, **_kwargs):\\n            nonlocal call_count\\n            call_count += 1\\n            if call_count == 1:\\n                msg = \\\"First attempt failed\\\"\\n                raise MCPComposerStartupError(msg, project_id)\\n            # Second attempt succeeds\\n            mock_process = MagicMock()\\n            mock_process.pid = 12345\\n            return mock_process\\n\\n        with patch.object(mcp_service, \\\"_start_project_composer_process\\\", side_effect=mock_start_raises_once):\\n            # Zombie cleanup raises error\\n            with patch.object(mcp_service, \\\"_kill_zombie_mcp_processes\\\", side_effect=Exception(\\\"PowerShell error\\\")):\\n                with patch.object(mcp_service, \\\"_is_port_available\\\", return_value=True):\\n                    mcp_service._start_locks[project_id] = asyncio.Lock()\\n\\n                    auth_config = {\\n                        \\\"auth_type\\\": \\\"oauth\\\",\\n                        \\\"oauth_host\\\": \\\"localhost\\\",\\n                        \\\"oauth_port\\\": \\\"2000\\\",\\n                        \\\"oauth_server_url\\\": \\\"http://localhost:2000\\\",\\n                        \\\"oauth_client_id\\\": \\\"test\\\",\\n                        \\\"oauth_client_secret\\\": \\\"test\\\",\\n                        \\\"oauth_auth_url\\\": \\\"http://test\\\",\\n                        \\\"oauth_token_url\\\": \\\"http://test\\\",\\n                    }\\n\\n                    # Should succeed on second attempt despite zombie cleanup failure\\n                    await mcp_service._do_start_project_composer(\\n                        project_id=project_id,\\n                        streamable_http_url=\\\"http://test\\\",\\n                        auth_config=auth_config,\\n                        max_retries=2,\\n                        max_startup_checks=1,\\n                        startup_delay=0.1,\\n                    )\\n\\n                    # Verify it retried successfully\\n                    assert call_count == 2\\n                    assert project_id in mcp_service.project_composers\\n\\n\\n@pytest.mark.asyncio\\nasync def test_windows_legacy_sse_url_passthrough(mcp_service):\\n    \\\"\\\"\\\"Ensure Windows composer starts propagate explicit legacy SSE URLs.\\\"\\\"\\\"\\n    project_id = \\\"windows-legacy\\\"\\n    auth_config = {\\n        \\\"auth_type\\\": \\\"oauth\\\",\\n        \\\"oauth_host\\\": \\\"localhost\\\",\\n        \\\"oauth_port\\\": \\\"9300\\\",\\n        \\\"oauth_server_url\\\": \\\"http://localhost:9300\\\",\\n        \\\"oauth_client_id\\\": \\\"legacy\\\",\\n        \\\"oauth_client_secret\\\": \\\"secret\\\",\\n        \\\"oauth_auth_url\\\": \\\"http://auth\\\",\\n        \\\"oauth_token_url\\\": \\\"http://token\\\",\\n    }\\n    mcp_service._start_locks[project_id] = asyncio.Lock()\\n    mock_process = MagicMock(pid=2468)\\n\\n    with patch.object(\\n        mcp_service,\\n        \\\"_start_project_composer_process\\\",\\n        new=AsyncMock(return_value=mock_process),\\n    ) as mock_start:\\n        await mcp_service._do_start_project_composer(\\n            project_id=project_id,\\n            streamable_http_url=\\\"http://windows/streamable\\\",\\n            auth_config=auth_config,\\n            legacy_sse_url=\\\"http://windows/sse\\\",\\n            max_retries=1,\\n            max_startup_checks=1,\\n        )\\n\\n    mock_start.assert_awaited()\\n    assert mock_start.call_args.kwargs[\\\"legacy_sse_url\\\"] == \\\"http://windows/sse\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_windows_legacy_sse_url_defaults(mcp_service):\\n    \\\"\\\"\\\"Ensure default legacy SSE URLs are derived when none supplied on Windows.\\\"\\\"\\\"\\n    project_id = \\\"windows-legacy-default\\\"\\n    streamable_url = \\\"http://windows/default\\\"\\n    auth_config = {\\n        \\\"auth_type\\\": \\\"oauth\\\",\\n        \\\"oauth_host\\\": \\\"localhost\\\",\\n        \\\"oauth_port\\\": \\\"9400\\\",\\n        \\\"oauth_server_url\\\": \\\"http://localhost:9400\\\",\\n        \\\"oauth_client_id\\\": \\\"legacy\\\",\\n        \\\"oauth_client_secret\\\": \\\"secret\\\",\\n        \\\"oauth_auth_url\\\": \\\"http://auth\\\",\\n        \\\"oauth_token_url\\\": \\\"http://token\\\",\\n    }\\n    mcp_service._start_locks[project_id] = asyncio.Lock()\\n    mock_process = MagicMock(pid=1357)\\n\\n    with patch.object(\\n        mcp_service,\\n        \\\"_start_project_composer_process\\\",\\n        new=AsyncMock(return_value=mock_process),\\n    ) as mock_start:\\n        await mcp_service._do_start_project_composer(\\n            project_id=project_id,\\n            streamable_http_url=streamable_url,\\n            auth_config=auth_config,\\n            max_retries=1,\\n            max_startup_checks=1,\\n        )\\n\\n    mock_start.assert_awaited()\\n    assert mock_start.call_args.kwargs[\\\"legacy_sse_url\\\"] == f\\\"{streamable_url}/sse\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_multi_worker_bypass_setting.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f61c916d092718fd67bf9acb12512696f9a459217665b747bec417c9ecbadecb\",\"content\":\"\\\"\\\"\\\"Tests for ``dangerously_allow_multi_worker_without_shared_queue``.\\n\\nThe setting is the operator-facing half of the multi-worker guard enforced in\\n``langflow.__main__.ensure_multi_worker_safe``: it must be off unless explicitly\\nturned on, readable from the environment under its full deliberately-scary name,\\nand it must NOT change how ``event_delivery`` is resolved. That last point is the\\nsubtle one \u2014 the bypass only stops the process from refusing to boot; forcing\\n``direct`` delivery is still the right call because the in-memory queue is still\\nworker-local, flag or no flag.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.services.settings.base import Settings\\n\\nif TYPE_CHECKING:\\n    import pytest\\n\\nBYPASS_ENV_VAR = \\\"LANGFLOW_DANGEROUSLY_ALLOW_MULTI_WORKER_WITHOUT_SHARED_QUEUE\\\"\\n\\n\\ndef _isolate_env(monkeypatch: pytest.MonkeyPatch) -> None:\\n    for name in (\\\"LANGFLOW_WORKERS\\\", \\\"LANGFLOW_JOB_QUEUE_TYPE\\\", \\\"LANGFLOW_EVENT_DELIVERY\\\", BYPASS_ENV_VAR):\\n        monkeypatch.delenv(name, raising=False)\\n\\n\\ndef test_bypass_is_off_by_default(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"Nobody gets the bypass by accident.\\\"\\\"\\\"\\n    _isolate_env(monkeypatch)\\n\\n    assert Settings().dangerously_allow_multi_worker_without_shared_queue is False\\n\\n\\ndef test_bypass_reads_its_env_var(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"The documented env var is what actually flips the setting.\\\"\\\"\\\"\\n    _isolate_env(monkeypatch)\\n    monkeypatch.setenv(BYPASS_ENV_VAR, \\\"true\\\")\\n\\n    assert Settings().dangerously_allow_multi_worker_without_shared_queue is True\\n\\n\\ndef test_bypass_does_not_change_event_delivery(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"The bypass must not re-enable cross-worker polling/streaming delivery.\\n\\n    The queue is still worker-local under the flag, so ``set_event_delivery``\\n    keeps forcing ``direct``; letting the flag leak into that validator would\\n    hand clients a delivery mode that fails ~half the time.\\n    \\\"\\\"\\\"\\n    _isolate_env(monkeypatch)\\n    monkeypatch.setenv(\\\"LANGFLOW_WORKERS\\\", \\\"4\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_JOB_QUEUE_TYPE\\\", \\\"asyncio\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_EVENT_DELIVERY\\\", \\\"polling\\\")\\n    monkeypatch.setenv(BYPASS_ENV_VAR, \\\"true\\\")\\n\\n    settings = Settings()\\n\\n    assert settings.dangerously_allow_multi_worker_without_shared_queue is True\\n    assert settings.event_delivery == \\\"direct\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_redis_queue_bounds.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"264cb6c426b47435b30eac821f4a9306c92f45fe8abb39f87dbb8f94c0450331\",\"content\":\"\\\"\\\"\\\"Validation tests for the Redis job-queue timing settings.\\n\\nThese settings drive cross-worker cancel, the cancel-marker race fix, and the\\npolling watchdog. Bad env values would silently re-open the races those\\nfeatures were added to close, so Pydantic must reject them at config load.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.services.settings.base import Settings\\nfrom pydantic import ValidationError\\n\\n\\ndef test_redis_queue_startup_grace_s_rejects_negative(monkeypatch):\\n    \\\"\\\"\\\"Negative grace would make remote consumers treat a not-yet-created stream as EOF.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_REDIS_QUEUE_STARTUP_GRACE_S\\\", \\\"-1\\\")\\n    with pytest.raises(ValidationError):\\n        Settings()\\n\\n\\ndef test_redis_queue_startup_grace_s_accepts_zero(monkeypatch):\\n    \\\"\\\"\\\"Zero is a valid (very strict) setting and must not be rejected.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_REDIS_QUEUE_STARTUP_GRACE_S\\\", \\\"0\\\")\\n    settings = Settings()\\n    assert settings.redis_queue_startup_grace_s == 0\\n\\n\\ndef test_redis_queue_cancel_marker_ttl_rejects_zero(monkeypatch):\\n    \\\"\\\"\\\"A zero TTL would make the marker key invalid and reopen the publish-before-subscribe race.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_REDIS_QUEUE_CANCEL_MARKER_TTL\\\", \\\"0\\\")\\n    with pytest.raises(ValidationError):\\n        Settings()\\n\\n\\ndef test_redis_queue_cancel_marker_ttl_rejects_negative(monkeypatch):\\n    \\\"\\\"\\\"Negative TTLs are invalid in Redis.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_REDIS_QUEUE_CANCEL_MARKER_TTL\\\", \\\"-1\\\")\\n    with pytest.raises(ValidationError):\\n        Settings()\\n\\n\\ndef test_redis_queue_polling_watchdog_interval_s_rejects_zero(monkeypatch):\\n    \\\"\\\"\\\"Zero interval would spin the scan loop with no progress.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_REDIS_QUEUE_POLLING_WATCHDOG_INTERVAL_S\\\", \\\"0\\\")\\n    with pytest.raises(ValidationError):\\n        Settings()\\n\\n\\ndef test_redis_queue_polling_stale_threshold_s_rejects_negative(monkeypatch):\\n    \\\"\\\"\\\"Negative threshold is meaningless; 0 is the documented disable switch.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_REDIS_QUEUE_POLLING_STALE_THRESHOLD_S\\\", \\\"-1\\\")\\n    with pytest.raises(ValidationError):\\n        Settings()\\n\\n\\ndef test_redis_queue_polling_stale_threshold_s_accepts_zero(monkeypatch):\\n    \\\"\\\"\\\"0 explicitly disables the watchdog and must remain a valid setting.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_REDIS_QUEUE_POLLING_STALE_THRESHOLD_S\\\", \\\"0\\\")\\n    settings = Settings()\\n    assert settings.redis_queue_polling_stale_threshold_s == 0\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_runtime_port.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d453d4c15befc235359ea5d6975386512404c91dbf1a4433501be5572b9b45d6\",\"content\":\"\\\"\\\"\\\"Tests for runtime_port validator in Settings.\\n\\nKubernetes auto-creates service discovery env vars like\\nLANGFLOW_RUNTIME_PORT=tcp://<ip>:<port> which collide with\\npydantic-settings LANGFLOW_ prefix. The validator should\\nextract the port from URL-like values.\\n\\\"\\\"\\\"\\n\\nfrom lfx.services.settings.base import Settings\\n\\n\\ndef test_runtime_port_from_k8s_tcp_url(monkeypatch):\\n    \\\"\\\"\\\"Kubernetes tcp:// service discovery value is parsed to the port number.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_RUNTIME_PORT\\\", \\\"tcp://10.96.0.1:7865\\\")\\n    settings = Settings()\\n    assert settings.runtime_port == 7865\\n\\n\\ndef test_runtime_port_from_k8s_tcp_url_different_port(monkeypatch):\\n    \\\"\\\"\\\"Different port numbers are parsed correctly.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_RUNTIME_PORT\\\", \\\"tcp://10.0.0.5:8080\\\")\\n    settings = Settings()\\n    assert settings.runtime_port == 8080\\n\\n\\ndef test_runtime_port_from_integer_string(monkeypatch):\\n    \\\"\\\"\\\"A plain integer string is parsed normally.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_RUNTIME_PORT\\\", \\\"7865\\\")\\n    settings = Settings()\\n    assert settings.runtime_port == 7865\\n\\n\\ndef test_runtime_port_default_is_none(monkeypatch):\\n    \\\"\\\"\\\"Without env var, runtime_port defaults to None.\\\"\\\"\\\"\\n    monkeypatch.delenv(\\\"LANGFLOW_RUNTIME_PORT\\\", raising=False)\\n    settings = Settings()\\n    assert settings.runtime_port is None\\n\\n\\ndef test_runtime_port_garbage_value_returns_none(monkeypatch):\\n    \\\"\\\"\\\"Unparseable values fall back to None.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_RUNTIME_PORT\\\", \\\"not-a-port\\\")\\n    settings = Settings()\\n    assert settings.runtime_port is None\\n\\n\\ndef test_runtime_port_from_http_url(monkeypatch):\\n    \\\"\\\"\\\"http:// URLs are also parsed correctly (validator is scheme-agnostic).\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_RUNTIME_PORT\\\", \\\"http://10.96.0.1:7865\\\")\\n    settings = Settings()\\n    assert settings.runtime_port == 7865\\n\\n\\ndef test_runtime_port_url_without_port_returns_none(monkeypatch):\\n    \\\"\\\"\\\"A URL without a port component falls back to None.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_RUNTIME_PORT\\\", \\\"tcp://10.96.0.1\\\")\\n    settings = Settings()\\n    assert settings.runtime_port is None\\n\\n\\ndef test_runtime_port_url_with_out_of_range_port_returns_none(monkeypatch):\\n    \\\"\\\"\\\"A URL with port > 65535 should not crash, falls back to None.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_RUNTIME_PORT\\\", \\\"tcp://10.0.0.1:99999\\\")\\n    settings = Settings()\\n    assert settings.runtime_port is None\\n\\n\\ndef test_runtime_port_url_with_non_numeric_port_returns_none(monkeypatch):\\n    \\\"\\\"\\\"A URL with non-numeric port should not crash, falls back to None.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_RUNTIME_PORT\\\", \\\"tcp://10.0.0.1:abc\\\")\\n    settings = Settings()\\n    assert settings.runtime_port is None\\n\\n\\ndef test_runtime_port_url_with_negative_port_returns_none(monkeypatch):\\n    \\\"\\\"\\\"A URL with negative port should not crash, falls back to None.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_RUNTIME_PORT\\\", \\\"tcp://10.0.0.1:-1\\\")\\n    settings = Settings()\\n    assert settings.runtime_port is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_secure_permissions_windows.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8834aeb61fd22ff39db7d7eeaf5f8b2b11cce82eaba22867f0d174c85bf97933\",\"content\":\"\\\"\\\"\\\"Windows DACL hardening for the secret_key file.\\n\\nRegression tests for the machine-name/username collision bug: when the\\ncomputer name equals the username (e.g. computer DANIEL, user daniel),\\n``LookupAccountName(\\\"\\\", GetUserName())`` resolves the bare name to the\\nmachine-domain object (SidTypeDomain, no user RID). Writing a DACL that\\ngrants access only to that SID locks out the real user, and the next\\nstartup dies with PermissionError when reading the secret_key back.\\n\\nThe fix takes the user SID from the process token instead of resolving\\nby name, and read_secret_from_file self-heals files whose DACL was\\nalready broken by an affected version.\\n\\\"\\\"\\\"\\n\\nimport platform\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.services.settings.utils import (\\n    read_secret_from_file,\\n    set_secure_permissions,\\n    write_secret_to_file,\\n)\\n\\npytestmark = pytest.mark.skipif(platform.system() != \\\"Windows\\\", reason=\\\"Windows DACL behavior\\\")\\n\\nSECRET = \\\"test-secret-value\\\"  # noqa: S105\\n\\n\\ndef _current_process_user_sid():\\n    import win32api\\n    import win32con\\n    import win32security\\n\\n    token = win32security.OpenProcessToken(win32api.GetCurrentProcess(), win32con.TOKEN_QUERY)\\n    sid, _attributes = win32security.GetTokenInformation(token, win32security.TokenUser)\\n    return sid\\n\\n\\ndef _dacl_sids(path: Path) -> list:\\n    import win32security\\n\\n    sd = win32security.GetFileSecurity(str(path), win32security.DACL_SECURITY_INFORMATION)\\n    dacl = sd.GetSecurityDescriptorDacl()\\n    assert dacl is not None, \\\"expected a protected DACL, got NULL (allow-everyone)\\\"\\n    return [dacl.GetAce(i)[2] for i in range(dacl.GetAceCount())]\\n\\n\\ndef _apply_broken_domain_sid_dacl(path: Path) -> None:\\n    \\\"\\\"\\\"Reproduce the DACL an affected version wrote: single ACE for the machine-domain SID.\\\"\\\"\\\"\\n    import win32api\\n    import win32con\\n    import win32security\\n\\n    domain_sid, _, sid_type = win32security.LookupAccountName(\\\"\\\", win32api.GetComputerName())\\n    assert sid_type == win32security.SidTypeDomain\\n    sd = win32security.GetFileSecurity(str(path), win32security.DACL_SECURITY_INFORMATION)\\n    dacl = win32security.ACL()\\n    dacl.AddAccessAllowedAce(\\n        win32security.ACL_REVISION,\\n        win32con.GENERIC_READ | win32con.GENERIC_WRITE,\\n        domain_sid,\\n    )\\n    sd.SetSecurityDescriptorDacl(1, dacl, 0)\\n    win32security.SetFileSecurity(str(path), win32security.DACL_SECURITY_INFORMATION, sd)\\n\\n\\n@pytest.fixture\\ndef secret_path(tmp_path: Path):\\n    path = tmp_path / \\\"secret_key\\\"\\n    yield path\\n    # Reset the ACL so pytest can clean tmp_path even after a broken-DACL test.\\n    if path.exists():\\n        import win32security\\n\\n        sd = win32security.GetFileSecurity(str(path), win32security.DACL_SECURITY_INFORMATION)\\n        sd.SetSecurityDescriptorDacl(1, None, 0)\\n        win32security.SetFileSecurity(str(path), win32security.DACL_SECURITY_INFORMATION, sd)\\n\\n\\ndef test_write_then_read_roundtrip(secret_path: Path):\\n    write_secret_to_file(secret_path, SECRET)\\n    assert read_secret_from_file(secret_path) == SECRET\\n\\n\\ndef test_dacl_grants_the_process_token_user(secret_path: Path):\\n    \\\"\\\"\\\"The ACE must target the token user SID, never a name-resolved principal.\\\"\\\"\\\"\\n    write_secret_to_file(secret_path, SECRET)\\n    sids = _dacl_sids(secret_path)\\n    assert sids == [_current_process_user_sid()]\\n\\n\\ndef test_survives_machine_name_username_collision(secret_path: Path, monkeypatch: pytest.MonkeyPatch):\\n    \\\"\\\"\\\"Simulate computer name == username: GetUserName() returns the machine name.\\n\\n    On an affected host the bare name resolves to the machine-domain SID; a fix\\n    based on the process token must be immune to whatever GetUserName returns.\\n    \\\"\\\"\\\"\\n    import win32api\\n\\n    monkeypatch.setattr(win32api, \\\"GetUserName\\\", win32api.GetComputerName)\\n    write_secret_to_file(secret_path, SECRET)\\n    assert read_secret_from_file(secret_path) == SECRET\\n    sids = _dacl_sids(secret_path)\\n    assert sids == [_current_process_user_sid()]\\n\\n\\ndef test_read_self_heals_broken_dacl(secret_path: Path):\\n    \\\"\\\"\\\"Installs already hit by the bug must recover without manual icacls /reset.\\\"\\\"\\\"\\n    secret_path.write_text(SECRET, encoding=\\\"utf-8\\\")\\n    _apply_broken_domain_sid_dacl(secret_path)\\n    with pytest.raises(PermissionError):\\n        secret_path.read_text(encoding=\\\"utf-8\\\")\\n\\n    assert read_secret_from_file(secret_path) == SECRET\\n    # The repaired file must stay readable and carry the correct ACE.\\n    assert secret_path.read_text(encoding=\\\"utf-8\\\") == SECRET\\n    assert _dacl_sids(secret_path) == [_current_process_user_sid()]\\n\\n\\ndef test_set_secure_permissions_direct(secret_path: Path):\\n    secret_path.write_text(SECRET, encoding=\\\"utf-8\\\")\\n    set_secure_permissions(secret_path)\\n    assert secret_path.read_text(encoding=\\\"utf-8\\\") == SECRET\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/settings/test_settings_composition.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b13a5c3772a31e59d863ffd5181626e10321e841b19044fc84e851691c23111e\",\"content\":\"\\\"\\\"\\\"Structural tests for the composed ``Settings`` class.\\n\\nThese guard the refactor that split ``Settings`` into per-group mixins:\\n\\n- every field that used to live on ``Settings`` still does (catches an\\n  accidental drop of a group from the inheritance list),\\n- a sampling of critical defaults is unchanged,\\n- cross-group validators still see their dependencies in ``info.data``\\n  (workers -> event_delivery, config_dir -> database_url),\\n- yaml round-trip and the small utility helpers still work.\\n\\\"\\\"\\\"\\n\\nimport builtins\\nimport tempfile\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.services.settings.base import (\\n    BASE_COMPONENTS_PATH,\\n    CustomSource,\\n    Settings,\\n    is_list_of_any,\\n    load_settings_from_yaml,\\n    save_settings_to_yaml,\\n)\\nfrom lfx.services.settings.constants import AGENTIC_VARIABLES\\n\\n\\ndef test_voice_mode_requires_openai_sdk(monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"Installing only the VAD library must not advertise unusable voice mode.\\\"\\\"\\\"\\n    real_import = builtins.__import__\\n\\n    def import_without_openai(name, *args, **kwargs):\\n        \\\"\\\"\\\"Return a stub for webrtcvad and raise ModuleNotFoundError for openai.\\\"\\\"\\\"\\n        if name == \\\"webrtcvad\\\":\\n            return object()\\n        if name == \\\"openai\\\" or name.startswith(\\\"openai.\\\"):\\n            error_message = \\\"No module named 'openai'\\\"\\n            raise ModuleNotFoundError(error_message, name=\\\"openai\\\")\\n        return real_import(name, *args, **kwargs)\\n\\n    monkeypatch.setattr(builtins, \\\"__import__\\\", import_without_openai)\\n\\n    assert Settings().voice_mode_available is False\\n\\n\\n# Every field the composed Settings must expose: the original monolith fields\\n# plus the settings added in 1.10.0 (folded into the mixins during the release\\n# back-merge). Asserted as a set so a missing group in the inheritance chain \u2014\\n# or a dropped 1.10.0 field \u2014 trips the test loudly.\\nEXPECTED_FIELDS = {\\n    # PathSettings\\n    \\\"config_dir\\\",\\n    \\\"knowledge_bases_dir\\\",\\n    # ServerSettings\\n    \\\"deployment_profile\\\",\\n    \\\"host\\\",\\n    \\\"port\\\",\\n    \\\"runtime_port\\\",\\n    \\\"workers\\\",\\n    \\\"log_level\\\",\\n    \\\"log_file\\\",\\n    \\\"alembic_log_file\\\",\\n    \\\"alembic_log_to_stdout\\\",\\n    \\\"frontend_path\\\",\\n    \\\"open_browser\\\",\\n    \\\"backend_only\\\",\\n    \\\"ssl_cert_file\\\",\\n    \\\"ssl_key_file\\\",\\n    \\\"root_path\\\",\\n    \\\"user_agent\\\",\\n    # DatabaseSettings\\n    \\\"save_db_in_config_dir\\\",\\n    \\\"database_url\\\",\\n    \\\"database_connection_retry\\\",\\n    \\\"pool_size\\\",\\n    \\\"max_overflow\\\",\\n    \\\"db_connect_timeout\\\",\\n    \\\"migration_lock_namespace\\\",\\n    \\\"sqlite_pragmas\\\",\\n    \\\"db_driver_connection_settings\\\",\\n    \\\"db_connection_settings\\\",\\n    \\\"use_noop_database\\\",\\n    # CacheSettings\\n    \\\"cache_type\\\",\\n    \\\"cache_expire\\\",\\n    \\\"cache_dir\\\",\\n    \\\"langchain_cache\\\",\\n    \\\"redis_host\\\",\\n    \\\"redis_port\\\",\\n    \\\"redis_db\\\",\\n    \\\"redis_url\\\",\\n    \\\"redis_cache_expire\\\",\\n    # StorageSettings\\n    \\\"storage_type\\\",\\n    \\\"object_storage_bucket_name\\\",\\n    \\\"object_storage_prefix\\\",\\n    \\\"object_storage_tags\\\",\\n    # McpSettings\\n    \\\"mcp_base_url\\\",\\n    \\\"mcp_server_timeout\\\",\\n    \\\"mcp_max_sessions_per_server\\\",\\n    \\\"mcp_session_idle_timeout\\\",\\n    \\\"mcp_session_cleanup_interval\\\",\\n    \\\"mcp_server_enabled\\\",\\n    \\\"mcp_sse_enabled\\\",\\n    \\\"mcp_server_enable_progress_notifications\\\",\\n    \\\"add_projects_to_mcp_servers\\\",\\n    \\\"skip_mcp_auto_init\\\",\\n    \\\"mcp_composer_enabled\\\",\\n    \\\"mcp_composer_version\\\",\\n    \\\"mcp_sdk_constraint\\\",\\n    \\\"a2a_enabled\\\",\\n    \\\"a2a_allow_private_webhooks\\\",\\n    # TelemetrySettings\\n    \\\"sentry_dsn\\\",\\n    \\\"sentry_traces_sample_rate\\\",\\n    \\\"sentry_profiles_sample_rate\\\",\\n    \\\"do_not_track\\\",\\n    \\\"telemetry_base_url\\\",\\n    \\\"transactions_storage_enabled\\\",\\n    \\\"vertex_builds_storage_enabled\\\",\\n    \\\"sync_result_storage_enabled\\\",\\n    \\\"deactivate_tracing\\\",\\n    # ObservabilitySettings\\n    \\\"prometheus_enabled\\\",\\n    \\\"prometheus_port\\\",\\n    \\\"max_transactions_to_keep\\\",\\n    \\\"max_vertex_builds_to_keep\\\",\\n    \\\"max_vertex_builds_per_vertex\\\",\\n    \\\"max_flow_version_entries_per_flow\\\",\\n    # SecuritySettings\\n    \\\"cors_origins\\\",\\n    \\\"cors_allow_credentials\\\",\\n    \\\"cors_allow_methods\\\",\\n    \\\"cors_allow_headers\\\",\\n    \\\"ssrf_protection_enabled\\\",\\n    \\\"ssrf_allowed_hosts\\\",\\n    \\\"connector_ssrf_validation_enabled\\\",\\n    \\\"connector_ssrf_allow_loopback\\\",\\n    \\\"disable_track_apikey_usage\\\",\\n    \\\"remove_api_keys\\\",\\n    \\\"allow_custom_components\\\",\\n    \\\"tweaks_policy\\\",\\n    # ComponentsSettings\\n    \\\"components_path\\\",\\n    \\\"components_index_path\\\",\\n    \\\"load_flows_path\\\",\\n    \\\"bundle_urls\\\",\\n    \\\"lazy_load_components\\\",\\n    \\\"create_starter_projects\\\",\\n    \\\"update_starter_projects\\\",\\n    # UiSettings\\n    \\\"auto_saving\\\",\\n    \\\"auto_saving_interval\\\",\\n    \\\"max_text_length\\\",\\n    \\\"max_items_length\\\",\\n    \\\"frontend_timeout\\\",\\n    \\\"store\\\",\\n    \\\"store_url\\\",\\n    \\\"download_webhook_url\\\",\\n    \\\"like_webhook_url\\\",\\n    # RuntimeSettings\\n    \\\"warm_registry_enabled\\\",\\n    \\\"warm_registry_preload_limit\\\",\\n    \\\"warm_registry_max_entries\\\",\\n    \\\"warm_registry_max_flow_bytes\\\",\\n    \\\"warm_registry_max_total_bytes\\\",\\n    \\\"dev\\\",\\n    \\\"warm_reconcile_interval\\\",\\n    \\\"event_delivery\\\",\\n    \\\"worker_timeout\\\",\\n    \\\"workflow_execution_timeout\\\",\\n    \\\"model_provider_policy_refresh_interval_s\\\",\\n    \\\"public_flow_cleanup_interval\\\",\\n    \\\"public_flow_expiration\\\",\\n    \\\"webhook_polling_interval\\\",\\n    \\\"fs_flows_polling_interval\\\",\\n    \\\"health_check_max_retries\\\",\\n    \\\"max_file_size_upload\\\",\\n    \\\"celery_enabled\\\",\\n    # VariablesSettings\\n    \\\"variable_store\\\",\\n    \\\"fallback_to_env_var\\\",\\n    \\\"store_environment_variables\\\",\\n    \\\"variables_to_get_from_environment\\\",\\n    \\\"agentic_experience\\\",\\n    \\\"developer_api_enabled\\\",\\n    # ---- Added after the original Settings split and folded into the mixins ----\\n    # PathSettings\\n    \\\"kb_disk_reconcile_enabled\\\",\\n    \\\"kb_allowed_folder_roots\\\",\\n    \\\"kb_folder_max_file_size_bytes\\\",\\n    \\\"directory_component_allowed_roots\\\",\\n    # McpSettings\\n    \\\"mcp_tool_execution_timeout\\\",\\n    \\\"mcp_servers_locked\\\",\\n    # ComponentsSettings\\n    \\\"load_flows_overwrite_on_name_match\\\",\\n    \\\"load_flows_preserve_variable_bindings\\\",\\n    \\\"enable_extension_reload\\\",\\n    # SecuritySettings\\n    \\\"rate_limit_enabled\\\",\\n    \\\"rate_limit_per_minute\\\",\\n    \\\"rate_limit_storage_uri\\\",\\n    \\\"rate_limit_trust_proxy\\\",\\n    \\\"public_flow_rate_limit_per_minute\\\",\\n    \\\"custom_component_admin_only\\\",\\n    \\\"allow_components_paths_override\\\",\\n    # RuntimeSettings\\n    \\\"job_queue_type\\\",\\n    \\\"redis_queue_host\\\",\\n    \\\"redis_queue_port\\\",\\n    \\\"redis_queue_db\\\",\\n    \\\"redis_queue_url\\\",\\n    \\\"redis_queue_ttl\\\",\\n    \\\"redis_queue_startup_grace_s\\\",\\n    \\\"redis_queue_cancel_channel_enabled\\\",\\n    \\\"redis_queue_cancel_marker_ttl\\\",\\n    \\\"redis_queue_polling_stale_threshold_s\\\",\\n    \\\"redis_queue_polling_watchdog_interval_s\\\",\\n    \\\"max_ingestion_timeout_secs\\\",\\n    \\\"executor_kind\\\",\\n    \\\"dangerously_allow_multi_worker_without_shared_queue\\\",\\n    # UiSettings\\n    \\\"embedded_mode\\\",\\n    \\\"hide_getting_started_progress\\\",\\n    \\\"hide_logout_button\\\",\\n    \\\"hide_new_project_button\\\",\\n    \\\"hide_new_flow_button\\\",\\n    \\\"hide_starter_projects\\\",\\n    # TelemetrySettings\\n    \\\"telemetry_writer_enabled\\\",\\n    \\\"telemetry_writer_batch_size\\\",\\n    \\\"telemetry_writer_flush_interval_s\\\",\\n    \\\"telemetry_writer_cleanup_interval_s\\\",\\n    \\\"telemetry_writer_max_queue\\\",\\n    \\\"telemetry_writer_outbox_dir\\\",\\n    \\\"telemetry_writer_shutdown_drain_s\\\",\\n    \\\"telemetry_writer_orphan_max_age_s\\\",\\n    \\\"telemetry_writer_size_strategy\\\",\\n    \\\"telemetry_writer_batch_size_bytes\\\",\\n    \\\"telemetry_writer_max_queue_bytes\\\",\\n    # Background execution\\n    \\\"background_max_concurrency\\\",\\n    \\\"background_job_timeout\\\",\\n    \\\"background_input_deadline_s\\\",\\n    \\\"background_lease_ttl_s\\\",\\n    \\\"background_heartbeat_interval_s\\\",\\n    \\\"background_watchdog_interval_s\\\",\\n    \\\"test_redis_url\\\",\\n    # ---- Added in 1.10.1 ----\\n    # SecuritySettings\\n    \\\"allow_public_custom_components\\\",\\n    \\\"block_code_interpreter_components\\\",\\n    \\\"restrict_local_file_access\\\",\\n    \\\"mcp_server_docker_hardening\\\",\\n    \\\"mcp_server_allowed_packages\\\",\\n    \\\"mcp_server_interpreter_hardening\\\",\\n    \\\"mcp_server_env_allowlist\\\",\\n    # ---- Added in 1.12.0 ----\\n    # SecuritySettings: opt-in microVM sandbox backend (issue #12029)\\n    \\\"sandbox_backend\\\",\\n    \\\"sandbox_timeout_seconds\\\",\\n    \\\"sandbox_memory_mb\\\",\\n    \\\"sandbox_allow_network\\\",\\n    \\\"sandbox_allowed_domains\\\",\\n    \\\"sandbox_allow_software_emulation\\\",\\n    # SecuritySettings: rebuild drifted built-ins with this server's code (issue #14455)\\n    \\\"substitute_outdated_component_code\\\",\\n    # VariablesSettings: operator-tunable Langflow Assistant prompt length\\n    \\\"assistant_max_message_length\\\",\\n    # ---- Serving-plane end-user identity ----\\n    # SecuritySettings\\n    \\\"serving_end_user_header\\\",\\n    \\\"serving_trust_proxy_headers\\\",\\n    \\\"serving_end_user_required\\\",\\n    \\\"serving_trace_end_user\\\",\\n    \\\"serving_internal_mcp_hosts\\\",\\n}\\n\\n\\ndef test_all_expected_fields_present():\\n    \\\"\\\"\\\"Every field that lived on the monolithic Settings is still present.\\n\\n    Trips loudly if a group is dropped from the inheritance list.\\n    \\\"\\\"\\\"\\n    actual = set(Settings.model_fields)\\n    missing = EXPECTED_FIELDS - actual\\n    assert not missing, f\\\"Settings is missing fields: {sorted(missing)}\\\"\\n\\n\\ndef test_field_count_unchanged():\\n    \\\"\\\"\\\"The total field count matches the curated expected set (no stray adds/drops).\\\"\\\"\\\"\\n    assert len(Settings.model_fields) == len(EXPECTED_FIELDS)\\n\\n\\ndef test_critical_defaults_unchanged():\\n    \\\"\\\"\\\"A sampling of important field defaults survives the split byte-for-byte.\\\"\\\"\\\"\\n    settings = Settings()\\n    assert settings.host == \\\"localhost\\\"\\n    assert settings.port == 7860\\n    assert settings.workers == 1\\n    assert settings.cache_type == \\\"async\\\"\\n    assert settings.storage_type == \\\"local\\\"\\n    assert settings.event_delivery == \\\"streaming\\\"\\n    assert settings.model_provider_policy_refresh_interval_s == 10.0\\n    assert settings.cors_origins == \\\"*\\\"\\n    assert settings.cors_allow_credentials is True\\n    assert settings.ssrf_protection_enabled is True\\n    assert settings.connector_ssrf_validation_enabled is True\\n    assert settings.allow_custom_components is True\\n    assert settings.block_code_interpreter_components is False\\n    assert settings.substitute_outdated_component_code is True\\n    assert settings.restrict_local_file_access is False\\n    assert settings.mcp_server_docker_hardening is False\\n    assert settings.mcp_server_interpreter_hardening is False\\n    assert settings.mcp_server_allowed_packages is None\\n    assert settings.mcp_server_enabled is True\\n    assert settings.mcp_composer_enabled is True\\n    assert settings.mcp_sdk_constraint == \\\"mcp~=1.28\\\"\\n    assert settings.load_flows_preserve_variable_bindings is True\\n    assert settings.do_not_track is False\\n    assert settings.warm_registry_enabled is False\\n    assert settings.warm_registry_preload_limit == 0\\n    assert settings.warm_registry_max_entries == 128\\n    assert settings.warm_registry_max_flow_bytes == 2_000_000\\n    assert settings.warm_registry_max_total_bytes == 32_000_000\\n    assert settings.dev is False\\n    assert settings.agentic_experience is True\\n    assert settings.developer_api_enabled is False\\n    assert settings.dangerously_allow_multi_worker_without_shared_queue is False\\n\\n\\ndef test_dict_defaults_unchanged():\\n    \\\"\\\"\\\"Dict-typed defaults like sqlite_pragmas and db_connection_settings are intact.\\\"\\\"\\\"\\n    settings = Settings()\\n    assert settings.sqlite_pragmas == {\\n        \\\"synchronous\\\": \\\"NORMAL\\\",\\n        \\\"journal_mode\\\": \\\"WAL\\\",\\n        \\\"busy_timeout\\\": 30000,\\n    }\\n    assert settings.db_connection_settings == {\\n        \\\"pool_size\\\": 20,\\n        \\\"max_overflow\\\": 30,\\n        \\\"pool_timeout\\\": 30,\\n        \\\"pool_pre_ping\\\": True,\\n        \\\"pool_recycle\\\": 1800,\\n        \\\"echo\\\": False,\\n    }\\n\\n\\ndef test_multi_worker_forces_direct_event_delivery(monkeypatch):\\n    \\\"\\\"\\\"Workers > 1 must flip event_delivery to 'direct'.\\n\\n    Exercises the cross-group validator dependency: event_delivery lives in\\n    RuntimeSettings, workers lives in ServerSettings, and the inheritance\\n    order in Settings must ensure workers is in info.data when\\n    event_delivery validates.\\n    \\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_WORKERS\\\", \\\"4\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_EVENT_DELIVERY\\\", \\\"streaming\\\")\\n    settings = Settings()\\n    assert settings.workers == 4\\n    assert settings.event_delivery == \\\"direct\\\"\\n\\n\\ndef test_single_worker_keeps_explicit_event_delivery(monkeypatch):\\n    \\\"\\\"\\\"Workers == 1 leaves an explicit event_delivery setting alone.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_WORKERS\\\", \\\"1\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_EVENT_DELIVERY\\\", \\\"polling\\\")\\n    settings = Settings()\\n    assert settings.event_delivery == \\\"polling\\\"\\n\\n\\ndef test_warm_registry_reads_environment(monkeypatch):\\n    \\\"\\\"\\\"The warm execution plane must be independently activatable through settings.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_WARM_REGISTRY_ENABLED\\\", \\\"true\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_WARM_REGISTRY_PRELOAD_LIMIT\\\", \\\"5\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_WARM_REGISTRY_MAX_ENTRIES\\\", \\\"16\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_WARM_REGISTRY_MAX_FLOW_BYTES\\\", \\\"100000\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_WARM_REGISTRY_MAX_TOTAL_BYTES\\\", \\\"1000000\\\")\\n\\n    settings = Settings()\\n    assert settings.warm_registry_enabled is True\\n    assert settings.warm_registry_preload_limit == 5\\n    assert settings.warm_registry_max_entries == 16\\n    assert settings.warm_registry_max_flow_bytes == 100_000\\n    assert settings.warm_registry_max_total_bytes == 1_000_000\\n\\n\\ndef test_database_url_sees_config_dir(monkeypatch, tmp_path):\\n    \\\"\\\"\\\"database_url validator must see config_dir in info.data.\\n\\n    With config_dir set and no LANGFLOW_DATABASE_URL env var, the validator\\n    falls back to a sqlite path under the langflow package directory. If\\n    PathSettings's config_dir wasn't validated first, the validator would\\n    raise 'config_dir not set'.\\n    \\\"\\\"\\\"\\n    monkeypatch.delenv(\\\"LANGFLOW_DATABASE_URL\\\", raising=False)\\n    monkeypatch.setenv(\\\"LANGFLOW_CONFIG_DIR\\\", str(tmp_path))\\n    settings = Settings()\\n    assert settings.database_url.startswith(\\\"sqlite:///\\\")\\n    assert settings.config_dir == str(tmp_path)\\n\\n\\ndef test_back_compat_exports():\\n    \\\"\\\"\\\"Symbols that consumers import from settings.base are still exported.\\\"\\\"\\\"\\n    assert is_list_of_any is not None\\n    assert CustomSource is not None\\n    assert save_settings_to_yaml is not None\\n    assert load_settings_from_yaml is not None\\n    assert isinstance(BASE_COMPONENTS_PATH, str)\\n\\n\\ndef test_update_settings_scalar():\\n    \\\"\\\"\\\"Settings.update_settings replaces scalar fields.\\\"\\\"\\\"\\n    settings = Settings()\\n    settings.update_settings(port=9999)\\n    assert settings.port == 9999\\n\\n\\ndef test_update_settings_list_appends_unique():\\n    \\\"\\\"\\\"Settings.update_settings appends to list fields without duplicates.\\\"\\\"\\\"\\n    settings = Settings()\\n    before = list(settings.bundle_urls)\\n    settings.update_settings(bundle_urls=\\\"https://example.com/bundle\\\")\\n    assert \\\"https://example.com/bundle\\\" in settings.bundle_urls\\n    # Applying twice doesn't duplicate\\n    settings.update_settings(bundle_urls=\\\"https://example.com/bundle\\\")\\n    assert settings.bundle_urls.count(\\\"https://example.com/bundle\\\") == 1\\n    # Original entries untouched\\n    for url in before:\\n        assert url in settings.bundle_urls\\n\\n\\ndef test_yaml_round_trip():\\n    \\\"\\\"\\\"save_settings_to_yaml + load_settings_from_yaml preserves field values.\\\"\\\"\\\"\\n    settings = Settings()\\n    original_components = list(settings.components_path)\\n\\n    with tempfile.NamedTemporaryFile(\\\"w\\\", suffix=\\\".yaml\\\", delete=False) as f:\\n        yaml_path = f.name\\n    try:\\n        save_settings_to_yaml(settings, yaml_path)\\n        assert Path(yaml_path).exists()\\n        # load_settings_from_yaml only reads components_path back today, but\\n        # the helper should at least round-trip without erroring on a full dump.\\n        # We don't assert deep equality because the yaml loader currently\\n        # restricts to a subset of fields by design.\\n    finally:\\n        Path(yaml_path).unlink(missing_ok=True)\\n\\n    # components_path should be the same after re-instantiation with no env changes\\n    settings2 = Settings()\\n    assert settings2.components_path == original_components\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"env_var\\\", \\\"env_value\\\", \\\"field\\\", \\\"expected\\\"),\\n    [\\n        (\\\"LANGFLOW_HOST\\\", \\\"0.0.0.0\\\", \\\"host\\\", \\\"0.0.0.0\\\"),\\n        (\\\"LANGFLOW_PORT\\\", \\\"8080\\\", \\\"port\\\", 8080),\\n        (\\\"LANGFLOW_WORKERS\\\", \\\"2\\\", \\\"workers\\\", 2),\\n        (\\\"LANGFLOW_LOG_LEVEL\\\", \\\"info\\\", \\\"log_level\\\", \\\"info\\\"),\\n        (\\\"LANGFLOW_CACHE_TYPE\\\", \\\"memory\\\", \\\"cache_type\\\", \\\"memory\\\"),\\n        (\\\"LANGFLOW_STORAGE_TYPE\\\", \\\"s3\\\", \\\"storage_type\\\", \\\"s3\\\"),\\n        (\\\"LANGFLOW_PROMETHEUS_ENABLED\\\", \\\"true\\\", \\\"prometheus_enabled\\\", True),\\n        (\\\"LANGFLOW_PROMETHEUS_PORT\\\", \\\"9999\\\", \\\"prometheus_port\\\", 9999),\\n        (\\\"LANGFLOW_MCP_SERVER_ENABLED\\\", \\\"false\\\", \\\"mcp_server_enabled\\\", False),\\n        (\\\"LANGFLOW_MCP_SSE_ENABLED\\\", \\\"false\\\", \\\"mcp_sse_enabled\\\", False),\\n        (\\\"LANGFLOW_MCP_SDK_CONSTRAINT\\\", \\\"mcp~=1.30\\\", \\\"mcp_sdk_constraint\\\", \\\"mcp~=1.30\\\"),\\n        (\\\"LANGFLOW_SKIP_MCP_AUTO_INIT\\\", \\\"true\\\", \\\"skip_mcp_auto_init\\\", True),\\n        (\\\"LANGFLOW_DO_NOT_TRACK\\\", \\\"true\\\", \\\"do_not_track\\\", True),\\n        (\\\"LANGFLOW_DEV\\\", \\\"true\\\", \\\"dev\\\", True),\\n        (\\n            \\\"LANGFLOW_MODEL_PROVIDER_POLICY_REFRESH_INTERVAL_S\\\",\\n            \\\"7.5\\\",\\n            \\\"model_provider_policy_refresh_interval_s\\\",\\n            7.5,\\n        ),\\n        (\\\"LANGFLOW_BACKEND_ONLY\\\", \\\"true\\\", \\\"backend_only\\\", True),\\n        (\\\"LANGFLOW_AUTO_SAVING\\\", \\\"false\\\", \\\"auto_saving\\\", False),\\n        (\\\"LANGFLOW_FALLBACK_TO_ENV_VAR\\\", \\\"false\\\", \\\"fallback_to_env_var\\\", False),\\n        (\\n            \\\"LANGFLOW_LOAD_FLOWS_PRESERVE_VARIABLE_BINDINGS\\\",\\n            \\\"false\\\",\\n            \\\"load_flows_preserve_variable_bindings\\\",\\n            False,\\n        ),\\n        (\\\"LANGFLOW_VARIABLE_STORE\\\", \\\"kubernetes\\\", \\\"variable_store\\\", \\\"kubernetes\\\"),\\n    ],\\n)\\ndef test_env_var_round_trip(monkeypatch, env_var, env_value, field, expected):\\n    \\\"\\\"\\\"A sampling of LANGFLOW_* env vars still populate the right fields.\\\"\\\"\\\"\\n    monkeypatch.setenv(env_var, env_value)\\n    settings = Settings()\\n    assert getattr(settings, field) == expected\\n\\n\\ndef test_agentic_experience_on_by_default(monkeypatch):\\n    \\\"\\\"\\\"The Assistant is Langflow's entry-point experience and must work out of the box.\\n\\n    Regression: defaulting agentic_experience off left the frontend Assistant panel\\n    mounted while every /agentic endpoint returned 404 unless the operator set\\n    LANGFLOW_AGENTIC_EXPERIENCE=true. With the experience on, its variables are\\n    mirrored from the environment so provider credentials resolve.\\n    \\\"\\\"\\\"\\n    monkeypatch.delenv(\\\"LANGFLOW_AGENTIC_EXPERIENCE\\\", raising=False)\\n    settings = Settings()\\n    assert settings.agentic_experience is True\\n    for var in AGENTIC_VARIABLES:\\n        assert var in settings.variables_to_get_from_environment\\n\\n\\n@pytest.mark.parametrize(\\\"env_value\\\", [\\\"true\\\", \\\"1\\\", \\\"yes\\\", \\\"on\\\"])\\ndef test_agentic_variables_included_when_experience_enabled(monkeypatch, env_value):\\n    \\\"\\\"\\\"All supported true values keep the feature and its environment mirror aligned.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_AGENTIC_EXPERIENCE\\\", env_value)\\n    settings = Settings()\\n    assert settings.agentic_experience is True\\n    for var in AGENTIC_VARIABLES:\\n        assert var in settings.variables_to_get_from_environment\\n\\n\\ndef test_agentic_variables_excluded_when_experience_disabled(monkeypatch):\\n    \\\"\\\"\\\"Opting out with LANGFLOW_AGENTIC_EXPERIENCE=false stops the env mirror.\\n\\n    The ASTRA_TOKEN credential is among the mirrored variables; a deployment that\\n    disables the Assistant must not have it provisioned into the DB for endpoints\\n    that stay 404.\\n    \\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_AGENTIC_EXPERIENCE\\\", \\\"false\\\")\\n    settings = Settings()\\n    assert settings.agentic_experience is False\\n    for var in AGENTIC_VARIABLES:\\n        assert var not in settings.variables_to_get_from_environment\\n\\n\\ndef test_serving_end_user_defaults_are_feature_off():\\n    \\\"\\\"\\\"The serving-plane end-user identity feature is off by default (backwards compatible).\\\"\\\"\\\"\\n    settings = Settings()\\n    assert settings.serving_end_user_header is None\\n    assert settings.serving_trust_proxy_headers is False\\n    assert settings.serving_end_user_required is False\\n\\n\\ndef test_serving_end_user_env_vars_bind_to_fields(monkeypatch):\\n    \\\"\\\"\\\"The three operator-facing env vars must bind to their settings fields.\\n\\n    This guards the operator contract: a typo in a field name or the LANGFLOW_\\n    prefix would silently disable the feature with no other test catching it.\\n    \\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_SERVING_END_USER_HEADER\\\", \\\"X-End-User-Id\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_SERVING_TRUST_PROXY_HEADERS\\\", \\\"true\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_SERVING_END_USER_REQUIRED\\\", \\\"true\\\")\\n    settings = Settings()\\n    assert settings.serving_end_user_header == \\\"X-End-User-Id\\\"\\n    assert settings.serving_trust_proxy_headers is True\\n    assert settings.serving_end_user_required is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/test_adapter_registry_concurrency.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fb806eacae10c26f6e5bc71154de645f59b5ef03050c5055c511db830ffdd045\",\"content\":\"\\\"\\\"\\\"Concurrency tests for generic adapter registry.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport threading\\nimport time\\nfrom concurrent.futures import ThreadPoolExecutor\\n\\nimport pytest\\n\\nfrom tests.unit.services.adapter_test_helpers import DeploymentAdapterStub, make_deployment_adapter_registry\\n\\n\\nclass DummyEntryPointAdapter(DeploymentAdapterStub):\\n    pass\\n\\n\\npytestmark = pytest.mark.usefixtures(\\\"clean_adapter_globals\\\")\\n\\n\\ndef test_get_instance_is_thread_safe_singleton_creation():\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"local\\\", DummyEntryPointAdapter)\\n    factory_calls = 0\\n    factory_lock = threading.Lock()\\n\\n    def factory(adapter_class):\\n        nonlocal factory_calls\\n        with factory_lock:\\n            factory_calls += 1\\n        return adapter_class()\\n\\n    def resolve_instance(_):\\n        return registry.get_instance(\\\"local\\\", factory=factory)\\n\\n    with ThreadPoolExecutor(max_workers=8) as pool:\\n        instances = list(pool.map(resolve_instance, range(50)))\\n\\n    assert instances\\n    first = instances[0]\\n    assert first is not None\\n    assert all(instance is first for instance in instances)\\n    assert factory_calls == 1\\n\\n\\ndef test_discover_is_thread_safe_runs_inner_discovery_once(tmp_path, monkeypatch):\\n    registry = make_deployment_adapter_registry()\\n    call_count = 0\\n    call_count_lock = threading.Lock()\\n\\n    def counted_entry_points():\\n        nonlocal call_count\\n        time.sleep(0.02)\\n        with call_count_lock:\\n            call_count += 1\\n\\n    monkeypatch.setattr(registry, \\\"_discover_from_entry_points\\\", counted_entry_points)\\n    monkeypatch.setattr(registry, \\\"_discover_from_config\\\", lambda **_: None)\\n\\n    def run_discover(_):\\n        registry.discover(config_dir=tmp_path)\\n\\n    with ThreadPoolExecutor(max_workers=8) as pool:\\n        list(pool.map(run_discover, range(8)))\\n\\n    assert registry.is_discovered is True\\n    assert call_count == 1\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/test_adapter_registry_discovery.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6ebb98eed92023e471c30d87fd2df4476078374db33cb40feee6326367831d7f\",\"content\":\"\\\"\\\"\\\"Discovery and registration tests for generic adapter registry.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom lfx.services.adapters import registry as adapter_registry_mod\\nfrom lfx.services.adapters.schema import AdapterType\\n\\nfrom tests.unit.services.adapter_test_helpers import DeploymentAdapterStub, make_deployment_adapter_registry\\n\\n\\nclass DummyDecoratorAdapter(DeploymentAdapterStub):\\n    pass\\n\\n\\nclass DummyEntryPointAdapter(DeploymentAdapterStub):\\n    pass\\n\\n\\nclass DummyConfigAdapter(DeploymentAdapterStub):\\n    pass\\n\\n\\nclass DummyAlternateAdapter(DeploymentAdapterStub):\\n    pass\\n\\n\\nclass DummyEntryPoint:\\n    \\\"\\\"\\\"Simple entry point stub for importlib.metadata.entry_points().\\\"\\\"\\\"\\n\\n    def __init__(self, name: str, obj: type):\\n        self.name = name\\n        self._obj = obj\\n\\n    def load(self):\\n        return self._obj\\n\\n\\npytestmark = pytest.mark.usefixtures(\\\"clean_adapter_globals\\\")\\n\\n\\ndef test_get_adapter_registry_singleton():\\n    first = make_deployment_adapter_registry()\\n    second = make_deployment_adapter_registry()\\n\\n    assert first is second\\n\\n\\ndef test_get_adapter_registry_raises_on_parameter_mismatch_for_same_adapter_type():\\n    make_deployment_adapter_registry()\\n\\n    with pytest.raises(adapter_registry_mod.AdapterRegistryConflictError):\\n        adapter_registry_mod.get_adapter_registry(\\n            adapter_type=AdapterType.DEPLOYMENT,\\n            entry_point_group=\\\"lfx.OTHER.group\\\",\\n            config_section_path=(\\\"other\\\", \\\"path\\\"),\\n        )\\n\\n\\ndef test_get_adapter_registry_convention_defaults():\\n    \\\"\\\"\\\"Convention-derived params match explicit equivalents.\\\"\\\"\\\"\\n    registry = adapter_registry_mod.get_adapter_registry(adapter_type=AdapterType.DEPLOYMENT)\\n\\n    assert registry.entry_point_group == \\\"lfx.deployment.adapters\\\"\\n    assert registry.config_section_path == (\\\"deployment\\\", \\\"adapters\\\")\\n\\n\\ndef test_discovery_precedence_entrypoint_decorator_config(tmp_path, monkeypatch):\\n    registry = make_deployment_adapter_registry()\\n\\n    monkeypatch.setattr(\\n        \\\"importlib.metadata.entry_points\\\",\\n        lambda group: [DummyEntryPoint(\\\"local\\\", DummyEntryPointAdapter)] if group == \\\"lfx.deployment.adapters\\\" else [],\\n    )\\n\\n    adapter_registry_mod.register_adapter(AdapterType.DEPLOYMENT, \\\"local\\\")(DummyDecoratorAdapter)\\n\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        f\\\"\\\"\\\"\\n[deployment.adapters]\\nlocal = \\\"{__name__}:DummyConfigAdapter\\\"\\n\\\"\\\"\\\"\\n    )\\n\\n    registry.discover(config_dir=tmp_path)\\n\\n    assert registry.get_class(\\\"local\\\") is DummyConfigAdapter\\n\\n\\ndef test_lfx_toml_takes_precedence_over_pyproject(tmp_path):\\n    registry = make_deployment_adapter_registry()\\n\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        f\\\"\\\"\\\"\\n[deployment.adapters]\\nlocal = \\\"{__name__}:DummyConfigAdapter\\\"\\n\\\"\\\"\\\"\\n    )\\n    (tmp_path / \\\"pyproject.toml\\\").write_text(\\n        f\\\"\\\"\\\"\\n[tool.lfx.deployment.adapters]\\nlocal = \\\"{__name__}:DummyAlternateAdapter\\\"\\n\\\"\\\"\\\"\\n    )\\n\\n    registry.discover(config_dir=tmp_path)\\n\\n    assert registry.get_class(\\\"local\\\") is DummyConfigAdapter\\n\\n\\ndef test_discover_only_once(tmp_path):\\n    registry = make_deployment_adapter_registry()\\n\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        f\\\"\\\"\\\"\\n[deployment.adapters]\\nlocal = \\\"{__name__}:DummyConfigAdapter\\\"\\n\\\"\\\"\\\"\\n    )\\n    registry.discover(config_dir=tmp_path)\\n    assert registry.get_class(\\\"local\\\") is DummyConfigAdapter\\n\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        f\\\"\\\"\\\"\\n[deployment.adapters]\\nlocal = \\\"{__name__}:DummyAlternateAdapter\\\"\\n\\\"\\\"\\\"\\n    )\\n    registry.discover(config_dir=tmp_path)\\n\\n    assert registry.get_class(\\\"local\\\") is DummyConfigAdapter\\n\\n\\ndef test_invalid_import_path_is_ignored(tmp_path):\\n    registry = make_deployment_adapter_registry()\\n\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        \\\"\\\"\\\"\\n[deployment.adapters]\\nlocal = \\\"invalid_without_colon\\\"\\n\\\"\\\"\\\"\\n    )\\n\\n    registry.discover(config_dir=tmp_path)\\n\\n    assert registry.get_class(\\\"local\\\") is None\\n\\n\\ndef test_register_class_override_false_preserves_existing():\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"local\\\", DummyEntryPointAdapter, override=True)\\n    registry.register_class(\\\"local\\\", DummyDecoratorAdapter, override=False)\\n\\n    assert registry.get_class(\\\"local\\\") is DummyEntryPointAdapter\\n\\n\\ndef test_decorator_override_false_wins_over_entrypoint(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"Decorator registers at import time (before discover), so it wins.\\n\\n    Both sources use override=False.  The decorator fires first, and the\\n    entry point can't overwrite it.  This mirrors ``@register_service``\\n    behavior for top-level services.\\n    \\\"\\\"\\\"\\n    registry = make_deployment_adapter_registry()\\n    monkeypatch.setattr(\\n        \\\"importlib.metadata.entry_points\\\",\\n        lambda group: [DummyEntryPoint(\\\"local\\\", DummyEntryPointAdapter)] if group == \\\"lfx.deployment.adapters\\\" else [],\\n    )\\n    adapter_registry_mod.register_adapter(\\n        AdapterType.DEPLOYMENT,\\n        \\\"local\\\",\\n        override=False,\\n    )(DummyDecoratorAdapter)\\n\\n    registry.discover(config_dir=tmp_path)\\n\\n    assert registry.get_class(\\\"local\\\") is DummyDecoratorAdapter\\n\\n\\ndef test_decorator_override_false_skips_when_same_key_already_decorated(tmp_path):\\n    adapter_registry_mod.register_adapter(AdapterType.DEPLOYMENT, \\\"local\\\")(DummyDecoratorAdapter)\\n    adapter_registry_mod.register_adapter(AdapterType.DEPLOYMENT, \\\"local\\\", override=False)(DummyAlternateAdapter)\\n\\n    registry = make_deployment_adapter_registry()\\n    registry.discover(config_dir=tmp_path)\\n\\n    assert registry.get_class(\\\"local\\\") is DummyDecoratorAdapter\\n\\n\\ndef test_list_keys_is_sorted():\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"zeta\\\", DummyEntryPointAdapter)\\n    registry.register_class(\\\"alpha\\\", DummyDecoratorAdapter)\\n\\n    assert registry.list_keys() == [\\\"alpha\\\", \\\"zeta\\\"]\\n\\n\\ndef test_repr_before_and_after_discovery(tmp_path):\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"local\\\", DummyEntryPointAdapter)\\n\\n    r = repr(registry)\\n    assert \\\"adapter_type=<AdapterType.DEPLOYMENT: 'deployment'>\\\" in r\\n    assert \\\"keys=['local']\\\" in r\\n    assert \\\"discovered=False\\\" in r\\n\\n    registry.discover(config_dir=tmp_path)\\n    assert \\\"discovered=True\\\" in repr(registry)\\n\\n\\ndef test_pyproject_only_discovery(tmp_path):\\n    registry = make_deployment_adapter_registry()\\n    (tmp_path / \\\"pyproject.toml\\\").write_text(\\n        f\\\"\\\"\\\"\\n[tool.lfx.deployment.adapters]\\nlocal = \\\"{__name__}:DummyConfigAdapter\\\"\\n\\\"\\\"\\\"\\n    )\\n\\n    registry.discover(config_dir=tmp_path)\\n\\n    assert registry.get_class(\\\"local\\\") is DummyConfigAdapter\\n\\n\\ndef test_discovery_handles_malformed_toml(tmp_path):\\n    registry = make_deployment_adapter_registry()\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        \\\"\\\"\\\"\\n[deployment.adapters\\nlocal = \\\"pathlib:Path\\\"\\n\\\"\\\"\\\"\\n    )\\n\\n    registry.discover(config_dir=tmp_path)\\n    assert registry.get_class(\\\"local\\\") is None\\n\\n\\ndef test_discovery_ignores_missing_or_empty_section(tmp_path):\\n    registry = make_deployment_adapter_registry()\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        \\\"\\\"\\\"\\n[other]\\nkey = \\\"value\\\"\\n\\\"\\\"\\\"\\n    )\\n\\n    registry.discover(config_dir=tmp_path)\\n    assert registry.list_keys() == []\\n\\n\\ndef test_entry_point_load_failure_does_not_abort_discovery(tmp_path, monkeypatch):\\n    registry = make_deployment_adapter_registry()\\n\\n    class BrokenEntryPoint:\\n        name = \\\"broken\\\"\\n\\n        def load(self):\\n            msg = \\\"boom\\\"\\n            raise RuntimeError(msg)\\n\\n    monkeypatch.setattr(\\n        \\\"importlib.metadata.entry_points\\\",\\n        lambda group: [BrokenEntryPoint()] if group == \\\"lfx.deployment.adapters\\\" else [],\\n    )\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        f\\\"\\\"\\\"\\n[deployment.adapters]\\nlocal = \\\"{__name__}:DummyConfigAdapter\\\"\\n\\\"\\\"\\\"\\n    )\\n\\n    registry.discover(config_dir=tmp_path)\\n    assert registry.get_class(\\\"local\\\") is DummyConfigAdapter\\n\\n\\ndef test_get_nested_section_returns_none_for_non_dict_path():\\n    from lfx.services.config_discovery import get_nested_section\\n\\n    nested = {\\\"tool\\\": {\\\"lfx\\\": {\\\"deployment\\\": \\\"not-a-dict\\\"}}}\\n\\n    section = get_nested_section(nested, (\\\"tool\\\", \\\"lfx\\\", \\\"deployment\\\", \\\"adapters\\\"))\\n    assert section is None\\n\\n\\ndef test_config_with_nonexistent_module_is_ignored(tmp_path):\\n    \\\"\\\"\\\"Config referencing a module that cannot be imported is skipped.\\\"\\\"\\\"\\n    registry = make_deployment_adapter_registry()\\n\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        \\\"\\\"\\\"\\n[deployment.adapters]\\nlocal = \\\"nonexistent_pkg_xyz.adapters:Adapter\\\"\\n\\\"\\\"\\\"\\n    )\\n\\n    registry.discover(config_dir=tmp_path)\\n    assert registry.get_class(\\\"local\\\") is None\\n\\n\\ndef test_config_with_nonexistent_class_in_valid_module_is_ignored(tmp_path):\\n    \\\"\\\"\\\"Config referencing a real module but missing class is skipped.\\\"\\\"\\\"\\n    registry = make_deployment_adapter_registry()\\n\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        \\\"\\\"\\\"\\n[deployment.adapters]\\nlocal = \\\"pathlib:TotallyMadeUpClassName\\\"\\n\\\"\\\"\\\"\\n    )\\n\\n    registry.discover(config_dir=tmp_path)\\n    assert registry.get_class(\\\"local\\\") is None\\n\\n\\ndef test_config_with_non_string_value_is_ignored(tmp_path):\\n    registry = make_deployment_adapter_registry()\\n\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        \\\"\\\"\\\"\\n[deployment.adapters]\\nlocal = 42\\n\\\"\\\"\\\"\\n    )\\n\\n    registry.discover(config_dir=tmp_path)\\n    assert registry.get_class(\\\"local\\\") is None\\n\\n\\ndef test_multi_key_discovery_across_sources(tmp_path, monkeypatch):\\n    registry = make_deployment_adapter_registry()\\n\\n    monkeypatch.setattr(\\n        \\\"importlib.metadata.entry_points\\\",\\n        lambda group: (\\n            [DummyEntryPoint(\\\"ep_only\\\", DummyEntryPointAdapter)] if group == \\\"lfx.deployment.adapters\\\" else []\\n        ),\\n    )\\n\\n    adapter_registry_mod.register_adapter(AdapterType.DEPLOYMENT, \\\"dec_only\\\")(DummyDecoratorAdapter)\\n\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        f\\\"\\\"\\\"\\n[deployment.adapters]\\ncfg_only = \\\"{__name__}:DummyConfigAdapter\\\"\\n\\\"\\\"\\\"\\n    )\\n\\n    registry.discover(config_dir=tmp_path)\\n\\n    assert registry.get_class(\\\"ep_only\\\") is DummyEntryPointAdapter\\n    assert registry.get_class(\\\"dec_only\\\") is DummyDecoratorAdapter\\n    assert registry.get_class(\\\"cfg_only\\\") is DummyConfigAdapter\\n    assert registry.list_keys() == [\\\"cfg_only\\\", \\\"dec_only\\\", \\\"ep_only\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/test_adapter_registry_lifecycle.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0cb5a482c03ae407c10c9993d5e3f4d590dc8564960bebf644e54fe686eff214\",\"content\":\"\\\"\\\"\\\"Instance lifecycle tests for generic adapter registry.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom lfx.services.adapters import registry as adapter_registry_mod\\n\\nfrom tests.unit.services.adapter_test_helpers import DeploymentAdapterStub, make_deployment_adapter_registry\\n\\n\\nclass DummyEntryPointAdapter(DeploymentAdapterStub):\\n    pass\\n\\n\\nclass DummyTeardownAdapter(DeploymentAdapterStub):\\n    \\\"\\\"\\\"Adapter stub that tracks teardown calls via an external list.\\n\\n    Each test that uses this must provide its own ``teardown_log`` list\\n    to avoid shared mutable class-level state across parallel tests.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, *, teardown_log: list[str] | None = None):\\n        self._teardown_log = teardown_log if teardown_log is not None else []\\n\\n    async def teardown(self):\\n        self._teardown_log.append(\\\"teardown\\\")\\n\\n\\npytestmark = pytest.mark.usefixtures(\\\"clean_adapter_globals\\\")\\n\\n\\ndef test_get_instance_returns_singleton_for_same_key():\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"local\\\", DummyEntryPointAdapter)\\n    factory_calls = 0\\n\\n    def factory(adapter_class):\\n        nonlocal factory_calls\\n        factory_calls += 1\\n        return adapter_class()\\n\\n    first = registry.get_instance(\\\"local\\\", factory=factory)\\n    second = registry.get_instance(\\\"local\\\", factory=factory)\\n\\n    assert first is not None\\n    assert first is second\\n    assert factory_calls == 1\\n\\n\\ndef test_get_instance_returns_none_for_unknown_key():\\n    registry = make_deployment_adapter_registry()\\n\\n    instance = registry.get_instance(\\\"missing\\\", factory=lambda adapter_class: adapter_class())\\n\\n    assert instance is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_teardown_instances_clears_cache_and_recreates():\\n    teardown_log: list[str] = []\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"local\\\", DummyTeardownAdapter)\\n\\n    first = registry.get_instance(\\\"local\\\", factory=lambda cls: cls(teardown_log=teardown_log))\\n    assert first is not None\\n\\n    await registry.teardown_instances()\\n\\n    second = registry.get_instance(\\\"local\\\", factory=lambda cls: cls(teardown_log=teardown_log))\\n    assert second is not None\\n    assert second is not first\\n    assert len(teardown_log) == 1\\n\\n\\n@pytest.mark.asyncio\\nasync def test_teardown_all_adapter_registries_clears_instances():\\n    teardown_log: list[str] = []\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"local\\\", DummyTeardownAdapter)\\n    registry.get_instance(\\\"local\\\", factory=lambda cls: cls(teardown_log=teardown_log))\\n\\n    await adapter_registry_mod.teardown_all_adapter_registries()\\n\\n    assert not registry.has_cached_instances()\\n    assert len(teardown_log) == 1\\n\\n\\ndef test_get_deployment_adapter_returns_singleton_instance():\\n    from lfx.services.deps import get_deployment_adapter\\n\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"unit\\\", DummyEntryPointAdapter)\\n\\n    first = get_deployment_adapter(\\\"unit\\\")\\n    second = get_deployment_adapter(\\\"unit\\\")\\n\\n    assert first is not None\\n    assert first is second\\n\\n\\ndef test_get_deployment_adapter_returns_none_for_unknown_key():\\n    from lfx.services.deps import get_deployment_adapter\\n\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"known\\\", DummyEntryPointAdapter)\\n\\n    result = get_deployment_adapter(\\\"nonexistent\\\")\\n\\n    assert result is None\\n\\n\\ndef test_register_class_evicts_stale_cached_instance():\\n    \\\"\\\"\\\"Re-registering a key with a different class evicts the cached instance.\\\"\\\"\\\"\\n\\n    class AdapterA(DeploymentAdapterStub):\\n        pass\\n\\n    class AdapterB(DeploymentAdapterStub):\\n        pass\\n\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"local\\\", AdapterA)\\n    first = registry.get_instance(\\\"local\\\", factory=lambda cls: cls())\\n    assert isinstance(first, AdapterA)\\n\\n    registry.register_class(\\\"local\\\", AdapterB, override=True)\\n    second = registry.get_instance(\\\"local\\\", factory=lambda cls: cls())\\n    assert isinstance(second, AdapterB)\\n    assert second is not first\\n\\n\\ndef test_factory_exception_does_not_poison_cache():\\n    \\\"\\\"\\\"A failing factory should not prevent subsequent successful creation.\\\"\\\"\\\"\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"local\\\", DummyEntryPointAdapter)\\n    call_count = 0\\n\\n    def failing_then_succeeding_factory(adapter_class):\\n        nonlocal call_count\\n        call_count += 1\\n        if call_count == 1:\\n            msg = \\\"factory failed\\\"\\n            raise RuntimeError(msg)\\n        return adapter_class()\\n\\n    with pytest.raises(RuntimeError, match=\\\"factory failed\\\"):\\n        registry.get_instance(\\\"local\\\", factory=failing_then_succeeding_factory)\\n\\n    instance = registry.get_instance(\\\"local\\\", factory=failing_then_succeeding_factory)\\n    assert instance is not None\\n    assert isinstance(instance, DummyEntryPointAdapter)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_teardown_exception_does_not_prevent_other_teardowns():\\n    \\\"\\\"\\\"If one adapter's teardown raises, other adapters still get torn down.\\\"\\\"\\\"\\n\\n    class FailingTeardownAdapter(DeploymentAdapterStub):\\n        async def teardown(self):\\n            msg = \\\"boom\\\"\\n            raise RuntimeError(msg)\\n\\n    class TrackingTeardownAdapter(DeploymentAdapterStub):\\n        teardown_called = False\\n\\n        async def teardown(self):\\n            type(self).teardown_called = True\\n\\n    TrackingTeardownAdapter.teardown_called = False\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"failing\\\", FailingTeardownAdapter)\\n    registry.register_class(\\\"tracking\\\", TrackingTeardownAdapter)\\n    registry.get_instance(\\\"failing\\\", factory=lambda cls: cls())\\n    registry.get_instance(\\\"tracking\\\", factory=lambda cls: cls())\\n\\n    await registry.teardown_instances()\\n\\n    assert TrackingTeardownAdapter.teardown_called\\n    assert not registry.has_cached_instances()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_sync_teardown_is_called():\\n    \\\"\\\"\\\"Adapters with a synchronous teardown() should still be called.\\\"\\\"\\\"\\n    calls: list[str] = []\\n\\n    class SyncTeardownAdapter(DeploymentAdapterStub):\\n        def teardown(self):\\n            calls.append(\\\"torn_down\\\")\\n\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"sync\\\", SyncTeardownAdapter)\\n    registry.get_instance(\\\"sync\\\", factory=lambda cls: cls())\\n\\n    await registry.teardown_instances()\\n\\n    assert calls == [\\\"torn_down\\\"]\\n    assert not registry.has_cached_instances()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_adapter_without_teardown_does_not_raise():\\n    \\\"\\\"\\\"Adapters with no teardown method should be cleaned up without error.\\\"\\\"\\\"\\n\\n    class NoTeardownAdapter(DeploymentAdapterStub):\\n        teardown = None  # type: ignore[assignment]\\n\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"plain\\\", NoTeardownAdapter)\\n    registry.get_instance(\\\"plain\\\", factory=lambda cls: cls())\\n\\n    await registry.teardown_instances()\\n\\n    assert not registry.has_cached_instances()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_reset_registries_clears_global_state():\\n    \\\"\\\"\\\"_reset_registries tears down instances and clears the global registry dict.\\\"\\\"\\\"\\n    teardown_log: list[str] = []\\n    registry = make_deployment_adapter_registry()\\n    registry.register_class(\\\"local\\\", DummyTeardownAdapter)\\n    registry.get_instance(\\\"local\\\", factory=lambda cls: cls(teardown_log=teardown_log))\\n\\n    await adapter_registry_mod._reset_registries()\\n\\n    assert len(teardown_log) == 1\\n    # A new call should create a fresh registry (not the same object).\\n    new_registry = make_deployment_adapter_registry()\\n    assert new_registry is not registry\\n    assert new_registry.list_keys() == []\\n\\n\\ndef test_get_deployment_adapter_triggers_auto_discovery(tmp_path, monkeypatch):\\n    \\\"\\\"\\\"get_deployment_adapter should auto-discover from config on first call.\\\"\\\"\\\"\\n    from lfx.services.deps import get_deployment_adapter\\n\\n    (tmp_path / \\\"lfx.toml\\\").write_text(\\n        f\\\"\\\"\\\"\\n[deployment.adapters]\\nlocal = \\\"{__name__}:DummyEntryPointAdapter\\\"\\n\\\"\\\"\\\"\\n    )\\n    monkeypatch.setattr(\\n        \\\"lfx.services.deps._resolve_adapter_config_dir\\\",\\n        lambda: tmp_path,\\n    )\\n\\n    # Registry should not be discovered yet.\\n    registry = make_deployment_adapter_registry()\\n    assert not registry.is_discovered\\n\\n    result = get_deployment_adapter(\\\"local\\\")\\n\\n    assert registry.is_discovered\\n    assert result is not None\\n    assert isinstance(result, DummyEntryPointAdapter)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/test_config_discovery.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"92c9302ba0590ac95083555a9d6f90d94d0d268e03cb8a8f433a661ae3cb2468\",\"content\":\"\\\"\\\"\\\"Tests for shared config discovery helpers.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom pathlib import Path\\nfrom unittest.mock import MagicMock\\n\\nfrom lfx.services.config_discovery import resolve_config_dir\\n\\n\\nclass TestResolveConfigDir:\\n    \\\"\\\"\\\"Tests for resolve_config_dir resolution branches.\\\"\\\"\\\"\\n\\n    def test_explicit_path_is_returned_as_is(self):\\n        result = resolve_config_dir(Path(\\\"/explicit/path\\\"))\\n        assert result == Path(\\\"/explicit/path\\\")\\n\\n    def test_explicit_string_is_converted_to_path(self):\\n        result = resolve_config_dir(\\\"/explicit/string\\\")\\n        assert result == Path(\\\"/explicit/string\\\")\\n\\n    def test_settings_service_config_dir_is_used_when_no_explicit(self):\\n        settings_service = MagicMock()\\n        settings_service.settings.config_dir = \\\"/from/settings\\\"\\n\\n        result = resolve_config_dir(None, settings_service=settings_service)\\n\\n        assert result == Path(\\\"/from/settings\\\")\\n\\n    def test_falls_back_to_cwd_when_no_explicit_and_no_settings(self):\\n        result = resolve_config_dir(None)\\n        assert result == Path.cwd()\\n\\n    def test_falls_back_to_cwd_when_settings_service_is_none(self):\\n        result = resolve_config_dir(None, settings_service=None)\\n        assert result == Path.cwd()\\n\\n    def test_falls_back_to_cwd_when_settings_has_no_settings_attr(self):\\n        settings_service = object()  # no .settings attribute\\n        result = resolve_config_dir(None, settings_service=settings_service)\\n        assert result == Path.cwd()\\n\\n    def test_falls_back_to_cwd_when_config_dir_is_empty_string(self):\\n        settings_service = MagicMock()\\n        settings_service.settings.config_dir = \\\"\\\"\\n\\n        result = resolve_config_dir(None, settings_service=settings_service)\\n\\n        assert result == Path.cwd()\\n\\n    def test_explicit_takes_precedence_over_settings(self):\\n        settings_service = MagicMock()\\n        settings_service.settings.config_dir = \\\"/from/settings\\\"\\n\\n        result = resolve_config_dir(Path(\\\"/explicit\\\"), settings_service=settings_service)\\n\\n        assert result == Path(\\\"/explicit\\\")\\n\\n\\nclass TestLoadTomlConfig:\\n    \\\"\\\"\\\"Tests for load_toml_config error handling.\\\"\\\"\\\"\\n\\n    def test_permission_error_returns_none(self, tmp_path):\\n        from lfx.services.config_discovery import load_toml_config\\n\\n        config_file = tmp_path / \\\"lfx.toml\\\"\\n        config_file.write_text(\\\"[section]\\\\nkey = 'value'\\\\n\\\")\\n        config_file.chmod(0o000)\\n\\n        try:\\n            result = load_toml_config(config_file)\\n            assert result is None\\n        finally:\\n            config_file.chmod(0o644)\\n\\n    def test_valid_toml_is_loaded(self, tmp_path):\\n        from lfx.services.config_discovery import load_toml_config\\n\\n        config_file = tmp_path / \\\"lfx.toml\\\"\\n        config_file.write_text(\\\"[section]\\\\nkey = 'value'\\\\n\\\")\\n\\n        result = load_toml_config(config_file)\\n\\n        assert result == {\\\"section\\\": {\\\"key\\\": \\\"value\\\"}}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/test_decorator_registration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8623cd6cf76058c4395dcdd6e50d6561a17962f16e14cd06d5d31858ae4fad38\",\"content\":\"\\\"\\\"\\\"Tests for decorator-based service registration.\\\"\\\"\\\"\\n\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\nfrom lfx.services.base import Service\\nfrom lfx.services.manager import ServiceManager\\nfrom lfx.services.schema import ServiceType\\nfrom lfx.services.storage.local import LocalStorageService\\nfrom lfx.services.telemetry.service import TelemetryService\\nfrom lfx.services.tracing.service import TracingService\\n\\n\\nclass MockSessionService(Service):\\n    \\\"\\\"\\\"Mock session service for testing.\\\"\\\"\\\"\\n\\n    name = \\\"session_service\\\"\\n\\n    def __init__(self):\\n        \\\"\\\"\\\"Initialize mock session service.\\\"\\\"\\\"\\n        self.set_ready()\\n\\n    async def teardown(self) -> None:\\n        \\\"\\\"\\\"Teardown the mock session service.\\\"\\\"\\\"\\n\\n\\n@pytest.fixture\\ndef clean_manager():\\n    \\\"\\\"\\\"Create a fresh ServiceManager for testing decorators.\\\"\\\"\\\"\\n    manager = ServiceManager()\\n\\n    # Register mock SESSION_SERVICE so services with dependencies can be created\\n    manager.register_service_class(ServiceType.SESSION_SERVICE, MockSessionService, override=True)\\n\\n    yield manager\\n    # Cleanup\\n    import asyncio\\n\\n    asyncio.run(manager.teardown())\\n\\n\\nclass TestDecoratorRegistration:\\n    \\\"\\\"\\\"Tests for @register_service decorator with real services.\\\"\\\"\\\"\\n\\n    def test_decorator_registers_real_storage_service(self, clean_manager):\\n        \\\"\\\"\\\"Test that decorator registers real LocalStorageService.\\\"\\\"\\\"\\n        # Use direct registration to simulate decorator (since decorator uses singleton)\\n        clean_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService, override=True)\\n\\n        assert ServiceType.STORAGE_SERVICE in clean_manager.service_classes\\n        assert clean_manager.service_classes[ServiceType.STORAGE_SERVICE] == LocalStorageService\\n\\n        # Verify we can actually create and use the service\\n        storage = clean_manager.get(ServiceType.STORAGE_SERVICE)\\n        assert isinstance(storage, LocalStorageService)\\n        assert storage.ready is True\\n\\n    @pytest.mark.asyncio\\n    async def test_decorator_registers_real_telemetry_service(self, clean_manager):\\n        \\\"\\\"\\\"Test that decorator registers real TelemetryService.\\\"\\\"\\\"\\n        clean_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TelemetryService, override=True)\\n\\n        assert ServiceType.TELEMETRY_SERVICE in clean_manager.service_classes\\n        assert clean_manager.service_classes[ServiceType.TELEMETRY_SERVICE] == TelemetryService\\n\\n        # Verify service works\\n        telemetry = clean_manager.get(ServiceType.TELEMETRY_SERVICE)\\n        assert isinstance(telemetry, TelemetryService)\\n        await telemetry.log_package_version()  # Should not raise\\n\\n    def test_decorator_with_override_false_preserves_first(self, clean_manager):\\n        \\\"\\\"\\\"Test decorator with override=False preserves first registration.\\\"\\\"\\\"\\n        # Register first service\\n        clean_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TelemetryService, override=True)\\n\\n        # Try to register second service with override=False\\n        clean_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TracingService, override=False)\\n\\n        # Should still be first service\\n        assert clean_manager.service_classes[ServiceType.TELEMETRY_SERVICE] == TelemetryService\\n\\n    def test_decorator_with_override_true_replaces(self, clean_manager):\\n        \\\"\\\"\\\"Test decorator with override=True replaces existing.\\\"\\\"\\\"\\n        # Register first service\\n        clean_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TelemetryService, override=True)\\n\\n        # Replace with second service\\n        clean_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TracingService, override=True)\\n\\n        # Should be second service\\n        assert clean_manager.service_classes[ServiceType.TELEMETRY_SERVICE] == TracingService\\n\\n    def test_cannot_decorate_settings_service(self, clean_manager):\\n        \\\"\\\"\\\"Test that decorating settings service raises ValueError.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Settings service cannot be registered\\\"):\\n            clean_manager.register_service_class(ServiceType.SETTINGS_SERVICE, LocalStorageService)\\n\\n    def test_decorator_with_custom_service_class(self, clean_manager):\\n        \\\"\\\"\\\"Test decorator with a custom service implementation.\\\"\\\"\\\"\\n\\n        class CustomTracingService(Service):\\n            @property\\n            def name(self) -> str:\\n                return \\\"tracing_service\\\"\\n\\n            def __init__(self):\\n                super().__init__()\\n                self.messages = []\\n                self.set_ready()\\n\\n            def add_log(self, trace_name: str, log: dict):\\n                self.messages.append(f\\\"{trace_name}: {log}\\\")\\n\\n            async def teardown(self) -> None:\\n                self.messages.clear()\\n\\n        clean_manager.register_service_class(ServiceType.TRACING_SERVICE, CustomTracingService, override=True)\\n\\n        # Verify registration\\n        assert clean_manager.service_classes[ServiceType.TRACING_SERVICE] == CustomTracingService\\n\\n        # Verify we can use it\\n        tracing = clean_manager.get(ServiceType.TRACING_SERVICE)\\n        assert isinstance(tracing, CustomTracingService)\\n        tracing.add_log(\\\"test_trace\\\", {\\\"message\\\": \\\"test message\\\"})\\n        assert len(tracing.messages) == 1\\n\\n    def test_decorator_preserves_class_functionality(self, clean_manager, tmp_path):\\n        \\\"\\\"\\\"Test that decorator preserves all class functionality.\\\"\\\"\\\"\\n        clean_manager.register_service_class(ServiceType.VARIABLE_SERVICE, LocalStorageService, override=True)\\n\\n        # Class should still be usable directly (not just through manager)\\n        mock_session = MagicMock()\\n        mock_settings = MagicMock()\\n        mock_settings.settings.config_dir = tmp_path\\n        direct_instance = LocalStorageService(mock_session, mock_settings)\\n        assert direct_instance.ready is True\\n        assert direct_instance.name == \\\"storage_service\\\"\\n\\n    def test_multiple_decorators_on_different_services(self, clean_manager):\\n        \\\"\\\"\\\"Test registering multiple different services.\\\"\\\"\\\"\\n        clean_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService, override=True)\\n        clean_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TelemetryService, override=True)\\n        clean_manager.register_service_class(ServiceType.TRACING_SERVICE, TracingService, override=True)\\n\\n        # All should be registered (plus MockSessionService from fixture)\\n        assert len(clean_manager.service_classes) == 4\\n        assert ServiceType.STORAGE_SERVICE in clean_manager.service_classes\\n        assert ServiceType.TELEMETRY_SERVICE in clean_manager.service_classes\\n        assert ServiceType.TRACING_SERVICE in clean_manager.service_classes\\n\\n        # All should be creatable\\n        storage = clean_manager.get(ServiceType.STORAGE_SERVICE)\\n        telemetry = clean_manager.get(ServiceType.TELEMETRY_SERVICE)\\n        tracing = clean_manager.get(ServiceType.TRACING_SERVICE)\\n\\n        assert isinstance(storage, LocalStorageService)\\n        assert isinstance(telemetry, TelemetryService)\\n        assert isinstance(tracing, TracingService)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/test_integration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e2fadb483e36134a7a554ad0b5b89b592cc5f18dafcb584092bbe14d8ccdea7c\",\"content\":\"\\\"\\\"\\\"Integration tests for pluggable service system.\\\"\\\"\\\"\\n\\nimport os\\n\\nimport pytest\\nfrom lfx.services.base import Service\\nfrom lfx.services.manager import ServiceManager\\nfrom lfx.services.schema import ServiceType\\n\\nfrom .conftest import MockSessionService\\n\\n\\nclass TestStandaloneLFX:\\n    \\\"\\\"\\\"Test LFX running standalone without langflow.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def clean_manager(self):\\n        \\\"\\\"\\\"Create a clean ServiceManager instance.\\\"\\\"\\\"\\n        manager = ServiceManager()\\n        # Register mock session service as dependency for LocalStorageService\\n        manager.register_service_class(ServiceType.SESSION_SERVICE, MockSessionService, override=True)\\n        yield manager\\n        # Cleanup\\n        import asyncio\\n\\n        asyncio.run(manager.teardown())\\n\\n    def test_minimal_storage_service_loads(self, clean_manager):\\n        \\\"\\\"\\\"Test that minimal storage service loads by default.\\\"\\\"\\\"\\n        from lfx.services.storage.local import LocalStorageService\\n\\n        # Register the minimal storage service\\n        clean_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService)\\n\\n        storage = clean_manager.get(ServiceType.STORAGE_SERVICE)\\n\\n        assert isinstance(storage, LocalStorageService)\\n        assert storage.ready is True\\n\\n    def test_minimal_telemetry_service_loads(self, clean_manager):\\n        \\\"\\\"\\\"Test that minimal telemetry service loads by default.\\\"\\\"\\\"\\n        # Should fall back to factory since no plugin registered\\n\\n        # Telemetry doesn't have a default factory, so should fail\\n        # unless we register it first\\n        from lfx.services.telemetry.service import TelemetryService\\n\\n        clean_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TelemetryService)\\n\\n        telemetry = clean_manager.get(ServiceType.TELEMETRY_SERVICE)\\n        assert isinstance(telemetry, TelemetryService)\\n        assert telemetry.ready is True\\n\\n    def test_minimal_variable_service_loads(self, clean_manager):\\n        \\\"\\\"\\\"Test that minimal variable service loads by default.\\\"\\\"\\\"\\n        from lfx.services.variable.service import VariableService\\n\\n        clean_manager.register_service_class(ServiceType.VARIABLE_SERVICE, VariableService)\\n\\n        variables = clean_manager.get(ServiceType.VARIABLE_SERVICE)\\n        assert isinstance(variables, VariableService)\\n        assert variables.ready is True\\n\\n    def test_settings_service_always_available(self, clean_manager):\\n        \\\"\\\"\\\"Test that settings service is always available.\\\"\\\"\\\"\\n        settings = clean_manager.get(ServiceType.SETTINGS_SERVICE)\\n\\n        from lfx.services.settings.service import SettingsService\\n\\n        assert isinstance(settings, SettingsService)\\n        assert settings.ready is True\\n\\n\\nclass TestLFXWithLangflowConfig:\\n    \\\"\\\"\\\"Test LFX with langflow configuration.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def langflow_config_dir(self, tmp_path):\\n        \\\"\\\"\\\"Create a temporary langflow-style config directory.\\\"\\\"\\\"\\n        config_dir = tmp_path / \\\"config\\\"\\n        config_dir.mkdir()\\n\\n        # Create lfx.toml with langflow services\\n        config_file = config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\ncache_service = \\\"lfx.services.cache.service:ThreadingInMemoryCache\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        return config_dir\\n\\n    @pytest.fixture\\n    def clean_manager(self):\\n        \\\"\\\"\\\"Create a clean ServiceManager instance.\\\"\\\"\\\"\\n        manager = ServiceManager()\\n        # Register mock session service as dependency for LocalStorageService\\n        manager.register_service_class(ServiceType.SESSION_SERVICE, MockSessionService, override=True)\\n        yield manager\\n        # Cleanup\\n        import asyncio\\n\\n        asyncio.run(manager.teardown())\\n\\n    def test_config_overrides_defaults(self, clean_manager, langflow_config_dir):\\n        \\\"\\\"\\\"Test that config file overrides default services.\\\"\\\"\\\"\\n        # Discover plugins from config\\n        clean_manager.discover_plugins(langflow_config_dir)\\n\\n        # Storage should be loaded from config\\n        assert ServiceType.STORAGE_SERVICE in clean_manager.service_classes\\n\\n        from lfx.services.storage.local import LocalStorageService\\n\\n        assert clean_manager.service_classes[ServiceType.STORAGE_SERVICE] == LocalStorageService\\n\\n    def test_multiple_services_from_config(self, clean_manager, langflow_config_dir):\\n        \\\"\\\"\\\"Test loading multiple services from config.\\\"\\\"\\\"\\n        clean_manager.discover_plugins(langflow_config_dir)\\n\\n        # Both services should be registered\\n        assert ServiceType.STORAGE_SERVICE in clean_manager.service_classes\\n        assert ServiceType.CACHE_SERVICE in clean_manager.service_classes\\n\\n\\nclass TestServiceOverrideScenarios:\\n    \\\"\\\"\\\"Test various service override scenarios.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def clean_manager(self):\\n        \\\"\\\"\\\"Create a clean ServiceManager instance.\\\"\\\"\\\"\\n        manager = ServiceManager()\\n        # Register mock session service as dependency for LocalStorageService\\n        manager.register_service_class(ServiceType.SESSION_SERVICE, MockSessionService, override=True)\\n        yield manager\\n        # Cleanup\\n        import asyncio\\n\\n        asyncio.run(manager.teardown())\\n\\n    def test_decorator_overrides_config(self, clean_manager, tmp_path):\\n        \\\"\\\"\\\"Test that decorator registration overrides config.\\\"\\\"\\\"\\n        # First create config\\n        config_dir = tmp_path / \\\"config\\\"\\n        config_dir.mkdir()\\n        config_file = config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        # Load from config\\n        clean_manager.discover_plugins(config_dir)\\n\\n        # Now override with direct registration (simulating decorator)\\n        class CustomStorageService(Service):\\n            @property\\n            def name(self) -> str:\\n                return \\\"storage_service\\\"\\n\\n            async def teardown(self) -> None:\\n                pass\\n\\n        clean_manager.register_service_class(ServiceType.STORAGE_SERVICE, CustomStorageService, override=True)\\n\\n        # Should use the override version\\n        assert clean_manager.service_classes[ServiceType.STORAGE_SERVICE] == CustomStorageService\\n\\n    def test_override_false_preserves_existing(self, clean_manager):\\n        \\\"\\\"\\\"Test that override=False preserves existing registration.\\\"\\\"\\\"\\n\\n        class FirstService(Service):\\n            name = \\\"storage_service\\\"\\n\\n            async def teardown(self) -> None:\\n                pass\\n\\n        class SecondService(Service):\\n            name = \\\"storage_service\\\"\\n\\n            async def teardown(self) -> None:\\n                pass\\n\\n        # Register first\\n        clean_manager.register_service_class(ServiceType.STORAGE_SERVICE, FirstService, override=True)\\n\\n        # Try to register second with override=False\\n        clean_manager.register_service_class(ServiceType.STORAGE_SERVICE, SecondService, override=False)\\n\\n        # Should still be first\\n        assert clean_manager.service_classes[ServiceType.STORAGE_SERVICE] == FirstService\\n\\n\\nclass TestErrorConditions:\\n    \\\"\\\"\\\"Test error handling in various conditions.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def clean_manager(self):\\n        \\\"\\\"\\\"Create a clean ServiceManager instance.\\\"\\\"\\\"\\n        manager = ServiceManager()\\n        # Register mock session service as dependency for LocalStorageService\\n        manager.register_service_class(ServiceType.SESSION_SERVICE, MockSessionService, override=True)\\n        yield manager\\n        # Cleanup\\n        import asyncio\\n\\n        asyncio.run(manager.teardown())\\n\\n    def test_missing_import_in_config(self, clean_manager, tmp_path):\\n        \\\"\\\"\\\"Test handling of missing import in config.\\\"\\\"\\\"\\n        config_dir = tmp_path / \\\"config\\\"\\n        config_dir.mkdir()\\n        config_file = config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\nstorage_service = \\\"nonexistent.module:NonexistentClass\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        # Should not raise, just log warning\\n        clean_manager.discover_plugins(config_dir)\\n\\n        # Service should not be registered\\n        assert ServiceType.STORAGE_SERVICE not in clean_manager.service_classes\\n\\n    def test_invalid_service_type_in_config(self, clean_manager, tmp_path):\\n        \\\"\\\"\\\"Test handling of invalid service type in config.\\\"\\\"\\\"\\n        config_dir = tmp_path / \\\"config\\\"\\n        config_dir.mkdir()\\n        config_file = config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\ninvalid_service_type = \\\"some.module:SomeClass\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        # Should not raise, just log warning\\n        clean_manager.discover_plugins(config_dir)\\n\\n        # No services should be registered from config (only SESSION_SERVICE from fixture)\\n        assert len(clean_manager.service_classes) == 1\\n        assert ServiceType.SESSION_SERVICE in clean_manager.service_classes\\n\\n    def test_malformed_toml_in_config(self, clean_manager, tmp_path):\\n        \\\"\\\"\\\"Test handling of malformed TOML.\\\"\\\"\\\"\\n        config_dir = tmp_path / \\\"config\\\"\\n        config_dir.mkdir()\\n        config_file = config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        # Should not raise, just log warning\\n        clean_manager.discover_plugins(config_dir)\\n\\n        # No services should be registered from config (only SESSION_SERVICE from fixture)\\n        assert len(clean_manager.service_classes) == 1\\n        assert ServiceType.SESSION_SERVICE in clean_manager.service_classes\\n\\n    def test_service_without_name_attribute(self, clean_manager):\\n        \\\"\\\"\\\"Test registering a service without name attribute.\\\"\\\"\\\"\\n\\n        class InvalidService(Service):\\n            async def teardown(self) -> None:\\n                pass\\n\\n        # Should not raise during registration\\n        clean_manager.register_service_class(ServiceType.STORAGE_SERVICE, InvalidService)\\n\\n        # But should fail during creation (can't instantiate abstract class)\\n        with pytest.raises(TypeError, match=\\\"Can't instantiate abstract class\\\"):\\n            clean_manager.get(ServiceType.STORAGE_SERVICE)\\n\\n    def test_service_initialization_failure(self, clean_manager):\\n        \\\"\\\"\\\"Test handling of service initialization failure.\\\"\\\"\\\"\\n\\n        class FailingService(Service):\\n            name = \\\"storage_service\\\"\\n\\n            def __init__(self):\\n                msg = \\\"Initialization failed\\\"\\n                raise RuntimeError(msg)\\n\\n            async def teardown(self) -> None:\\n                pass\\n\\n        clean_manager.register_service_class(ServiceType.STORAGE_SERVICE, FailingService)\\n\\n        # Should raise the initialization error\\n        with pytest.raises(RuntimeError, match=\\\"Initialization failed\\\"):\\n            clean_manager.get(ServiceType.STORAGE_SERVICE)\\n\\n\\nclass TestDependencyResolution:\\n    \\\"\\\"\\\"Test dependency resolution and injection.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def clean_manager(self):\\n        \\\"\\\"\\\"Create a clean ServiceManager instance.\\\"\\\"\\\"\\n        manager = ServiceManager()\\n        # Register mock session service as dependency for LocalStorageService\\n        manager.register_service_class(ServiceType.SESSION_SERVICE, MockSessionService, override=True)\\n        yield manager\\n        # Cleanup\\n        import asyncio\\n\\n        asyncio.run(manager.teardown())\\n\\n    def test_service_with_settings_dependency(self, clean_manager):\\n        \\\"\\\"\\\"Test service that depends on settings service.\\\"\\\"\\\"\\n\\n        class ServiceWithSettings(Service):\\n            name = \\\"test_service\\\"\\n\\n            def __init__(self, settings_service):\\n                super().__init__()\\n                self.settings = settings_service\\n                self.set_ready()\\n\\n            async def teardown(self) -> None:\\n                pass\\n\\n        clean_manager.register_service_class(ServiceType.STORAGE_SERVICE, ServiceWithSettings)\\n\\n        service = clean_manager.get(ServiceType.STORAGE_SERVICE)\\n\\n        # Should have settings injected\\n        from lfx.services.settings.service import SettingsService\\n\\n        assert isinstance(service.settings, SettingsService)\\n\\n    def test_service_with_multiple_dependencies(self, clean_manager):\\n        \\\"\\\"\\\"Test service with multiple dependencies.\\\"\\\"\\\"\\n\\n        class SimpleService(Service):\\n            name = \\\"simple_service\\\"\\n\\n            def __init__(self):\\n                super().__init__()\\n                self.set_ready()\\n\\n            async def teardown(self) -> None:\\n                pass\\n\\n        class ComplexService(Service):\\n            name = \\\"complex_service\\\"\\n\\n            def __init__(self, settings_service, storage_service):\\n                super().__init__()\\n                self.settings = settings_service\\n                self.storage = storage_service\\n                self.set_ready()\\n\\n            async def teardown(self) -> None:\\n                pass\\n\\n        # Register both\\n        clean_manager.register_service_class(ServiceType.STORAGE_SERVICE, SimpleService)\\n        clean_manager.register_service_class(ServiceType.CACHE_SERVICE, ComplexService)\\n\\n        # Create complex service\\n        complex_service = clean_manager.get(ServiceType.CACHE_SERVICE)\\n\\n        # Should have both dependencies\\n        from lfx.services.settings.service import SettingsService\\n\\n        assert isinstance(complex_service.settings, SettingsService)\\n        assert isinstance(complex_service.storage, SimpleService)\\n\\n    def test_service_with_unresolvable_dependency(self, clean_manager):\\n        \\\"\\\"\\\"Test service with dependency that can't be resolved.\\\"\\\"\\\"\\n\\n        class ServiceWithUnknownDep(Service):\\n            name = \\\"test_service\\\"\\n\\n            def __init__(self, unknown_param: str):\\n                super().__init__()\\n                self.unknown_param = unknown_param\\n                self.set_ready()\\n\\n            async def teardown(self) -> None:\\n                pass\\n\\n        clean_manager.register_service_class(ServiceType.STORAGE_SERVICE, ServiceWithUnknownDep)\\n\\n        # Should raise due to missing parameter\\n        with pytest.raises(TypeError):\\n            clean_manager.get(ServiceType.STORAGE_SERVICE)\\n\\n\\nclass TestConfigFileDiscovery:\\n    \\\"\\\"\\\"Test configuration file discovery.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def clean_manager(self):\\n        \\\"\\\"\\\"Create a clean ServiceManager instance.\\\"\\\"\\\"\\n        manager = ServiceManager()\\n        # Register mock session service as dependency for LocalStorageService\\n        manager.register_service_class(ServiceType.SESSION_SERVICE, MockSessionService, override=True)\\n        yield manager\\n        # Cleanup\\n        import asyncio\\n\\n        asyncio.run(manager.teardown())\\n\\n    def test_pyproject_toml_discovery(self, clean_manager, tmp_path):\\n        \\\"\\\"\\\"Test discovering services from pyproject.toml.\\\"\\\"\\\"\\n        config_dir = tmp_path / \\\"config\\\"\\n        config_dir.mkdir()\\n        config_file = config_dir / \\\"pyproject.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[tool.lfx.services]\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        clean_manager.discover_plugins(config_dir)\\n\\n        assert ServiceType.STORAGE_SERVICE in clean_manager.service_classes\\n\\n    def test_lfx_toml_takes_precedence(self, clean_manager, tmp_path):\\n        \\\"\\\"\\\"Test that lfx.toml takes precedence over pyproject.toml.\\\"\\\"\\\"\\n        config_dir = tmp_path / \\\"config\\\"\\n        config_dir.mkdir()\\n\\n        # Create both files with different services\\n        (config_dir / \\\"lfx.toml\\\").write_text(\\n            \\\"\\\"\\\"\\n[services]\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        (config_dir / \\\"pyproject.toml\\\").write_text(\\n            \\\"\\\"\\\"\\n[tool.lfx.services]\\ncache_service = \\\"lfx.services.cache.service:ThreadingInMemoryCache\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        clean_manager.discover_plugins(config_dir)\\n\\n        # Should only have storage from lfx.toml\\n        assert ServiceType.STORAGE_SERVICE in clean_manager.service_classes\\n        assert ServiceType.CACHE_SERVICE not in clean_manager.service_classes\\n\\n    def test_no_config_file_no_error(self, clean_manager, tmp_path):\\n        \\\"\\\"\\\"Test that missing config files don't cause errors.\\\"\\\"\\\"\\n        config_dir = tmp_path / \\\"config\\\"\\n        config_dir.mkdir()\\n\\n        # Should not raise\\n        clean_manager.discover_plugins(config_dir)\\n\\n        # No services should be registered from config (only SESSION_SERVICE from fixture)\\n        assert len(clean_manager.service_classes) == 1\\n        assert ServiceType.SESSION_SERVICE in clean_manager.service_classes\\n\\n\\nclass TestEnvironmentVariableIntegration:\\n    \\\"\\\"\\\"Test environment variable integration with services.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def clean_manager(self):\\n        \\\"\\\"\\\"Create a clean ServiceManager instance.\\\"\\\"\\\"\\n        manager = ServiceManager()\\n        # Register mock session service as dependency for LocalStorageService\\n        manager.register_service_class(ServiceType.SESSION_SERVICE, MockSessionService, override=True)\\n        yield manager\\n        # Cleanup\\n        import asyncio\\n\\n        asyncio.run(manager.teardown())\\n\\n    async def test_variable_service_uses_env(self, clean_manager):\\n        \\\"\\\"\\\"Test that variable service reads from environment.\\\"\\\"\\\"\\n        from lfx.services.variable.service import VariableService\\n\\n        clean_manager.register_service_class(ServiceType.VARIABLE_SERVICE, VariableService)\\n\\n        os.environ[\\\"TEST_API_KEY\\\"] = \\\"test_value_123\\\"  # pragma: allowlist secret\\n        try:\\n            variables = clean_manager.get(ServiceType.VARIABLE_SERVICE)\\n            value = await variables.get_variable(\\\"TEST_API_KEY\\\")\\n            assert value == \\\"test_value_123\\\"\\n        finally:\\n            del os.environ[\\\"TEST_API_KEY\\\"]\\n\\n    async def test_variable_service_in_memory_overrides_env(self, clean_manager):\\n        \\\"\\\"\\\"Test that in-memory variables override environment.\\\"\\\"\\\"\\n        from lfx.services.variable.service import VariableService\\n\\n        clean_manager.register_service_class(ServiceType.VARIABLE_SERVICE, VariableService)\\n\\n        os.environ[\\\"TEST_VAR\\\"] = \\\"env_value\\\"\\n        try:\\n            variables = clean_manager.get(ServiceType.VARIABLE_SERVICE)\\n            variables.set_variable(\\\"TEST_VAR\\\", \\\"memory_value\\\")\\n            value = await variables.get_variable(\\\"TEST_VAR\\\")\\n            assert value == \\\"memory_value\\\"\\n        finally:\\n            del os.environ[\\\"TEST_VAR\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/test_minimal_services.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1179b8812e684d07fb58b181043ec0a27bdde8522a3fccd67f70d2cd2449cf30\",\"content\":\"\\\"\\\"\\\"Tests for minimal service implementations in LFX.\\\"\\\"\\\"\\n\\nimport os\\n\\nimport pytest\\nfrom lfx.services.storage.local import LocalStorageService\\nfrom lfx.services.telemetry.service import TelemetryService\\nfrom lfx.services.tracing.service import TracingService\\nfrom lfx.services.variable.service import VariableService\\n\\n\\nclass TestLocalStorageService:\\n    \\\"\\\"\\\"Tests for LocalStorageService.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def storage(self, mock_session_service, mock_settings_service):\\n        \\\"\\\"\\\"Create a storage service with temp directory.\\\"\\\"\\\"\\n        return LocalStorageService(mock_session_service, mock_settings_service)\\n\\n    @pytest.mark.asyncio\\n    async def test_save_and_get_file(self, storage):\\n        \\\"\\\"\\\"Test saving and retrieving a file.\\\"\\\"\\\"\\n        data = b\\\"test content\\\"\\n        await storage.save_file(\\\"flow_123\\\", \\\"test.txt\\\", data)\\n\\n        retrieved = await storage.get_file(\\\"flow_123\\\", \\\"test.txt\\\")\\n        assert retrieved == data\\n\\n    @pytest.mark.asyncio\\n    async def test_list_files(self, storage):\\n        \\\"\\\"\\\"Test listing files in a flow.\\\"\\\"\\\"\\n        await storage.save_file(\\\"flow_123\\\", \\\"file1.txt\\\", b\\\"content1\\\")\\n        await storage.save_file(\\\"flow_123\\\", \\\"file2.txt\\\", b\\\"content2\\\")\\n\\n        files = await storage.list_files(\\\"flow_123\\\")\\n        assert len(files) == 2\\n        assert \\\"file1.txt\\\" in files\\n        assert \\\"file2.txt\\\" in files\\n\\n    @pytest.mark.asyncio\\n    async def test_delete_file(self, storage):\\n        \\\"\\\"\\\"Test deleting a file.\\\"\\\"\\\"\\n        await storage.save_file(\\\"flow_123\\\", \\\"test.txt\\\", b\\\"content\\\")\\n        await storage.delete_file(\\\"flow_123\\\", \\\"test.txt\\\")\\n\\n        with pytest.raises(FileNotFoundError):\\n            await storage.get_file(\\\"flow_123\\\", \\\"test.txt\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_get_file_size(self, storage):\\n        \\\"\\\"\\\"Test getting file size.\\\"\\\"\\\"\\n        data = b\\\"test content\\\"\\n        await storage.save_file(\\\"flow_123\\\", \\\"test.txt\\\", data)\\n\\n        size = await storage.get_file_size(\\\"flow_123\\\", \\\"test.txt\\\")\\n        assert size == len(data)\\n\\n    @pytest.mark.asyncio\\n    async def test_get_nonexistent_file(self, storage):\\n        \\\"\\\"\\\"Test getting a file that doesn't exist.\\\"\\\"\\\"\\n        with pytest.raises(FileNotFoundError):\\n            await storage.get_file(\\\"flow_123\\\", \\\"nonexistent.txt\\\")\\n\\n    def test_build_full_path(self, storage, mock_settings_service):\\n        \\\"\\\"\\\"Test building full file path.\\\"\\\"\\\"\\n        path = storage.build_full_path(\\\"flow_123\\\", \\\"test.txt\\\")\\n        config_dir = mock_settings_service.settings.config_dir\\n        expected = f\\\"{config_dir}/flow_123/test.txt\\\"\\n        assert path == expected\\n\\n    @pytest.mark.asyncio\\n    async def test_list_files_empty_flow(self, storage):\\n        \\\"\\\"\\\"Test listing files in nonexistent flow.\\\"\\\"\\\"\\n        files = await storage.list_files(\\\"nonexistent_flow\\\")\\n        assert files == []\\n\\n    def test_service_ready(self, storage):\\n        \\\"\\\"\\\"Test that service is marked as ready.\\\"\\\"\\\"\\n        assert storage.ready is True\\n        assert storage.name == \\\"storage_service\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_teardown(self, storage):\\n        \\\"\\\"\\\"Test service teardown.\\\"\\\"\\\"\\n        await storage.teardown()\\n        # Should not raise\\n\\n\\nclass TestTelemetryService:\\n    \\\"\\\"\\\"Tests for TelemetryService.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def telemetry(self):\\n        \\\"\\\"\\\"Create a telemetry service with do_not_track so it doesn't hit the network.\\\"\\\"\\\"\\n        return TelemetryService(do_not_track=True)\\n\\n    def test_service_ready(self, telemetry):\\n        \\\"\\\"\\\"Test that service is ready.\\\"\\\"\\\"\\n        assert telemetry.ready is True\\n        assert telemetry.name == \\\"telemetry_service\\\"\\n\\n    def test_do_not_track_from_env(self):\\n        \\\"\\\"\\\"Test DO_NOT_TRACK env var is respected.\\\"\\\"\\\"\\n        os.environ[\\\"DO_NOT_TRACK\\\"] = \\\"1\\\"\\n        try:\\n            svc = TelemetryService()\\n            assert svc.do_not_track is True\\n        finally:\\n            del os.environ[\\\"DO_NOT_TRACK\\\"]\\n\\n    def test_start_skipped_when_do_not_track(self, telemetry):\\n        \\\"\\\"\\\"Start is a no-op when do_not_track is set.\\\"\\\"\\\"\\n        telemetry.start()\\n        assert telemetry._running is False\\n        assert telemetry._worker_task is None\\n        assert telemetry._client is None\\n\\n    @pytest.mark.asyncio\\n    async def test_start_and_stop_lifecycle(self):\\n        \\\"\\\"\\\"Test that start creates worker/client and stop cleans them up.\\\"\\\"\\\"\\n        svc = TelemetryService(base_url=\\\"http://localhost:0\\\")\\n        svc.start()\\n        assert svc._running is True\\n        assert svc._worker_task is not None\\n        assert svc._client is not None\\n\\n        await svc.stop()\\n        assert svc._running is False\\n        assert svc._client is None\\n\\n    @pytest.mark.asyncio\\n    async def test_enqueue_skipped_when_do_not_track(self, telemetry):\\n        \\\"\\\"\\\"Enqueue is a no-op when do_not_track is set.\\\"\\\"\\\"\\n        from lfx.services.telemetry.schema import MCPToolPayload\\n\\n        await telemetry.log_mcp_tool(MCPToolPayload(tool=\\\"test\\\", success=True, ms=5))\\n        assert telemetry._queue.empty()\\n\\n    @pytest.mark.asyncio\\n    async def test_flush_when_do_not_track(self, telemetry):\\n        \\\"\\\"\\\"Flush should not raise when do_not_track is set.\\\"\\\"\\\"\\n        await telemetry.flush()\\n\\n    @pytest.mark.asyncio\\n    async def test_log_exception(self, telemetry):\\n        \\\"\\\"\\\"Test logging an exception.\\\"\\\"\\\"\\n        exc = ValueError(\\\"test error\\\")\\n        await telemetry.log_exception(exc, \\\"test_context\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_log_package_version(self, telemetry):\\n        \\\"\\\"\\\"Test logging package version.\\\"\\\"\\\"\\n        await telemetry.log_package_version()\\n\\n    @pytest.mark.asyncio\\n    async def test_teardown(self, telemetry):\\n        \\\"\\\"\\\"Test service teardown.\\\"\\\"\\\"\\n        await telemetry.teardown()\\n\\n    @pytest.mark.asyncio\\n    async def test_teardown_after_start(self):\\n        \\\"\\\"\\\"Test that teardown properly stops a started service.\\\"\\\"\\\"\\n        svc = TelemetryService(base_url=\\\"http://localhost:0\\\")\\n        svc.start()\\n        assert svc._running is True\\n        await svc.teardown()\\n        assert svc._running is False\\n        assert svc._client is None\\n\\n\\nclass TestTracingService:\\n    \\\"\\\"\\\"Tests for minimal TracingService.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def tracing(self):\\n        \\\"\\\"\\\"Create a tracing service.\\\"\\\"\\\"\\n        return TracingService()\\n\\n    def test_service_ready(self, tracing):\\n        \\\"\\\"\\\"Test that service is ready.\\\"\\\"\\\"\\n        assert tracing.ready is True\\n        assert tracing.name == \\\"tracing_service\\\"\\n\\n    def test_add_log(self, tracing):\\n        \\\"\\\"\\\"Test adding a log entry (outputs to debug).\\\"\\\"\\\"\\n        # Should not raise\\n        tracing.add_log(\\\"test_trace\\\", {\\\"message\\\": \\\"test log\\\"})\\n\\n    @pytest.mark.asyncio\\n    async def test_teardown(self, tracing):\\n        \\\"\\\"\\\"Test service teardown.\\\"\\\"\\\"\\n        await tracing.teardown()\\n        # Should not raise\\n\\n\\nclass TestVariableService:\\n    \\\"\\\"\\\"Tests for minimal VariableService.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def variables(self):\\n        \\\"\\\"\\\"Create a variable service.\\\"\\\"\\\"\\n        return VariableService()\\n\\n    def test_service_ready(self, variables):\\n        \\\"\\\"\\\"Test that service is ready.\\\"\\\"\\\"\\n        assert variables.ready is True\\n        assert variables.name == \\\"variable_service\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_set_and_get_variable(self, variables):\\n        \\\"\\\"\\\"Test setting and getting a variable.\\\"\\\"\\\"\\n        variables.set_variable(\\\"test_key\\\", \\\"test_value\\\")\\n        value = await variables.get_variable(\\\"test_key\\\")\\n        assert value == \\\"test_value\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_get_from_environment(self, variables):\\n        \\\"\\\"\\\"Test getting variable from environment.\\\"\\\"\\\"\\n        os.environ[\\\"TEST_ENV_VAR\\\"] = \\\"env_value\\\"\\n        try:\\n            value = await variables.get_variable(\\\"TEST_ENV_VAR\\\")\\n            assert value == \\\"env_value\\\"\\n        finally:\\n            del os.environ[\\\"TEST_ENV_VAR\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_get_nonexistent_variable(self, variables):\\n        \\\"\\\"\\\"Test getting a variable that doesn't exist.\\\"\\\"\\\"\\n        value = await variables.get_variable(\\\"nonexistent_key\\\")\\n        assert value is None\\n\\n    @pytest.mark.asyncio\\n    async def test_delete_variable(self, variables):\\n        \\\"\\\"\\\"Test deleting a variable.\\\"\\\"\\\"\\n        variables.set_variable(\\\"test_key\\\", \\\"test_value\\\")\\n        variables.delete_variable(\\\"test_key\\\")\\n        value = await variables.get_variable(\\\"test_key\\\")\\n        assert value is None\\n\\n    def test_list_variables(self, variables):\\n        \\\"\\\"\\\"Test listing variables.\\\"\\\"\\\"\\n        variables.set_variable(\\\"key1\\\", \\\"value1\\\")\\n        variables.set_variable(\\\"key2\\\", \\\"value2\\\")\\n\\n        vars_list = variables.list_variables()\\n        assert \\\"key1\\\" in vars_list\\n        assert \\\"key2\\\" in vars_list\\n\\n    @pytest.mark.asyncio\\n    async def test_in_memory_overrides_env(self, variables):\\n        \\\"\\\"\\\"Test that in-memory variables override environment.\\\"\\\"\\\"\\n        os.environ[\\\"TEST_VAR\\\"] = \\\"env_value\\\"\\n        try:\\n            variables.set_variable(\\\"TEST_VAR\\\", \\\"memory_value\\\")\\n            value = await variables.get_variable(\\\"TEST_VAR\\\")\\n            assert value == \\\"memory_value\\\"\\n        finally:\\n            del os.environ[\\\"TEST_VAR\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_get_variable_is_coroutine(self, variables):\\n        \\\"\\\"\\\"get_variable is async to match custom component call sites.\\\"\\\"\\\"\\n        import inspect\\n\\n        assert inspect.iscoroutinefunction(variables.get_variable)\\n        coro = variables.get_variable(\\\"anything\\\")\\n        assert inspect.iscoroutine(coro)\\n        await coro\\n\\n    @pytest.mark.asyncio\\n    async def test_get_variable_absorbs_extra_kwargs(self, variables):\\n        \\\"\\\"\\\"Extra kwargs are accepted for compatibility with langflow call signature.\\\"\\\"\\\"\\n        os.environ[\\\"KWARG_TEST\\\"] = \\\"value-from-env\\\"\\n        try:\\n            value = await variables.get_variable(user_id=\\\"random-uuid\\\", name=\\\"KWARG_TEST\\\", field=\\\"value\\\", session=None)\\n            assert value == \\\"value-from-env\\\"\\n        finally:\\n            del os.environ[\\\"KWARG_TEST\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_strict_no_bearer_token_from_access_token_env(self, variables):\\n        \\\"\\\"\\\"*_bearer_token is not synthesized from *_access_token; exact env keys only.\\\"\\\"\\\"\\n        os.environ[\\\"WXO_DEMO_ACCESS_TOKEN\\\"] = \\\"token-123\\\"  # noqa: S105\\n        try:\\n            assert await variables.get_variable(\\\"wxo_demo_bearer_token\\\") is None\\n            assert await variables.get_variable(\\\"WXO_DEMO_ACCESS_TOKEN\\\") == \\\"token-123\\\"\\n        finally:\\n            del os.environ[\\\"WXO_DEMO_ACCESS_TOKEN\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_get_variable_from_langflow_request_variables(self, variables):\\n        \\\"\\\"\\\"Test request-scoped variables are read from LANGFLOW_REQUEST_VARIABLES.\\\"\\\"\\\"\\n        os.environ[\\\"LANGFLOW_REQUEST_VARIABLES\\\"] = '{\\\"runtime_token\\\":\\\"abc123\\\",\\\"normal_key\\\":\\\"value1\\\"}'\\n        try:\\n            assert await variables.get_variable(\\\"runtime_token\\\") == \\\"abc123\\\"\\n            assert await variables.get_variable(\\\"normal_key\\\") == \\\"value1\\\"\\n        finally:\\n            del os.environ[\\\"LANGFLOW_REQUEST_VARIABLES\\\"]\\n\\n    async def test_global_alias_from_request_scope(self, variables):\\n        \\\"\\\"\\\"x-langflow-global-var-* aliases resolve from request-scoped variables.\\\"\\\"\\\"\\n        from lfx.services.variable.request_scope import activate_request_variables, reset_request_variables\\n\\n        token = activate_request_variables({\\\"x-langflow-global-var-access-token\\\": \\\"alias-token\\\"})\\n        try:\\n            assert await variables.get_variable(\\\"access_token\\\") == \\\"alias-token\\\"\\n        finally:\\n            reset_request_variables(token)\\n\\n    async def test_request_scope_overrides_env(self, variables):\\n        \\\"\\\"\\\"A request-scoped variable wins over an env var of the same name (core feature).\\\"\\\"\\\"\\n        from lfx.services.variable.request_scope import activate_request_variables, reset_request_variables\\n\\n        os.environ[\\\"SHARED_VAR\\\"] = \\\"env-value\\\"\\n        token = activate_request_variables({\\\"SHARED_VAR\\\": \\\"request-value\\\"})\\n        try:\\n            assert await variables.get_variable(\\\"SHARED_VAR\\\") == \\\"request-value\\\"\\n        finally:\\n            reset_request_variables(token)\\n            del os.environ[\\\"SHARED_VAR\\\"]\\n\\n    async def test_request_scope_alias_overrides_env(self, variables):\\n        \\\"\\\"\\\"A request-scoped x-langflow-global-var-* alias wins over an env var of the same name.\\n\\n        Ensures a caller's per-request credential is never shadowed by an ambient process\\n        credential, regardless of which form (exact name or alias) the caller supplied.\\n        \\\"\\\"\\\"\\n        from lfx.services.variable.request_scope import activate_request_variables, reset_request_variables\\n\\n        os.environ[\\\"ACCESS_TOKEN\\\"] = \\\"env-token\\\"  # noqa: S105\\n        token = activate_request_variables({\\\"x-langflow-global-var-access-token\\\": \\\"alias-token\\\"})\\n        try:\\n            assert await variables.get_variable(\\\"ACCESS_TOKEN\\\") == \\\"alias-token\\\"\\n        finally:\\n            reset_request_variables(token)\\n            del os.environ[\\\"ACCESS_TOKEN\\\"]\\n\\n    async def test_in_memory_overrides_request_scope(self, variables):\\n        \\\"\\\"\\\"An in-memory variable wins over a request-scoped variable of the same name.\\\"\\\"\\\"\\n        from lfx.services.variable.request_scope import activate_request_variables, reset_request_variables\\n\\n        variables.set_variable(\\\"SHARED_VAR\\\", \\\"memory-value\\\")\\n        token = activate_request_variables({\\\"SHARED_VAR\\\": \\\"request-value\\\"})\\n        try:\\n            assert await variables.get_variable(\\\"SHARED_VAR\\\") == \\\"memory-value\\\"\\n        finally:\\n            reset_request_variables(token)\\n\\n    @pytest.mark.asyncio\\n    async def test_langflow_request_variables_invalid_json_falls_back(self, variables):\\n        \\\"\\\"\\\"Test invalid request variable JSON does not break env fallback.\\\"\\\"\\\"\\n        os.environ[\\\"LANGFLOW_REQUEST_VARIABLES\\\"] = \\\"{not-json\\\"\\n        os.environ[\\\"FALLBACK_ENV_KEY\\\"] = \\\"fallback-value\\\"\\n        try:\\n            assert await variables.get_variable(\\\"FALLBACK_ENV_KEY\\\") == \\\"fallback-value\\\"\\n        finally:\\n            del os.environ[\\\"LANGFLOW_REQUEST_VARIABLES\\\"]\\n            del os.environ[\\\"FALLBACK_ENV_KEY\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_strict_no_bearer_token_from_request_access_token(self, variables):\\n        \\\"\\\"\\\"Request-scoped *_access_token does not satisfy *_bearer_token name.\\\"\\\"\\\"\\n        os.environ[\\\"LANGFLOW_REQUEST_VARIABLES\\\"] = '{\\\"wxo_github_access_token\\\":\\\"request-token\\\"}'\\n        try:\\n            assert await variables.get_variable(\\\"wxo_github_bearer_token\\\") is None\\n            assert await variables.get_variable(\\\"wxo_github_access_token\\\") == \\\"request-token\\\"\\n        finally:\\n            del os.environ[\\\"LANGFLOW_REQUEST_VARIABLES\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_non_wxo_access_token_does_not_create_bearer_alias(self, variables):\\n        \\\"\\\"\\\"Test generic non-WXO token variables are read by exact key.\\\"\\\"\\\"\\n        os.environ[\\\"DEMO_ACCESS_TOKEN\\\"] = \\\"token-456\\\"  # noqa: S105\\n        try:\\n            assert await variables.get_variable(\\\"DEMO_ACCESS_TOKEN\\\") == \\\"token-456\\\"\\n        finally:\\n            del os.environ[\\\"DEMO_ACCESS_TOKEN\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_explicit_bearer_token_env_not_listed_in_memory(self, variables):\\n        \\\"\\\"\\\"Env-backed reads do not add names to the in-memory variable list.\\\"\\\"\\\"\\n        os.environ[\\\"WXO_DEMO_BEARER_TOKEN\\\"] = \\\"Bearer explicit-789\\\"  # noqa: S105\\n        try:\\n            assert await variables.get_variable(\\\"WXO_DEMO_BEARER_TOKEN\\\") == \\\"Bearer explicit-789\\\"\\n            assert \\\"WXO_DEMO_BEARER_TOKEN\\\" not in variables.list_variables()\\n        finally:\\n            del os.environ[\\\"WXO_DEMO_BEARER_TOKEN\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_strict_no_token_access_token_alias_resolution(self, variables):\\n        \\\"\\\"\\\"Strict matching: token and access_token are not interchangeable.\\\"\\\"\\\"\\n        os.environ[\\\"LANGFLOW_REQUEST_VARIABLES\\\"] = '{\\\"access_token\\\":\\\"request-access\\\"}'\\n        try:\\n            assert await variables.get_variable(\\\"token\\\") is None\\n            assert await variables.get_variable(\\\"access_token\\\") == \\\"request-access\\\"\\n        finally:\\n            del os.environ[\\\"LANGFLOW_REQUEST_VARIABLES\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_strict_no_prefixed_token_alias_resolution(self, variables):\\n        \\\"\\\"\\\"Strict matching for prefixed token/access_token variables.\\\"\\\"\\\"\\n        os.environ[\\\"LANGFLOW_REQUEST_VARIABLES\\\"] = '{\\\"my_app_access_token\\\":\\\"prefixed-token\\\"}'\\n        try:\\n            assert await variables.get_variable(\\\"my_app_token\\\") is None\\n            assert await variables.get_variable(\\\"my_app_access_token\\\") == \\\"prefixed-token\\\"\\n        finally:\\n            del os.environ[\\\"LANGFLOW_REQUEST_VARIABLES\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_global_var_alias_resolution(self, variables):\\n        \\\"\\\"\\\"Test x-langflow-global-var-* alias lookup.\\\"\\\"\\\"\\n        os.environ[\\\"x-langflow-global-var-access-token\\\"] = \\\"global-token\\\"  # noqa: SIM112\\n        try:\\n            assert await variables.get_variable(\\\"access_token\\\") == \\\"global-token\\\"\\n            assert await variables.get_variable(\\\"token\\\") is None\\n        finally:\\n            del os.environ[\\\"x-langflow-global-var-access-token\\\"]  # noqa: SIM112\\n\\n    @pytest.mark.asyncio\\n    async def test_teardown(self, variables):\\n        \\\"\\\"\\\"Test service teardown clears variables.\\\"\\\"\\\"\\n        variables.set_variable(\\\"test_key\\\", \\\"test_value\\\")\\n        await variables.teardown()\\n        # Variables should be cleared (verify via public API)\\n        assert variables.list_variables() == []\\n        assert await variables.get_variable(\\\"test_key\\\") is None\\n\\n\\nclass TestMinimalServicesIntegration:\\n    \\\"\\\"\\\"Integration tests for minimal services working together.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_all_minimal_services_initialize(self, mock_session_service, mock_settings_service):\\n        \\\"\\\"\\\"Test that all minimal services can be initialized.\\\"\\\"\\\"\\n        storage = LocalStorageService(mock_session_service, mock_settings_service)\\n        telemetry = TelemetryService()\\n        tracing = TracingService()\\n        variables = VariableService()\\n\\n        assert storage.ready\\n        assert telemetry.ready\\n        assert tracing.ready\\n        assert variables.ready\\n\\n    @pytest.mark.asyncio\\n    async def test_minimal_services_teardown_all(self, mock_session_service, mock_settings_service):\\n        \\\"\\\"\\\"Test tearing down all minimal services.\\\"\\\"\\\"\\n        storage = LocalStorageService(mock_session_service, mock_settings_service)\\n        telemetry = TelemetryService()\\n        tracing = TracingService()\\n        variables = VariableService()\\n\\n        # Should all teardown without errors\\n        await storage.teardown()\\n        await telemetry.teardown()\\n        await tracing.teardown()\\n        await variables.teardown()\\n\\n    @pytest.mark.asyncio\\n    async def test_storage_with_tracing(self, mock_session_service, mock_settings_service):\\n        \\\"\\\"\\\"Test using storage with tracing.\\\"\\\"\\\"\\n        storage = LocalStorageService(mock_session_service, mock_settings_service)\\n        tracing = TracingService()\\n\\n        tracing.add_log(\\\"storage_test\\\", {\\\"operation\\\": \\\"save\\\", \\\"flow_id\\\": \\\"123\\\"})\\n        await storage.save_file(\\\"flow_123\\\", \\\"test.txt\\\", b\\\"content\\\")\\n        tracing.add_log(\\\"storage_test\\\", {\\\"operation\\\": \\\"saved\\\", \\\"flow_id\\\": \\\"123\\\"})\\n\\n        # Should complete without errors\\n        assert await storage.get_file(\\\"flow_123\\\", \\\"test.txt\\\") == b\\\"content\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/test_no_env_fallback_credentials.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4f6d06aefd7031f17e4858f7ef7035729df203b39a7a79baaa5b411c8f2beb75\",\"content\":\"\\\"\\\"\\\"Regression tests for ``no_env_fallback`` in the post-DB-miss provider fallback.\\n\\n``get_all_variables_for_provider`` has a post-async fallback loop that, after the\\ndatabase lookup, fills any still-missing provider keys from ``os.environ`` (so a\\n``SECRET_KEY`` rotation that silently drops decrypted values doesn't leave the\\nassistant rejecting requests). That loop must honor the request's\\n``no_env_fallback`` contract \u2014 a served flow under ``no_env_fallback`` must stay\\nisolated from process-wide credentials.\\n\\nThese tests drive the ``user_id``-not-None path (the only one reaching the\\npost-async fallback) with a forced DB miss by monkeypatching ``run_until_complete``\\nto return an empty mapping, so no real database is required.\\n\\\"\\\"\\\"\\n\\nimport uuid\\nfrom contextlib import asynccontextmanager\\n\\nimport pytest\\nfrom lfx.base.models.unified_models import credentials\\nfrom lfx.services.variable.request_scope import activate_no_env_fallback, reset_no_env_fallback\\n\\n\\ndef _force_db_miss(monkeypatch):\\n    \\\"\\\"\\\"Make the in-function DB lookup return a miss without touching a database.\\\"\\\"\\\"\\n\\n    def _fake_run(coro):\\n        coro.close()  # avoid \\\"coroutine was never awaited\\\" warnings\\n        return {}\\n\\n    monkeypatch.setattr(credentials, \\\"run_until_complete\\\", _fake_run)\\n\\n\\ndef test_post_db_miss_fallback_respects_no_env_fallback(monkeypatch):\\n    \\\"\\\"\\\"Under no_env_fallback, the post-DB-miss loop must NOT read os.environ.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"OPENAI_API_KEY\\\", \\\"env-secret\\\")  # pragma: allowlist secret\\n    _force_db_miss(monkeypatch)\\n\\n    token = activate_no_env_fallback(disabled=True)\\n    try:\\n        values = credentials.get_all_variables_for_provider(uuid.uuid4(), \\\"OpenAI\\\")\\n    finally:\\n        reset_no_env_fallback(token)\\n\\n    assert \\\"OPENAI_API_KEY\\\" not in values  # gated: env not read under no_env_fallback\\n\\n\\ndef test_post_db_miss_fallback_uses_env_when_fallback_enabled(monkeypatch):\\n    \\\"\\\"\\\"With env fallback enabled (default), the post-DB-miss loop still reads os.environ.\\n\\n    Guards against regressing the SECRET_KEY-rotation fix this fallback exists for.\\n    \\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"OPENAI_API_KEY\\\", \\\"env-secret\\\")  # pragma: allowlist secret\\n    _force_db_miss(monkeypatch)\\n\\n    # no_env_fallback NOT active (default) -> env fallback is allowed.\\n    values = credentials.get_all_variables_for_provider(uuid.uuid4(), \\\"OpenAI\\\")\\n\\n    assert values.get(\\\"OPENAI_API_KEY\\\") == \\\"env-secret\\\"  # pragma: allowlist secret\\n\\n\\ndef test_db_resolution_error_does_not_fall_back_to_process_environment(monkeypatch):\\n    \\\"\\\"\\\"Only an actual missing variable may use the process-wide fallback.\\\"\\\"\\\"\\n\\n    class BrokenVariableService:\\n        async def get_variable(self, **_kwargs):\\n            msg = \\\"credential decryption failed\\\"\\n            raise ValueError(msg)\\n\\n    @asynccontextmanager\\n    async def fake_session_scope():\\n        yield object()\\n\\n    monkeypatch.setattr(credentials, \\\"session_scope\\\", fake_session_scope)\\n    monkeypatch.setattr(credentials, \\\"get_variable_service\\\", BrokenVariableService)\\n    monkeypatch.setenv(\\\"OPENAI_API_KEY\\\", \\\"server-wide-key\\\")  # pragma: allowlist secret\\n\\n    with pytest.raises(ValueError, match=\\\"credential decryption failed\\\"):\\n        credentials.get_all_variables_for_provider(uuid.uuid4(), \\\"OpenAI\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/test_request_scope_isolation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"72dca73cbc9bdef383ca333c57ef75a741a61cdac21afac59c205709530194a7\",\"content\":\"\\\"\\\"\\\"Isolation guarantees for request-scoped variables (lfx serve concurrency).\\n\\nThese tests verify the two properties that matter for running multiple flows in a\\nsingle ``lfx serve`` process:\\n\\n1. **Per-request isolation** - one request's ``global_vars`` must never be visible\\n   to a concurrently-running request. This is provided by the ContextVar in\\n   :mod:`lfx.services.variable.request_scope`: each asyncio task gets its own\\n   context copy, so activating a scope in one task cannot leak into another.\\n2. **No accidental env fallback for supplied credentials** - when a request scope\\n   provides a variable, resolution must use it and must not consult ``os.environ``\\n   for that name (so a stale/foreign env var can never shadow a request credential).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport os\\nfrom unittest.mock import patch\\n\\nfrom lfx.services.variable.request_scope import (\\n    activate_no_env_fallback,\\n    activate_request_variables,\\n    get_active_request_variables,\\n    reset_no_env_fallback,\\n    reset_request_variables,\\n)\\nfrom lfx.services.variable.service import VariableService\\n\\n\\nasync def test_concurrent_request_scopes_are_isolated():\\n    \\\"\\\"\\\"Two concurrent requests each see only their own request-scoped variable.\\\"\\\"\\\"\\n    service = VariableService()\\n    observed: dict[str, str | None] = {}\\n\\n    async def handle(request_id: str, secret: str) -> None:\\n        token = activate_request_variables({\\\"access_token\\\": secret})\\n        try:\\n            # Yield so the sibling task activates its own scope before we read;\\n            # if the ContextVar leaked across tasks this read would see it.\\n            await asyncio.sleep(0.01)\\n            observed[request_id] = await service.get_variable(\\\"access_token\\\")\\n            # Read again after another yield to catch any cross-task overwrite.\\n            await asyncio.sleep(0.01)\\n            observed[f\\\"{request_id}-recheck\\\"] = await service.get_variable(\\\"access_token\\\")\\n        finally:\\n            reset_request_variables(token)\\n\\n    await asyncio.gather(handle(\\\"A\\\", \\\"secret-A\\\"), handle(\\\"B\\\", \\\"secret-B\\\"))\\n\\n    assert observed[\\\"A\\\"] == \\\"secret-A\\\"\\n    assert observed[\\\"A-recheck\\\"] == \\\"secret-A\\\"\\n    assert observed[\\\"B\\\"] == \\\"secret-B\\\"\\n    assert observed[\\\"B-recheck\\\"] == \\\"secret-B\\\"\\n\\n\\nasync def test_unscoped_request_does_not_see_a_concurrent_scope():\\n    \\\"\\\"\\\"A request with no active scope must not observe another request's live scope.\\\"\\\"\\\"\\n    service = VariableService()\\n    scope_active = asyncio.Event()\\n    scope_may_exit = asyncio.Event()\\n    observed: dict[str, str | None] = {}\\n\\n    async def scoped() -> None:\\n        token = activate_request_variables({\\\"access_token\\\": \\\"secret-A\\\"})\\n        try:\\n            scope_active.set()\\n            await scope_may_exit.wait()  # hold the scope open while the other task reads\\n        finally:\\n            reset_request_variables(token)\\n\\n    async def unscoped() -> None:\\n        await scope_active.wait()  # read while scoped()'s scope is definitely active\\n        observed[\\\"value\\\"] = await service.get_variable(\\\"access_token\\\")\\n        scope_may_exit.set()\\n\\n    await asyncio.gather(scoped(), unscoped())\\n\\n    assert observed[\\\"value\\\"] is None\\n\\n\\nasync def test_scope_does_not_leak_after_reset():\\n    \\\"\\\"\\\"After reset, the variable is no longer resolvable (request teardown is clean).\\\"\\\"\\\"\\n    service = VariableService()\\n\\n    token = activate_request_variables({\\\"access_token\\\": \\\"secret\\\"})\\n    assert await service.get_variable(\\\"access_token\\\") == \\\"secret\\\"\\n    reset_request_variables(token)\\n\\n    assert get_active_request_variables() is None\\n    assert await service.get_variable(\\\"access_token\\\") is None\\n\\n\\nasync def test_scoped_value_used_without_consulting_env_for_that_name():\\n    \\\"\\\"\\\"A request-supplied variable is returned without falling back to os.environ.\\n\\n    Guards against a regression where the env tier runs first (or in addition),\\n    which would let a process env var shadow a per-request credential.\\n    \\\"\\\"\\\"\\n    service = VariableService()\\n    token = activate_request_variables({\\\"access_token\\\": \\\"from-request\\\"})\\n    with (\\n        patch.dict(os.environ, {\\\"access_token\\\": \\\"from-env\\\"}),\\n        patch(\\\"lfx.services.variable.service.os.getenv\\\") as mock_getenv,\\n    ):\\n        try:\\n            assert await service.get_variable(\\\"access_token\\\") == \\\"from-request\\\"\\n        finally:\\n            reset_request_variables(token)\\n\\n    name_lookups = [c for c in mock_getenv.call_args_list if c.args and c.args[0] == \\\"access_token\\\"]\\n    assert not name_lookups, f\\\"os.getenv('access_token') must not be consulted, got: {name_lookups}\\\"\\n\\n\\nasync def test_env_fallback_enabled_by_default():\\n    \\\"\\\"\\\"Without the no-env-fallback flag, env resolution still works (default preserved).\\\"\\\"\\\"\\n    service = VariableService()\\n    with patch.dict(os.environ, {\\\"DEFAULT_SECRET\\\": \\\"from-env\\\"}):\\n        assert await service.get_variable(\\\"DEFAULT_SECRET\\\") == \\\"from-env\\\"\\n\\n\\nasync def test_no_env_fallback_suppresses_env_in_variable_service():\\n    \\\"\\\"\\\"With env fallback disabled, a variable only in os.environ resolves to None.\\n\\n    Closes the gap where VariableService (model/KB credential path) ignored\\n    ``no_env_fallback`` and leaked process env credentials even under --no-env-fallback.\\n    \\\"\\\"\\\"\\n    service = VariableService()\\n    scope_token = activate_request_variables({\\\"access_token\\\": \\\"from-request\\\"})\\n    flag_token = activate_no_env_fallback(disabled=True)\\n    with (\\n        patch.dict(os.environ, {\\\"OTHER_SECRET\\\": \\\"from-env\\\"}),\\n        patch(\\\"lfx.services.variable.service.os.getenv\\\") as mock_getenv,\\n    ):\\n        try:\\n            # Supplied via the request scope -> still resolves.\\n            assert await service.get_variable(\\\"access_token\\\") == \\\"from-request\\\"\\n            # Only in process env -> must NOT resolve when fallback is disabled.\\n            assert await service.get_variable(\\\"OTHER_SECRET\\\") is None\\n        finally:\\n            reset_no_env_fallback(flag_token)\\n            reset_request_variables(scope_token)\\n\\n    assert not mock_getenv.call_args_list, f\\\"os.getenv must not be consulted, got: {mock_getenv.call_args_list}\\\"\\n\\n\\nasync def test_no_env_fallback_suppresses_langflow_request_variables_env():\\n    \\\"\\\"\\\"Env fallback disabled + no active scope must not leak the process LANGFLOW_REQUEST_VARIABLES blob.\\n\\n    Regression: _get_request_variables() read os.getenv(\\\"LANGFLOW_REQUEST_VARIABLES\\\")\\n    before the no-env-fallback gate, so an empty-global_vars request under\\n    --no-env-fallback (which binds the scope to None) still resolved credentials\\n    from the process env blob, violating the \\\"never reads os.environ\\\" contract.\\n    \\\"\\\"\\\"\\n    service = VariableService()\\n    scope_token = activate_request_variables(None)  # None == empty global_vars in serve\\n    flag_token = activate_no_env_fallback(disabled=True)\\n    with patch.dict(os.environ, {\\\"LANGFLOW_REQUEST_VARIABLES\\\": '{\\\"leaked_token\\\": \\\"SHOULD-NOT-LEAK\\\"}'}):\\n        try:\\n            assert await service.get_variable(\\\"leaked_token\\\") is None\\n        finally:\\n            reset_no_env_fallback(flag_token)\\n            reset_request_variables(scope_token)\\n\\n\\nasync def test_langflow_request_variables_env_blob_used_when_fallback_enabled():\\n    \\\"\\\"\\\"Env blob resolves when fallback is enabled: null dropped, structured -> valid JSON string.\\\"\\\"\\\"\\n    service = VariableService()\\n    scope_token = activate_request_variables(None)\\n    blob = '{\\\"shared_token\\\": \\\"from-env-blob\\\", \\\"null_cred\\\": null, \\\"nested\\\": {\\\"a\\\": 1}}'\\n    with patch.dict(os.environ, {\\\"LANGFLOW_REQUEST_VARIABLES\\\": blob}):\\n        try:\\n            assert await service.get_variable(\\\"shared_token\\\") == \\\"from-env-blob\\\"\\n            # null is dropped (not the truthy string \\\"None\\\"); env/None fallthrough -> None.\\n            assert await service.get_variable(\\\"null_cred\\\") is None\\n            # Structured value serialized as valid JSON, round-trippable via json.loads.\\n            assert await service.get_variable(\\\"nested\\\") == '{\\\"a\\\": 1}'\\n        finally:\\n            reset_request_variables(scope_token)\\n\\n\\nasync def test_no_env_fallback_flag_is_isolated_per_request():\\n    \\\"\\\"\\\"The no-env-fallback flag is per-request.\\n\\n    One request disabling it must not affect a concurrent request that allows\\n    env fallback.\\n    \\\"\\\"\\\"\\n    service = VariableService()\\n    observed: dict[str, str | None] = {}\\n\\n    async def strict_request() -> None:\\n        # Active (non-None) scope so resolution never reads LANGFLOW_REQUEST_VARIABLES.\\n        scope = activate_request_variables({\\\"unused\\\": \\\"x\\\"})\\n        flag = activate_no_env_fallback(disabled=True)\\n        try:\\n            await asyncio.sleep(0.01)  # let the lenient request run concurrently\\n            observed[\\\"strict\\\"] = await service.get_variable(\\\"SHARED_ENV\\\")\\n        finally:\\n            reset_no_env_fallback(flag)\\n            reset_request_variables(scope)\\n\\n    async def lenient_request() -> None:\\n        scope = activate_request_variables({\\\"unused\\\": \\\"y\\\"})\\n        flag = activate_no_env_fallback(disabled=False)\\n        try:\\n            await asyncio.sleep(0.01)\\n            observed[\\\"lenient\\\"] = await service.get_variable(\\\"SHARED_ENV\\\")\\n        finally:\\n            reset_no_env_fallback(flag)\\n            reset_request_variables(scope)\\n\\n    with patch.dict(os.environ, {\\\"SHARED_ENV\\\": \\\"from-env\\\"}):\\n        await asyncio.gather(strict_request(), lenient_request())\\n\\n    assert observed[\\\"strict\\\"] is None  # env fallback disabled for this request\\n    assert observed[\\\"lenient\\\"] == \\\"from-env\\\"  # env fallback allowed for this request\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/test_service_manager.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"385cccaa0bca931625354c4e7bf099dd7d74aa76e725695d5663167714b7205e\",\"content\":\"\\\"\\\"\\\"Tests for the ServiceManager plugin system.\\\"\\\"\\\"\\n\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.services.base import Service\\nfrom lfx.services.manager import NoFactoryRegisteredError, ServiceManager\\nfrom lfx.services.model_provider_policy import (\\n    BaseModelProviderPolicyService,\\n    ModelProviderPolicyContext,\\n    ModelProviderPolicyPurpose,\\n    ModelProviderPolicyService,\\n)\\nfrom lfx.services.schema import ServiceType\\nfrom lfx.services.storage.local import LocalStorageService\\nfrom lfx.services.telemetry.service import TelemetryService\\nfrom lfx.services.tracing.service import TracingService\\nfrom lfx.services.variable.service import VariableService\\n\\nfrom .conftest import MockSessionService\\n\\n\\nclass DenyAllModelProviderPolicyService(BaseModelProviderPolicyService):\\n    \\\"\\\"\\\"Test plugin proving that deployment config replaces the OSS default.\\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        super().__init__()\\n        self.set_ready()\\n\\n    @property\\n    def name(self) -> str:\\n        return ServiceType.MODEL_PROVIDER_POLICY_SERVICE.value\\n\\n    def get_allowed_provider_ids(self, *, context, candidate_provider_ids, purpose):  # noqa: ARG002\\n        return frozenset()\\n\\n\\n@pytest.fixture\\ndef service_manager():\\n    \\\"\\\"\\\"Create a fresh ServiceManager for each test.\\\"\\\"\\\"\\n    import asyncio\\n\\n    manager = ServiceManager()\\n    manager.register_service_class(ServiceType.SESSION_SERVICE, MockSessionService, override=True)\\n    yield manager\\n    asyncio.run(manager.teardown())\\n\\n\\n@pytest.fixture\\ndef temp_config_dir(tmp_path):\\n    \\\"\\\"\\\"Create a temporary config directory.\\\"\\\"\\\"\\n    config_dir = tmp_path / \\\"config\\\"\\n    config_dir.mkdir()\\n    return config_dir\\n\\n\\nclass TestServiceRegistration:\\n    \\\"\\\"\\\"Tests for service registration with real implementations.\\\"\\\"\\\"\\n\\n    def test_register_storage_service(self, service_manager):\\n        \\\"\\\"\\\"Test registering the real LocalStorageService.\\\"\\\"\\\"\\n        service_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService, override=True)\\n\\n        assert ServiceType.STORAGE_SERVICE in service_manager.service_classes\\n        assert service_manager.service_classes[ServiceType.STORAGE_SERVICE] == LocalStorageService\\n\\n    def test_register_multiple_real_services(self, service_manager):\\n        \\\"\\\"\\\"Test registering multiple real services.\\\"\\\"\\\"\\n        service_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService, override=True)\\n        service_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TelemetryService, override=True)\\n        service_manager.register_service_class(ServiceType.TRACING_SERVICE, TracingService, override=True)\\n        service_manager.register_service_class(ServiceType.VARIABLE_SERVICE, VariableService, override=True)\\n\\n        # 4 services + SESSION_SERVICE from fixture = 5\\n        assert len(service_manager.service_classes) == 5\\n        assert service_manager.service_classes[ServiceType.STORAGE_SERVICE] == LocalStorageService\\n        assert service_manager.service_classes[ServiceType.TELEMETRY_SERVICE] == TelemetryService\\n        assert service_manager.service_classes[ServiceType.TRACING_SERVICE] == TracingService\\n        assert service_manager.service_classes[ServiceType.VARIABLE_SERVICE] == VariableService\\n\\n    def test_register_service_class_no_override(self, service_manager):\\n        \\\"\\\"\\\"Test that override=False prevents replacement.\\\"\\\"\\\"\\n        service_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService, override=True)\\n\\n        # Try to register different class with override=False\\n        service_manager.register_service_class(ServiceType.STORAGE_SERVICE, TelemetryService, override=False)\\n\\n        # Should still have the original\\n        assert service_manager.service_classes[ServiceType.STORAGE_SERVICE] == LocalStorageService\\n\\n    def test_register_service_class_with_override(self, service_manager):\\n        \\\"\\\"\\\"Test that override=True replaces existing registration.\\\"\\\"\\\"\\n        service_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TelemetryService, override=True)\\n\\n        # Override with different service\\n        service_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TracingService, override=True)\\n\\n        # Should have the new one\\n        assert service_manager.service_classes[ServiceType.TELEMETRY_SERVICE] == TracingService\\n\\n    def test_cannot_register_settings_service(self, service_manager):\\n        \\\"\\\"\\\"Test that settings service cannot be registered via plugins.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Settings service cannot be registered\\\"):\\n            service_manager.register_service_class(ServiceType.SETTINGS_SERVICE, LocalStorageService)\\n\\n\\nclass TestPluginDiscovery:\\n    \\\"\\\"\\\"Tests for plugin discovery with real service paths.\\\"\\\"\\\"\\n\\n    def test_discover_storage_from_config_file(self, service_manager, temp_config_dir):\\n        \\\"\\\"\\\"Test discovering LocalStorageService from lfx.toml.\\\"\\\"\\\"\\n        config_file = temp_config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        service_manager.discover_plugins(temp_config_dir)\\n\\n        assert ServiceType.STORAGE_SERVICE in service_manager.service_classes\\n        assert service_manager.service_classes[ServiceType.STORAGE_SERVICE] == LocalStorageService\\n\\n    def test_model_provider_policy_config_overrides_allow_all_default(self, service_manager, temp_config_dir):\\n        service_manager.register_service_class(\\n            ServiceType.MODEL_PROVIDER_POLICY_SERVICE,\\n            ModelProviderPolicyService,\\n            override=True,\\n        )\\n        (temp_config_dir / \\\"lfx.toml\\\").write_text(\\n            f\\\"\\\"\\\"\\n[services]\\nmodel_provider_policy_service = \\\"{__name__}:DenyAllModelProviderPolicyService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        service_manager.discover_plugins(temp_config_dir)\\n        service = service_manager.get(ServiceType.MODEL_PROVIDER_POLICY_SERVICE)\\n        snapshot = service.resolve(\\n            context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n            candidate_provider_ids=frozenset({\\\"openai\\\", \\\"anthropic\\\"}),\\n            purpose=ModelProviderPolicyPurpose.USE,\\n        )\\n\\n        assert isinstance(service, DenyAllModelProviderPolicyService)\\n        assert snapshot.allowed_provider_ids == frozenset()\\n\\n    @pytest.mark.parametrize(\\n        (\\\"service_path\\\", \\\"error\\\"),\\n        [\\n            (\\n                \\\"nonexistent.module:MissingModelProviderPolicyService\\\",\\n                \\\"could not be loaded\\\",\\n            ),\\n            (\\n                \\\"lfx.services.storage.local:LocalStorageService\\\",\\n                \\\"must subclass BaseModelProviderPolicyService\\\",\\n            ),\\n        ],\\n    )\\n    def test_invalid_explicit_model_provider_policy_fails_closed(\\n        self,\\n        service_manager,\\n        temp_config_dir,\\n        service_path,\\n        error,\\n    ):\\n        (temp_config_dir / \\\"lfx.toml\\\").write_text(\\n            f\\\"\\\"\\\"\\n[services]\\nmodel_provider_policy_service = \\\"{service_path}\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        with pytest.raises(RuntimeError, match=error):\\n            service_manager.discover_plugins(temp_config_dir)\\n\\n    def test_missing_explicit_policy_bundle_fails_startup(self, service_manager, temp_config_dir):\\n        (temp_config_dir / \\\"lfx.toml\\\").write_text(\\n            \\\"\\\"\\\"\\n[services]\\npolicy_bundle_service = \\\"nonexistent.module:MissingPolicyBundleService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        with pytest.raises(RuntimeError, match=\\\"Configured policy bundle service could not be loaded\\\"):\\n            service_manager.discover_plugins(temp_config_dir)\\n\\n    def test_discover_multiple_services_from_config(self, service_manager, temp_config_dir):\\n        \\\"\\\"\\\"Test discovering multiple real services from config.\\\"\\\"\\\"\\n        config_file = temp_config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\ntelemetry_service = \\\"lfx.services.telemetry.service:TelemetryService\\\"\\ntracing_service = \\\"lfx.services.tracing.service:TracingService\\\"\\nvariable_service = \\\"lfx.services.variable.service:VariableService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        service_manager.discover_plugins(temp_config_dir)\\n\\n        assert ServiceType.STORAGE_SERVICE in service_manager.service_classes\\n        assert ServiceType.TELEMETRY_SERVICE in service_manager.service_classes\\n        assert ServiceType.TRACING_SERVICE in service_manager.service_classes\\n        assert ServiceType.VARIABLE_SERVICE in service_manager.service_classes\\n\\n    def test_discover_from_pyproject_toml(self, service_manager, temp_config_dir):\\n        \\\"\\\"\\\"Test discovering services from pyproject.toml.\\\"\\\"\\\"\\n        config_file = temp_config_dir / \\\"pyproject.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[tool.lfx.services]\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        service_manager.discover_plugins(temp_config_dir)\\n\\n        assert ServiceType.STORAGE_SERVICE in service_manager.service_classes\\n\\n    def test_lfx_toml_takes_precedence_over_pyproject(self, service_manager, temp_config_dir):\\n        \\\"\\\"\\\"Test that lfx.toml is preferred over pyproject.toml.\\\"\\\"\\\"\\n        # Create both files\\n        (temp_config_dir / \\\"lfx.toml\\\").write_text(\\n            \\\"\\\"\\\"\\n[services]\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\n\\\"\\\"\\\"\\n        )\\n        (temp_config_dir / \\\"pyproject.toml\\\").write_text(\\n            \\\"\\\"\\\"\\n[tool.lfx.services]\\ntelemetry_service = \\\"lfx.services.telemetry.service:TelemetryService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        service_manager.discover_plugins(temp_config_dir)\\n\\n        # Should have loaded from lfx.toml (storage_service)\\n        assert ServiceType.STORAGE_SERVICE in service_manager.service_classes\\n        # Should NOT have loaded from pyproject.toml (telemetry_service)\\n        assert ServiceType.TELEMETRY_SERVICE not in service_manager.service_classes\\n\\n    def test_discover_plugins_only_once(self, service_manager, temp_config_dir):\\n        \\\"\\\"\\\"Test that plugin discovery only runs once.\\\"\\\"\\\"\\n        config_file = temp_config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        service_manager.discover_plugins(temp_config_dir)\\n        initial_count = len(service_manager.service_classes)\\n\\n        # Try to discover again\\n        service_manager.discover_plugins(temp_config_dir)\\n\\n        # Should not have changed\\n        assert len(service_manager.service_classes) == initial_count\\n\\n    def test_invalid_service_key_in_config(self, service_manager, temp_config_dir):\\n        \\\"\\\"\\\"Test that invalid service keys are ignored.\\\"\\\"\\\"\\n        config_file = temp_config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\ninvalid_service_key = \\\"some.module:SomeClass\\\"  # pragma: allowlist secret\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        # Should not raise, just log warning\\n        service_manager.discover_plugins(temp_config_dir)\\n\\n        # Valid service should still be registered\\n        assert ServiceType.STORAGE_SERVICE in service_manager.service_classes\\n\\n    def test_invalid_import_path_in_config(self, service_manager, temp_config_dir):\\n        \\\"\\\"\\\"Test that invalid import paths are handled gracefully.\\\"\\\"\\\"\\n        config_file = temp_config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\nstorage_service = \\\"nonexistent.module:NonexistentClass\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        # Should not raise, just log warning\\n        service_manager.discover_plugins(temp_config_dir)\\n\\n        # Service should not be registered\\n        assert ServiceType.STORAGE_SERVICE not in service_manager.service_classes\\n\\n\\nclass TestServiceCreation:\\n    \\\"\\\"\\\"Tests for creating real services with dependency injection.\\\"\\\"\\\"\\n\\n    def test_create_storage_service(self, service_manager):\\n        \\\"\\\"\\\"Test creating LocalStorageService.\\\"\\\"\\\"\\n        service_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService)\\n\\n        service = service_manager.get(ServiceType.STORAGE_SERVICE)\\n\\n        assert isinstance(service, LocalStorageService)\\n        assert service.ready is True\\n        assert service.name == \\\"storage_service\\\"\\n\\n    def test_create_telemetry_service(self, service_manager):\\n        \\\"\\\"\\\"Test creating TelemetryService.\\\"\\\"\\\"\\n        service_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TelemetryService)\\n\\n        service = service_manager.get(ServiceType.TELEMETRY_SERVICE)\\n\\n        assert isinstance(service, TelemetryService)\\n        assert service.ready is True\\n        assert service.name == \\\"telemetry_service\\\"\\n\\n    def test_create_tracing_service(self, service_manager):\\n        \\\"\\\"\\\"Test creating TracingService.\\\"\\\"\\\"\\n        service_manager.register_service_class(ServiceType.TRACING_SERVICE, TracingService)\\n\\n        service = service_manager.get(ServiceType.TRACING_SERVICE)\\n\\n        assert isinstance(service, TracingService)\\n        assert service.ready is True\\n        assert service.name == \\\"tracing_service\\\"\\n\\n    def test_create_variable_service(self, service_manager):\\n        \\\"\\\"\\\"Test creating VariableService.\\\"\\\"\\\"\\n        service_manager.register_service_class(ServiceType.VARIABLE_SERVICE, VariableService)\\n\\n        service = service_manager.get(ServiceType.VARIABLE_SERVICE)\\n\\n        assert isinstance(service, VariableService)\\n        assert service.ready is True\\n        assert service.name == \\\"variable_service\\\"\\n\\n    def test_create_service_with_settings_dependency(self, service_manager):\\n        \\\"\\\"\\\"Test creating a service that depends on settings.\\\"\\\"\\\"\\n\\n        # Create a real service that needs settings\\n        class ServiceWithSettings(Service):\\n            @property\\n            def name(self) -> str:\\n                return \\\"test_service\\\"\\n\\n            def __init__(self, settings_service):\\n                super().__init__()\\n                self.settings = settings_service\\n                self.set_ready()\\n\\n            async def teardown(self) -> None:\\n                pass\\n\\n        service_manager.register_service_class(ServiceType.STORAGE_SERVICE, ServiceWithSettings)\\n\\n        service = service_manager.get(ServiceType.STORAGE_SERVICE)\\n\\n        # Should have settings injected\\n        from lfx.services.settings.service import SettingsService\\n\\n        assert isinstance(service, ServiceWithSettings)\\n        assert isinstance(service.settings, SettingsService)\\n        assert service.ready is True\\n\\n    def test_create_service_caching(self, service_manager):\\n        \\\"\\\"\\\"Test that services are cached (singleton).\\\"\\\"\\\"\\n        service_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService)\\n\\n        service1 = service_manager.get(ServiceType.STORAGE_SERVICE)\\n        service2 = service_manager.get(ServiceType.STORAGE_SERVICE)\\n\\n        assert service1 is service2\\n\\n    def test_settings_service_always_uses_factory(self, service_manager):\\n        \\\"\\\"\\\"Test that settings service always uses factory.\\\"\\\"\\\"\\n        service = service_manager.get(ServiceType.SETTINGS_SERVICE)\\n\\n        from lfx.services.settings.service import SettingsService\\n\\n        assert isinstance(service, SettingsService)\\n\\n    def test_fallback_to_factory_if_no_plugin(self, service_manager):\\n        \\\"\\\"\\\"Test that services fall back to factory if no plugin registered.\\\"\\\"\\\"\\n        # Don't register any plugin for storage\\n        # Should fail since there's no factory either\\n        with pytest.raises(NoFactoryRegisteredError):\\n            service_manager.get(ServiceType.STORAGE_SERVICE)\\n\\n\\nclass TestConflictResolution:\\n    \\\"\\\"\\\"Tests for conflict resolution with real services.\\\"\\\"\\\"\\n\\n    def test_direct_registration_overrides_config(self, service_manager, temp_config_dir):\\n        \\\"\\\"\\\"Test that direct registration overrides config file.\\\"\\\"\\\"\\n        # First load from config\\n        config_file = temp_config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\ntelemetry_service = \\\"lfx.services.telemetry.service:TelemetryService\\\"\\n\\\"\\\"\\\"\\n        )\\n        service_manager.discover_plugins(temp_config_dir)\\n\\n        # Then register via direct call (override=True)\\n        service_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TracingService, override=True)\\n\\n        # Should use the directly registered service\\n        assert service_manager.service_classes[ServiceType.TELEMETRY_SERVICE] == TracingService\\n\\n\\nclass TestTeardown:\\n    \\\"\\\"\\\"Tests for service teardown with real services.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_teardown_all_services(self, service_manager):\\n        \\\"\\\"\\\"Test that teardown clears all services.\\\"\\\"\\\"\\n        service_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService)\\n        service_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TelemetryService)\\n        service_manager.get(ServiceType.STORAGE_SERVICE)\\n        service_manager.get(ServiceType.TELEMETRY_SERVICE)\\n\\n        await service_manager.teardown()\\n\\n        assert len(service_manager.services) == 0\\n        assert len(service_manager.factories) == 0\\n\\n    @pytest.mark.asyncio\\n    async def test_teardown_calls_service_teardown(self, service_manager):\\n        \\\"\\\"\\\"Test that teardown calls each service's teardown method.\\\"\\\"\\\"\\n        service_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService)\\n        storage = service_manager.get(ServiceType.STORAGE_SERVICE)\\n\\n        # Service should exist\\n        assert storage is not None\\n\\n        await service_manager.teardown()\\n\\n        # Services should be cleared\\n        assert ServiceType.STORAGE_SERVICE not in service_manager.services\\n\\n    @pytest.mark.asyncio\\n    async def test_teardown_clears_factories_registered_flag(self, service_manager):\\n        \\\"\\\"\\\"teardown() must clear the factories-registered flag, not just the dict.\\n\\n        get_service() (both lfx and langflow) re-registers factories only when\\n        are_factories_registered() returns False. teardown() empties\\n        self.factories, so if it leaves the flag set, every later lookup skips\\n        re-registration and raises NoFactoryRegisteredError. That surfaced as\\n        flow-execution 500s once Graph.arun routed through the executor service\\n        and a sibling test had torn the global manager down.\\n        \\\"\\\"\\\"\\n        service_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService)\\n        service_manager.get(ServiceType.STORAGE_SERVICE)\\n        service_manager.set_factory_registered()\\n        assert service_manager.are_factories_registered() is True\\n\\n        await service_manager.teardown()\\n\\n        assert service_manager.factories == {}\\n        assert service_manager.are_factories_registered() is False\\n\\n\\nclass TestConfigDirectorySource:\\n    \\\"\\\"\\\"Tests for config_dir parameter with real services.\\\"\\\"\\\"\\n\\n    def test_config_dir_from_settings_service(self, service_manager):\\n        \\\"\\\"\\\"Test that config_dir comes from settings service.\\\"\\\"\\\"\\n        # Create settings service first\\n        settings_service = service_manager.get(ServiceType.SETTINGS_SERVICE)\\n\\n        # Create config in the settings config_dir\\n        config_dir = Path(settings_service.settings.config_dir)\\n        config_dir.mkdir(parents=True, exist_ok=True)\\n\\n        config_file = config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        # Discover plugins (should use settings.config_dir)\\n        service_manager._plugins_discovered = False  # Reset flag\\n        service_manager.discover_plugins()\\n\\n        assert ServiceType.STORAGE_SERVICE in service_manager.service_classes\\n\\n    def test_config_dir_falls_back_to_cwd(self, service_manager, temp_config_dir):\\n        \\\"\\\"\\\"Test that config_dir falls back to cwd if settings not available.\\\"\\\"\\\"\\n        # Don't create settings service\\n        # Should fall back to provided config_dir\\n        config_file = temp_config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        service_manager.discover_plugins(temp_config_dir)\\n\\n        # Should have searched temp_config_dir (passed as param)\\n        assert service_manager._plugins_discovered is True\\n        assert ServiceType.STORAGE_SERVICE in service_manager.service_classes\\n\\n\\nclass TestRealWorldScenarios:\\n    \\\"\\\"\\\"Tests for realistic usage scenarios.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_complete_service_lifecycle(self, service_manager):\\n        \\\"\\\"\\\"Test complete lifecycle: register, create, use, teardown.\\\"\\\"\\\"\\n        # Register\\n        service_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService)\\n\\n        # Create\\n        storage = service_manager.get(ServiceType.STORAGE_SERVICE)\\n        assert storage.ready is True\\n\\n        # Use\\n        await storage.save_file(\\\"test_flow\\\", \\\"test.txt\\\", b\\\"test content\\\")\\n        content = await storage.get_file(\\\"test_flow\\\", \\\"test.txt\\\")\\n        assert content == b\\\"test content\\\"\\n\\n        # Teardown\\n        await service_manager.teardown()\\n        assert ServiceType.STORAGE_SERVICE not in service_manager.services\\n\\n    async def test_multiple_services_working_together(self, service_manager):\\n        \\\"\\\"\\\"Test multiple services can coexist and work together.\\\"\\\"\\\"\\n        # Register all minimal services\\n        service_manager.register_service_class(ServiceType.STORAGE_SERVICE, LocalStorageService)\\n        service_manager.register_service_class(ServiceType.TELEMETRY_SERVICE, TelemetryService)\\n        service_manager.register_service_class(ServiceType.TRACING_SERVICE, TracingService)\\n        service_manager.register_service_class(ServiceType.VARIABLE_SERVICE, VariableService)\\n\\n        # Create all services\\n        storage = service_manager.get(ServiceType.STORAGE_SERVICE)\\n        telemetry = service_manager.get(ServiceType.TELEMETRY_SERVICE)\\n        tracing = service_manager.get(ServiceType.TRACING_SERVICE)\\n        variables = service_manager.get(ServiceType.VARIABLE_SERVICE)\\n\\n        # All should be ready\\n        assert storage.ready is True\\n        assert telemetry.ready is True\\n        assert tracing.ready is True\\n        assert variables.ready is True\\n\\n        # All should be usable\\n        tracing.add_log(\\\"test_trace\\\", {\\\"message\\\": \\\"test\\\"})\\n        variables.set_variable(\\\"TEST_KEY\\\", \\\"test_value\\\")\\n        assert await variables.get_variable(\\\"TEST_KEY\\\") == \\\"test_value\\\"\\n\\n    def test_config_file_with_all_minimal_services(self, service_manager, temp_config_dir):\\n        \\\"\\\"\\\"Test loading all minimal services from config file.\\\"\\\"\\\"\\n        config_file = temp_config_dir / \\\"lfx.toml\\\"\\n        config_file.write_text(\\n            \\\"\\\"\\\"\\n[services]\\nstorage_service = \\\"lfx.services.storage.local:LocalStorageService\\\"\\ntelemetry_service = \\\"lfx.services.telemetry.service:TelemetryService\\\"\\ntracing_service = \\\"lfx.services.tracing.service:TracingService\\\"\\nvariable_service = \\\"lfx.services.variable.service:VariableService\\\"\\n\\\"\\\"\\\"\\n        )\\n\\n        service_manager.discover_plugins(temp_config_dir)\\n\\n        # All services should be registered (4 from config + SESSION_SERVICE from fixture = 5)\\n        assert len(service_manager.service_classes) == 5\\n\\n        # Create and verify each service\\n        storage = service_manager.get(ServiceType.STORAGE_SERVICE)\\n        telemetry = service_manager.get(ServiceType.TELEMETRY_SERVICE)\\n        tracing = service_manager.get(ServiceType.TRACING_SERVICE)\\n        variables = service_manager.get(ServiceType.VARIABLE_SERVICE)\\n\\n        assert isinstance(storage, LocalStorageService)\\n        assert isinstance(telemetry, TelemetryService)\\n        assert isinstance(tracing, TracingService)\\n        assert isinstance(variables, VariableService)\\n\\n\\nclass _SpyService(Service):\\n    \\\"\\\"\\\"Minimal Service that records teardown and can be flipped to raise.\\\"\\\"\\\"\\n\\n    def __init__(self, name: str, *, fail: bool = False) -> None:\\n        super().__init__()\\n        self._name = name\\n        self._fail = fail\\n        self.torn_down = False\\n\\n    @property\\n    def name(self) -> str:\\n        return self._name\\n\\n    async def teardown(self) -> None:\\n        self.torn_down = True\\n        if self._fail:\\n            msg = f\\\"{self._name} teardown boom\\\"\\n            raise RuntimeError(msg)\\n\\n\\nclass TestServiceManagerTeardown:\\n    \\\"\\\"\\\"``teardown(raise_on_error=...)`` \u2014 strict mode for fork-safety-critical disposal.\\\"\\\"\\\"\\n\\n    async def test_best_effort_swallows_errors_by_default(self, service_manager):\\n        bad = _SpyService(\\\"bad_service\\\", fail=True)\\n        service_manager.services[ServiceType.TRACING_SERVICE] = bad\\n\\n        # Default best-effort: a failing teardown is logged, not raised.\\n        await service_manager.teardown()\\n\\n        assert bad.torn_down is True\\n        assert service_manager.services == {}\\n\\n    async def test_raise_on_error_propagates_after_attempting_all(self, service_manager):\\n        bad = _SpyService(\\\"bad_service\\\", fail=True)\\n        good = _SpyService(\\\"good_service\\\")\\n        service_manager.services[ServiceType.TRACING_SERVICE] = bad\\n        service_manager.services[ServiceType.CACHE_SERVICE] = good\\n\\n        with pytest.raises(RuntimeError, match=\\\"Service teardown failed\\\"):\\n            await service_manager.teardown(raise_on_error=True)\\n\\n        # Every service is still torn down before the error surfaces, and the table is cleared.\\n        assert bad.torn_down is True\\n        assert good.torn_down is True\\n        assert service_manager.services == {}\\n\\n    async def test_raise_on_error_is_quiet_when_all_succeed(self, service_manager):\\n        good = _SpyService(\\\"good_service\\\")\\n        service_manager.services[ServiceType.TRACING_SERVICE] = good\\n\\n        await service_manager.teardown(raise_on_error=True)  # no raise\\n\\n        assert good.torn_down is True\\n        assert service_manager.services == {}\\n\\n    async def test_service_without_teardown_is_skipped_not_failed(self, service_manager):\\n        \\\"\\\"\\\"A duck-typed service with no teardown holds nothing to dispose \u2014 not an error.\\n\\n        The in-memory caches and the Noop database/transaction services implement plain\\n        protocols rather than Service, so calling through would raise AttributeError and\\n        fail an otherwise clean fork-safety teardown.\\n        \\\"\\\"\\\"\\n        from lfx.services.shared_component_cache.service import SharedComponentCacheService\\n\\n        cache = SharedComponentCacheService()\\n        good = _SpyService(\\\"good_service\\\")\\n        service_manager.services[ServiceType.SHARED_COMPONENT_CACHE_SERVICE] = cache\\n        service_manager.services[ServiceType.TRACING_SERVICE] = good\\n\\n        await service_manager.teardown(raise_on_error=True)  # no raise\\n\\n        assert good.torn_down is True\\n        assert service_manager.services == {}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/test_check_components_frozen.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f52a58322194aea742cff870d7704b92ecd15ab1a1be6e73ee96fb048a1f25b8\",\"content\":\"\\\"\\\"\\\"Tests for ``scripts/ci/check_components_frozen.py``.\\n\\nThe bundle metapackage split (1.11) froze the top-level provider directories\\nunder ``src/lfx/src/lfx/components/``: no NEW in-tree provider directory may be\\nadded -- new providers go to ``lfx-bundles`` or a graduated ``lfx-<provider>``\\npackage. The CI gate is an additions-only check that fails when the live tree\\nholds a top-level directory (one shipping ``__init__.py``) absent from the\\ncommitted baseline, while allowing removals and ignoring package machinery.\\n\\nThese tests load the real script module and drive ``main()`` against synthetic\\ncomponent trees and baselines, so a regression in the gate's logic (e.g. the\\n``__init__.py`` requirement, the skip set, or baseline parsing) is caught\\nwithout running the CI job.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport importlib.util\\nimport sys\\nfrom pathlib import Path\\n\\nimport pytest\\n\\nREPO_ROOT = Path(__file__).resolve().parents[4]\\n_SCRIPT = REPO_ROOT / \\\"scripts\\\" / \\\"ci\\\" / \\\"check_components_frozen.py\\\"\\n\\n\\ndef _load_module():\\n    spec = importlib.util.spec_from_file_location(\\\"check_components_frozen\\\", _SCRIPT)\\n    module = importlib.util.module_from_spec(spec)\\n    sys.modules[\\\"check_components_frozen\\\"] = module\\n    spec.loader.exec_module(module)\\n    return module\\n\\n\\nmod = _load_module()\\n\\n\\ndef _make_provider(components_dir: Path, name: str) -> None:\\n    \\\"\\\"\\\"Create a top-level provider dir that ships an ``__init__.py``.\\\"\\\"\\\"\\n    provider = components_dir / name\\n    provider.mkdir(parents=True)\\n    (provider / \\\"__init__.py\\\").write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n\\n\\ndef _write_baseline(baseline_file: Path, names: list[str]) -> None:\\n    baseline_file.write_text(\\\"\\\\n\\\".join(names) + \\\"\\\\n\\\", encoding=\\\"utf-8\\\")\\n\\n\\n@pytest.fixture\\ndef gate(tmp_path: Path, monkeypatch: pytest.MonkeyPatch):\\n    \\\"\\\"\\\"Point the gate's module-level paths at a synthetic tree.\\\"\\\"\\\"\\n    components_dir = tmp_path / \\\"components\\\"\\n    components_dir.mkdir()\\n    baseline_file = tmp_path / \\\"frozen_component_dirs.txt\\\"\\n    monkeypatch.setattr(mod, \\\"COMPONENTS_DIR\\\", components_dir)\\n    monkeypatch.setattr(mod, \\\"BASELINE_FILE\\\", baseline_file)\\n    return components_dir, baseline_file\\n\\n\\ndef test_pass_when_all_dirs_in_baseline(gate):\\n    \\\"\\\"\\\"Every live provider dir is baselined -> gate passes (0).\\\"\\\"\\\"\\n    components_dir, baseline_file = gate\\n    _make_provider(components_dir, \\\"openai\\\")\\n    _make_provider(components_dir, \\\"anthropic\\\")\\n    _write_baseline(baseline_file, [\\\"openai\\\", \\\"anthropic\\\"])\\n\\n    assert mod.main() == 0\\n\\n\\ndef test_fail_when_new_dir_not_in_baseline(gate):\\n    \\\"\\\"\\\"A NEW provider dir with ``__init__.py`` absent from the baseline fails (1).\\\"\\\"\\\"\\n    components_dir, baseline_file = gate\\n    _make_provider(components_dir, \\\"openai\\\")\\n    _make_provider(components_dir, \\\"brandnew\\\")\\n    _write_baseline(baseline_file, [\\\"openai\\\"])\\n\\n    assert mod.main() == 1\\n\\n\\ndef test_pass_when_baseline_dir_removed(gate):\\n    \\\"\\\"\\\"A baselined dir absent on disk (removed) is allowed -> gate passes (0).\\\"\\\"\\\"\\n    components_dir, baseline_file = gate\\n    _make_provider(components_dir, \\\"openai\\\")\\n    _write_baseline(baseline_file, [\\\"openai\\\", \\\"removed_provider\\\"])\\n\\n    assert mod.main() == 0\\n\\n\\ndef test_ignores_dirs_without_init(gate):\\n    \\\"\\\"\\\"A new top-level dir lacking ``__init__.py`` does not trip the gate (0).\\\"\\\"\\\"\\n    components_dir, baseline_file = gate\\n    _make_provider(components_dir, \\\"openai\\\")\\n    # Stray directory with content but no __init__.py -> not a provider.\\n    stray = components_dir / \\\"stray_no_init\\\"\\n    stray.mkdir()\\n    (stray / \\\"notes.txt\\\").write_text(\\\"not a package\\\", encoding=\\\"utf-8\\\")\\n    _write_baseline(baseline_file, [\\\"openai\\\"])\\n\\n    assert mod.main() == 0\\n\\n\\ndef test_ignores_pycache_and_dotdirs(gate):\\n    \\\"\\\"\\\"``__pycache__`` and dotdirs are ignored even when not in the baseline (0).\\\"\\\"\\\"\\n    components_dir, baseline_file = gate\\n    _make_provider(components_dir, \\\"openai\\\")\\n    # __pycache__ even with an __init__.py present must be skipped by name.\\n    _make_provider(components_dir, \\\"__pycache__\\\")\\n    # A dotdir shipping an __init__.py must be skipped by the leading-dot rule.\\n    _make_provider(components_dir, \\\".hidden\\\")\\n    _write_baseline(baseline_file, [\\\"openai\\\"])\\n\\n    assert mod.main() == 0\\n\\n\\ndef test_baseline_ignores_blank_lines_and_comments(gate):\\n    \\\"\\\"\\\"Blank lines and ``#`` comments in the baseline are ignored when parsed.\\\"\\\"\\\"\\n    components_dir, baseline_file = gate\\n    _make_provider(components_dir, \\\"openai\\\")\\n    _make_provider(components_dir, \\\"anthropic\\\")\\n    baseline_file.write_text(\\n        \\\"# top-level provider directories (frozen)\\\\n\\\\nopenai\\\\n   \\\\n  # indented comment\\\\nanthropic\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    # Both live dirs are covered once comments/blanks are stripped.\\n    assert mod.main() == 0\\n\\n\\ndef test_real_tree_is_clean():\\n    \\\"\\\"\\\"The real component tree must be clean against the committed baseline (0).\\n\\n    Runs the unmonkeypatched script against the actual repo paths -- the gate's\\n    current state must be green, otherwise CI would already be red.\\n    \\\"\\\"\\\"\\n    assert mod.main() == 0\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/test_component_index.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"550ccfd1394db470f52bfc265e5fe32831c9827ad4f4418062e1607d233677c4\",\"content\":\"\\\"\\\"\\\"Unit tests for component index system.\\\"\\\"\\\"\\n\\nimport hashlib\\nfrom pathlib import Path\\nfrom unittest.mock import Mock, patch\\n\\nimport orjson\\nimport pytest\\nfrom lfx.interface.components import (\\n    _get_cache_path,\\n    _load_components_dynamically,\\n    _parse_dev_mode,\\n    _read_component_index,\\n    _save_generated_index,\\n    import_langflow_components,\\n)\\n\\n\\nclass TestParseDevMode:\\n    \\\"\\\"\\\"Tests for _parse_dev_mode() function.\\\"\\\"\\\"\\n\\n    def test_dev_mode_not_set(self, monkeypatch):\\n        \\\"\\\"\\\"Test default behavior when LFX_DEV is not set.\\\"\\\"\\\"\\n        monkeypatch.delenv(\\\"LFX_DEV\\\", raising=False)\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is False\\n        assert modules is None\\n\\n    def test_dev_mode_enabled_with_1(self, monkeypatch):\\n        \\\"\\\"\\\"Test dev mode enabled with LFX_DEV=1.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"1\\\")\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is True\\n        assert modules is None  # Load all modules\\n\\n    def test_dev_mode_enabled_with_true(self, monkeypatch):\\n        \\\"\\\"\\\"Test dev mode enabled with LFX_DEV=true.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"true\\\")\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is True\\n        assert modules is None\\n\\n    def test_dev_mode_enabled_with_yes(self, monkeypatch):\\n        \\\"\\\"\\\"Test dev mode enabled with LFX_DEV=yes.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"yes\\\")\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is True\\n        assert modules is None\\n\\n    def test_dev_mode_disabled_with_0(self, monkeypatch):\\n        \\\"\\\"\\\"Test dev mode disabled with LFX_DEV=0.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"0\\\")\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is False\\n        assert modules is None\\n\\n    def test_dev_mode_disabled_with_false(self, monkeypatch):\\n        \\\"\\\"\\\"Test dev mode disabled with LFX_DEV=false.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"false\\\")\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is False\\n        assert modules is None\\n\\n    def test_dev_mode_disabled_with_empty(self, monkeypatch):\\n        \\\"\\\"\\\"Test dev mode disabled with empty value.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"\\\")\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is False\\n        assert modules is None\\n\\n    def test_dev_mode_case_insensitive(self, monkeypatch):\\n        \\\"\\\"\\\"Test that env var is case insensitive.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"TRUE\\\")\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is True\\n        assert modules is None\\n\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"YES\\\")\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is True\\n        assert modules is None\\n\\n    def test_dev_mode_single_module(self, monkeypatch):\\n        \\\"\\\"\\\"Test dev mode with a single module filter.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"mistral\\\")\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is True\\n        assert modules == [\\\"mistral\\\"]\\n\\n    def test_dev_mode_multiple_modules(self, monkeypatch):\\n        \\\"\\\"\\\"Test dev mode with multiple module filters.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"mistral,openai,anthropic\\\")\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is True\\n        assert modules == [\\\"mistral\\\", \\\"openai\\\", \\\"anthropic\\\"]\\n\\n    def test_dev_mode_modules_with_spaces(self, monkeypatch):\\n        \\\"\\\"\\\"Test dev mode filters spaces correctly.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"mistral, openai , anthropic\\\")\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is True\\n        assert modules == [\\\"mistral\\\", \\\"openai\\\", \\\"anthropic\\\"]\\n\\n    def test_dev_mode_modules_case_normalized(self, monkeypatch):\\n        \\\"\\\"\\\"Test that module names are lowercased.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"Mistral,OpenAI\\\")\\n        enabled, modules = _parse_dev_mode()\\n        assert enabled is True\\n        assert modules == [\\\"mistral\\\", \\\"openai\\\"]\\n\\n\\nclass TestReadComponentIndex:\\n    \\\"\\\"\\\"Tests for _read_component_index() function.\\\"\\\"\\\"\\n\\n    def test_read_index_file_not_found(self):\\n        \\\"\\\"\\\"Test reading index when file doesn't exist.\\\"\\\"\\\"\\n        mock_path = Mock()\\n        mock_path.exists.return_value = False\\n\\n        with patch(\\\"lfx.interface.components.Path\\\") as mock_path_class:\\n            mock_path_class.return_value = mock_path\\n            result = _read_component_index()\\n\\n        assert result is None\\n\\n    def test_read_index_valid(self, tmp_path):\\n        \\\"\\\"\\\"Test reading valid index file.\\\"\\\"\\\"\\n        # Create valid index\\n        index = {\\n            \\\"version\\\": \\\"0.1.12\\\",\\n            \\\"entries\\\": [[\\\"category1\\\", {\\\"comp1\\\": {\\\"template\\\": {}}}]],\\n        }\\n        payload = orjson.dumps(index, option=orjson.OPT_SORT_KEYS)\\n        index[\\\"sha256\\\"] = hashlib.sha256(payload).hexdigest()\\n\\n        index_file = tmp_path / \\\"component_index.json\\\"\\n        index_file.write_bytes(orjson.dumps(index, option=orjson.OPT_SORT_KEYS | orjson.OPT_INDENT_2))\\n\\n        # Mock the path resolution\\n        with (\\n            patch(\\\"lfx.interface.components.inspect.getfile\\\") as mock_getfile,\\n            patch(\\\"importlib.metadata.version\\\") as mock_version,\\n        ):\\n            mock_getfile.return_value = str(tmp_path / \\\"lfx\\\" / \\\"__init__.py\\\")\\n            mock_version.return_value = \\\"0.1.12\\\"\\n\\n            # Create the directory structure\\n            (tmp_path / \\\"lfx\\\" / \\\"_assets\\\").mkdir(parents=True)\\n            (tmp_path / \\\"lfx\\\" / \\\"_assets\\\" / \\\"component_index.json\\\").write_bytes(\\n                orjson.dumps(index, option=orjson.OPT_SORT_KEYS | orjson.OPT_INDENT_2)\\n            )\\n\\n            result = _read_component_index()\\n\\n        assert result is not None\\n        assert result[\\\"version\\\"] == \\\"0.1.12\\\"\\n        assert \\\"entries\\\" in result\\n        assert result[\\\"sha256\\\"] == index[\\\"sha256\\\"]\\n\\n    def test_read_index_invalid_sha256(self, tmp_path):\\n        \\\"\\\"\\\"Test reading index with invalid SHA256.\\\"\\\"\\\"\\n        # Create index with bad hash\\n        index = {\\n            \\\"version\\\": \\\"0.1.12\\\",\\n            \\\"entries\\\": [[\\\"category1\\\", {\\\"comp1\\\": {\\\"template\\\": {}}}]],\\n            \\\"sha256\\\": \\\"invalid_hash\\\",\\n        }\\n\\n        index_file = tmp_path / \\\"component_index.json\\\"\\n        index_file.write_bytes(orjson.dumps(index))\\n\\n        with (\\n            patch(\\\"lfx.interface.components.inspect.getfile\\\") as mock_getfile,\\n            patch(\\\"importlib.metadata.version\\\") as mock_version,\\n        ):\\n            mock_getfile.return_value = str(tmp_path / \\\"lfx\\\" / \\\"__init__.py\\\")\\n            mock_version.return_value = \\\"0.1.12\\\"\\n\\n            (tmp_path / \\\"lfx\\\" / \\\"_assets\\\").mkdir(parents=True)\\n            (tmp_path / \\\"lfx\\\" / \\\"_assets\\\" / \\\"component_index.json\\\").write_bytes(orjson.dumps(index))\\n\\n            result = _read_component_index()\\n\\n        assert result is None\\n\\n    def test_read_index_version_mismatch(self, tmp_path):\\n        \\\"\\\"\\\"Test reading index with mismatched version.\\\"\\\"\\\"\\n        index = {\\n            \\\"version\\\": \\\"0.1.11\\\",\\n            \\\"entries\\\": [[\\\"category1\\\", {\\\"comp1\\\": {\\\"template\\\": {}}}]],\\n        }\\n        payload = orjson.dumps(index, option=orjson.OPT_SORT_KEYS)\\n        index[\\\"sha256\\\"] = hashlib.sha256(payload).hexdigest()\\n\\n        with (\\n            patch(\\\"lfx.interface.components.inspect.getfile\\\") as mock_getfile,\\n            patch(\\\"importlib.metadata.version\\\") as mock_version,\\n        ):\\n            mock_getfile.return_value = str(tmp_path / \\\"lfx\\\" / \\\"__init__.py\\\")\\n            mock_version.return_value = \\\"0.1.12\\\"  # Different version\\n\\n            (tmp_path / \\\"lfx\\\" / \\\"_assets\\\").mkdir(parents=True)\\n            (tmp_path / \\\"lfx\\\" / \\\"_assets\\\" / \\\"component_index.json\\\").write_bytes(\\n                orjson.dumps(index, option=orjson.OPT_SORT_KEYS | orjson.OPT_INDENT_2)\\n            )\\n\\n            result = _read_component_index()\\n\\n        assert result is None\\n\\n    def test_read_index_package_not_found(self, tmp_path):\\n        \\\"\\\"\\\"Test reading index when lfx package metadata is unavailable (e.g. Docker workspace install).\\\"\\\"\\\"\\n        from importlib.metadata import PackageNotFoundError\\n\\n        index = {\\n            \\\"version\\\": \\\"0.4.0\\\",\\n            \\\"entries\\\": [[\\\"category1\\\", {\\\"comp1\\\": {\\\"template\\\": {}}}]],\\n        }\\n        payload = orjson.dumps(index, option=orjson.OPT_SORT_KEYS)\\n        index[\\\"sha256\\\"] = hashlib.sha256(payload).hexdigest()\\n\\n        with (\\n            patch(\\\"lfx.interface.components.inspect.getfile\\\") as mock_getfile,\\n            patch(\\\"importlib.metadata.version\\\") as mock_version,\\n        ):\\n            mock_getfile.return_value = str(tmp_path / \\\"lfx\\\" / \\\"__init__.py\\\")\\n            mock_version.side_effect = PackageNotFoundError(\\\"lfx\\\")\\n\\n            (tmp_path / \\\"lfx\\\" / \\\"_assets\\\").mkdir(parents=True)\\n            (tmp_path / \\\"lfx\\\" / \\\"_assets\\\" / \\\"component_index.json\\\").write_bytes(\\n                orjson.dumps(index, option=orjson.OPT_SORT_KEYS | orjson.OPT_INDENT_2)\\n            )\\n\\n            result = _read_component_index()\\n\\n        # Should succeed - version check skipped when metadata unavailable\\n        assert result is not None\\n        assert result[\\\"version\\\"] == \\\"0.4.0\\\"\\n        assert \\\"entries\\\" in result\\n\\n    def test_read_index_custom_path_file(self, tmp_path):\\n        \\\"\\\"\\\"Test reading index from custom file path.\\\"\\\"\\\"\\n        index = {\\n            \\\"version\\\": \\\"0.1.12\\\",\\n            \\\"entries\\\": [[\\\"category1\\\", {\\\"comp1\\\": {\\\"template\\\": {}}}]],\\n        }\\n        payload = orjson.dumps(index, option=orjson.OPT_SORT_KEYS)\\n        index[\\\"sha256\\\"] = hashlib.sha256(payload).hexdigest()\\n\\n        custom_file = tmp_path / \\\"custom_index.json\\\"\\n        custom_file.write_bytes(orjson.dumps(index, option=orjson.OPT_SORT_KEYS | orjson.OPT_INDENT_2))\\n\\n        with patch(\\\"importlib.metadata.version\\\") as mock_version:\\n            mock_version.return_value = \\\"0.1.12\\\"\\n            result = _read_component_index(str(custom_file))\\n\\n        assert result is not None\\n        assert result[\\\"version\\\"] == \\\"0.1.12\\\"\\n\\n    def test_read_index_custom_path_url(self):\\n        \\\"\\\"\\\"Test reading index from URL.\\\"\\\"\\\"\\n        index = {\\n            \\\"version\\\": \\\"0.1.12\\\",\\n            \\\"entries\\\": [[\\\"category1\\\", {\\\"comp1\\\": {\\\"template\\\": {}}}]],\\n        }\\n        payload = orjson.dumps(index, option=orjson.OPT_SORT_KEYS)\\n        index[\\\"sha256\\\"] = hashlib.sha256(payload).hexdigest()\\n\\n        mock_response = Mock()\\n        mock_response.content = orjson.dumps(index)\\n\\n        with (\\n            patch(\\\"httpx.get\\\", return_value=mock_response),\\n            patch(\\\"importlib.metadata.version\\\", return_value=\\\"0.1.12\\\"),\\n        ):\\n            result = _read_component_index(\\\"https://example.com/index.json\\\")\\n\\n        assert result is not None\\n        assert result[\\\"version\\\"] == \\\"0.1.12\\\"\\n\\n\\nclass TestCachePath:\\n    \\\"\\\"\\\"Tests for cache path functionality.\\\"\\\"\\\"\\n\\n    def test_get_cache_path_returns_path(self):\\n        \\\"\\\"\\\"Test that _get_cache_path returns a Path object.\\\"\\\"\\\"\\n        result = _get_cache_path()\\n        assert isinstance(result, Path)\\n        assert result.name == \\\"component_index.json\\\"\\n        assert \\\"lfx\\\" in str(result)\\n\\n\\nclass TestSaveGeneratedIndex:\\n    \\\"\\\"\\\"Tests for _save_generated_index() function.\\\"\\\"\\\"\\n\\n    def test_save_generated_index(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Test saving generated index to cache.\\\"\\\"\\\"\\n        modules_dict = {\\n            \\\"category1\\\": {\\\"comp1\\\": {\\\"template\\\": {}, \\\"display_name\\\": \\\"Component 1\\\"}},\\n            \\\"category2\\\": {\\\"comp2\\\": {\\\"template\\\": {}, \\\"display_name\\\": \\\"Component 2\\\"}},\\n        }\\n\\n        cache_file = tmp_path / \\\"component_index.json\\\"\\n        monkeypatch.setattr(\\\"lfx.interface.components._get_cache_path\\\", lambda: cache_file)\\n\\n        with patch(\\\"importlib.metadata.version\\\", return_value=\\\"0.1.12\\\") as mock_version:\\n            _save_generated_index(modules_dict)\\n\\n        assert cache_file.exists()\\n        saved_index = orjson.loads(cache_file.read_bytes())\\n\\n        assert saved_index[\\\"version\\\"] == \\\"0.1.12\\\"\\n        assert \\\"entries\\\" in saved_index\\n        assert \\\"sha256\\\" in saved_index\\n        assert len(saved_index[\\\"entries\\\"]) == 2\\n        mock_version.assert_called_once_with(\\\"lfx\\\")\\n\\n    def test_save_generated_index_empty_dict(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Test saving empty modules dict.\\\"\\\"\\\"\\n        cache_file = tmp_path / \\\"component_index.json\\\"\\n        monkeypatch.setattr(\\\"lfx.interface.components._get_cache_path\\\", lambda: cache_file)\\n\\n        with patch(\\\"importlib.metadata.version\\\", return_value=\\\"0.1.12\\\"):\\n            _save_generated_index({})\\n\\n        assert cache_file.exists()\\n        saved_index = orjson.loads(cache_file.read_bytes())\\n        assert len(saved_index[\\\"entries\\\"]) == 0\\n\\n\\n@pytest.mark.asyncio\\nclass TestImportLangflowComponents:\\n    \\\"\\\"\\\"Tests for import_langflow_components() async function.\\\"\\\"\\\"\\n\\n    async def test_import_with_dev_mode(self, monkeypatch):\\n        \\\"\\\"\\\"Test import in dev mode (dynamic loading).\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"1\\\")\\n\\n        with patch(\\\"lfx.interface.components._process_single_module\\\") as mock_process:\\n            mock_process.return_value = (\\\"category1\\\", {\\\"comp1\\\": {\\\"template\\\": {}}})\\n\\n            with (\\n                patch(\\\"lfx.interface.components.pkgutil.walk_packages\\\") as mock_walk,\\n                patch(\\\"lfx.interface.components._save_generated_index\\\") as mock_save,\\n            ):\\n                mock_walk.return_value = [\\n                    (None, \\\"lfx.components.category1\\\", False),\\n                ]\\n\\n                result = await import_langflow_components()\\n\\n        assert \\\"components\\\" in result\\n        assert \\\"category1\\\" in result[\\\"components\\\"]\\n        # In dev mode, we don't save to cache\\n        assert not mock_save.called\\n\\n    async def test_dynamic_import_supports_serial_processing(self):\\n        \\\"\\\"\\\"Index generation can process modules serially to avoid import races.\\\"\\\"\\\"\\n        module_names = [\\n            (None, \\\"lfx.components.category1.first\\\", False),\\n            (None, \\\"lfx.components.category1.second\\\", False),\\n        ]\\n\\n        with (\\n            patch(\\\"lfx.interface.components.pkgutil.walk_packages\\\", return_value=module_names),\\n            patch(\\n                \\\"lfx.interface.components._process_single_module\\\",\\n                side_effect=[\\n                    (\\\"category1\\\", {\\\"first\\\": {\\\"template\\\": {}}}),\\n                    (\\\"category1\\\", {\\\"second\\\": {\\\"template\\\": {}}}),\\n                ],\\n            ) as mock_process,\\n            patch(\\\"lfx.interface.components.asyncio.to_thread\\\") as mock_to_thread,\\n        ):\\n            result = await _load_components_dynamically(parallel=False)\\n\\n        assert result == {\\n            \\\"category1\\\": {\\n                \\\"first\\\": {\\\"template\\\": {}},\\n                \\\"second\\\": {\\\"template\\\": {}},\\n            }\\n        }\\n        assert [call.args[0] for call in mock_process.call_args_list] == [\\n            \\\"lfx.components.category1.first\\\",\\n            \\\"lfx.components.category1.second\\\",\\n        ]\\n        mock_to_thread.assert_not_called()\\n\\n    async def test_import_with_builtin_index(self, monkeypatch):\\n        \\\"\\\"\\\"Test import with valid built-in index.\\\"\\\"\\\"\\n        monkeypatch.delenv(\\\"LFX_DEV\\\", raising=False)\\n\\n        index = {\\n            \\\"version\\\": \\\"0.1.12\\\",\\n            \\\"entries\\\": [[\\\"category1\\\", {\\\"comp1\\\": {\\\"template\\\": {}}}]],\\n        }\\n        payload = orjson.dumps(index, option=orjson.OPT_SORT_KEYS)\\n        index[\\\"sha256\\\"] = hashlib.sha256(payload).hexdigest()\\n\\n        with (\\n            patch(\\\"lfx.interface.components._read_component_index\\\") as mock_read,\\n            patch(\\\"importlib.metadata.version\\\", return_value=\\\"0.1.12\\\"),\\n        ):\\n            mock_read.return_value = index\\n\\n            result = await import_langflow_components()\\n\\n        assert \\\"components\\\" in result\\n        assert \\\"category1\\\" in result[\\\"components\\\"]\\n        assert \\\"comp1\\\" in result[\\\"components\\\"][\\\"category1\\\"]\\n\\n    async def test_import_with_missing_index_creates_cache(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Test import with missing index falls back to dynamic and caches.\\\"\\\"\\\"\\n        monkeypatch.delenv(\\\"LFX_DEV\\\", raising=False)\\n        cache_file = tmp_path / \\\"component_index.json\\\"\\n        monkeypatch.setattr(\\\"lfx.interface.components._get_cache_path\\\", lambda: cache_file)\\n\\n        with (\\n            patch(\\\"lfx.interface.components._read_component_index\\\") as mock_read,\\n            patch(\\\"lfx.interface.components._process_single_module\\\") as mock_process,\\n            patch(\\\"lfx.interface.components.pkgutil.walk_packages\\\") as mock_walk,\\n            patch(\\\"importlib.metadata.version\\\", return_value=\\\"0.1.12\\\"),\\n        ):\\n            # Simulate missing built-in index and cache\\n            mock_read.return_value = None\\n            mock_process.return_value = (\\\"category1\\\", {\\\"comp1\\\": {\\\"template\\\": {}}})\\n            mock_walk.return_value = [(None, \\\"lfx.components.category1\\\", False)]\\n\\n            result = await import_langflow_components()\\n\\n        assert \\\"components\\\" in result\\n        assert cache_file.exists()\\n\\n    async def test_import_with_custom_path_from_settings(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Test import with custom index path from settings.\\\"\\\"\\\"\\n        monkeypatch.delenv(\\\"LFX_DEV\\\", raising=False)\\n\\n        index = {\\n            \\\"version\\\": \\\"0.1.12\\\",\\n            \\\"entries\\\": [[\\\"category1\\\", {\\\"comp1\\\": {\\\"template\\\": {}}}]],\\n        }\\n        payload = orjson.dumps(index, option=orjson.OPT_SORT_KEYS)\\n        index[\\\"sha256\\\"] = hashlib.sha256(payload).hexdigest()\\n\\n        custom_file = tmp_path / \\\"custom_index.json\\\"\\n        custom_file.write_bytes(orjson.dumps(index))\\n\\n        mock_settings = Mock()\\n        mock_settings.settings.components_index_path = str(custom_file)\\n\\n        with (\\n            patch(\\\"lfx.interface.components._read_component_index\\\") as mock_read,\\n            patch(\\\"importlib.metadata.version\\\", return_value=\\\"0.1.12\\\"),\\n        ):\\n            mock_read.return_value = index\\n\\n            result = await import_langflow_components(mock_settings)\\n\\n        assert \\\"components\\\" in result\\n        # Verify custom path was used\\n        mock_read.assert_called_with(str(custom_file))\\n\\n    async def test_import_handles_import_errors(self, monkeypatch):\\n        \\\"\\\"\\\"Test import handles component import errors gracefully.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LFX_DEV\\\", \\\"1\\\")\\n\\n        with (\\n            patch(\\\"lfx.interface.components._process_single_module\\\") as mock_process,\\n            patch(\\\"lfx.interface.components.pkgutil.walk_packages\\\") as mock_walk,\\n        ):\\n            # Simulate an import error\\n            mock_process.side_effect = ImportError(\\\"Failed to import\\\")\\n            mock_walk.return_value = [(None, \\\"lfx.components.broken\\\", False)]\\n\\n            result = await import_langflow_components()\\n\\n        # Should return empty dict, not raise\\n        assert \\\"components\\\" in result\\n        assert len(result[\\\"components\\\"]) == 0\\n\\n\\nclass TestToolOutputCapabilitySerialization:\\n    \\\"\\\"\\\"``add_tool_output`` must survive into the serialized template.\\n\\n    It is half of ``Component._handle_tool_mode``, the runtime authority for\\n    whether a component can produce a ``component_as_tool`` output. Consumers\\n    that only see a template (the flow builder, the MCP registry) cannot state\\n    that rule unless the flag is serialized, and the alternative signal they\\n    reached for \u2014 ``tool_mode`` on outputs \u2014 is set by nearly every component.\\n    \\\"\\\"\\\"\\n\\n    def _frontend_node(self, **attrs):\\n        from lfx.custom.custom_component.base_component import BaseComponent\\n        from lfx.template.frontend_node.custom_components import ComponentFrontendNode\\n\\n        component = type(\\\"StubComponent\\\", (), {\\\"inputs\\\": [], \\\"outputs\\\": [], **attrs})()\\n        config = BaseComponent.get_template_config(component)\\n        return ComponentFrontendNode.from_inputs(**config, base_classes=[]).to_dict(keep_name=False)\\n\\n    def test_enabled_capability_is_serialized(self):\\n        assert self._frontend_node(add_tool_output=True)[\\\"add_tool_output\\\"] is True\\n\\n    def test_disabled_capability_is_omitted(self):\\n        \\\"\\\"\\\"The default must not bloat every template with a false flag.\\\"\\\"\\\"\\n        assert \\\"add_tool_output\\\" not in self._frontend_node(add_tool_output=False)\\n\\n    def test_bundled_index_carries_runtime_capabilities(self):\\n        index_path = Path(__file__).parents[2] / \\\"src\\\" / \\\"lfx\\\" / \\\"_assets\\\" / \\\"component_index.json\\\"\\n        index = orjson.loads(index_path.read_bytes())\\n        components = {name: tmpl for _category, entries in index[\\\"entries\\\"] for name, tmpl in entries.items()}\\n\\n        # RunFlow has no tool_mode input; add_tool_output is its only signal.\\n        assert components[\\\"RunFlow\\\"][\\\"add_tool_output\\\"] is True\\n        # CSVAgent redeclares LCAgentComponent's input_value, which shadows the\\n        # base input's tool_mode in the name-keyed template.\\n        assert components[\\\"CSVAgent\\\"][\\\"template\\\"][\\\"input_value\\\"][\\\"tool_mode\\\"] is True\\n        # ChatInput has neither, yet its message output carries tool_mode.\\n        assert \\\"add_tool_output\\\" not in components[\\\"ChatInput\\\"]\\n        assert any(o.get(\\\"tool_mode\\\") for o in components[\\\"ChatInput\\\"][\\\"outputs\\\"])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/test_data_class.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8dcea60d22df0831f08c9a869fde096d65a3d771b93f2ba3d45920b4ed00577d\",\"content\":\"import copy\\n\\nimport pytest\\nfrom langchain_core.documents import Document\\nfrom lfx.schema import Data\\n\\n\\ndef test_data_initialization():\\n    record = Data(text_key=\\\"msg\\\", data={\\\"msg\\\": \\\"Hello, World!\\\", \\\"extra\\\": \\\"value\\\"})\\n    assert record.msg == \\\"Hello, World!\\\"\\n    assert record.extra == \\\"value\\\"\\n\\n\\ndef test_validate_data_with_extra_keys():\\n    record = Data(dummy_key=\\\"dummy\\\", data={\\\"key\\\": \\\"value\\\"})\\n    assert record.data[\\\"dummy_key\\\"] == \\\"dummy\\\"\\n    assert \\\"dummy_key\\\" in record.data\\n    assert record.key == \\\"value\\\"\\n\\n\\ndef test_conversion_to_document():\\n    record = Data(data={\\\"text\\\": \\\"Sample text\\\", \\\"meta\\\": \\\"data\\\"})\\n    document = record.to_lc_document()\\n    assert document.page_content == \\\"Sample text\\\"\\n    assert document.metadata == {\\\"meta\\\": \\\"data\\\"}\\n\\n\\ndef test_conversion_from_document():\\n    document = Document(page_content=\\\"Doc content\\\", metadata={\\\"meta\\\": \\\"info\\\"})\\n    record = Data.from_document(document)\\n    assert record.text == \\\"Doc content\\\"\\n    assert record.meta == \\\"info\\\"\\n\\n\\ndef test_add_method_for_strings():\\n    record1 = Data(data={\\\"text\\\": \\\"Hello\\\"})\\n    record2 = Data(data={\\\"text\\\": \\\" World\\\"})\\n    combined = record1 + record2\\n    assert combined.text == \\\"Hello World\\\"\\n\\n\\ndef test_add_method_for_integers():\\n    record1 = Data(data={\\\"number\\\": 5})\\n    record2 = Data(data={\\\"number\\\": 10})\\n    combined = record1 + record2\\n    expected_number = 15\\n    assert combined.number == expected_number\\n\\n\\ndef test_add_method_with_non_overlapping_keys():\\n    record1 = Data(data={\\\"text\\\": \\\"Hello\\\"})\\n    record2 = Data(data={\\\"number\\\": 10})\\n    combined = record1 + record2\\n    assert combined.text == \\\"Hello\\\"\\n    expected_number = 10\\n    assert combined.number == expected_number\\n\\n\\ndef test_custom_attribute_get_set_del():\\n    record = Data()\\n    record.custom_attr = \\\"custom_value\\\"\\n    assert record.custom_attr == \\\"custom_value\\\"\\n    del record.custom_attr\\n    with pytest.raises(AttributeError):\\n        _ = record.custom_attr\\n\\n\\ndef test_deep_copy():\\n    record1 = Data(data={\\\"text\\\": \\\"Hello\\\", \\\"number\\\": 10})\\n    record2 = copy.deepcopy(record1)\\n    assert record2.text == \\\"Hello\\\"\\n    expected_number = 10\\n    assert record2.number == expected_number\\n    record2.text = \\\"World\\\"\\n    assert record1.text == \\\"Hello\\\"  # Ensure original is unchanged\\n\\n\\ndef test_custom_attribute_setting_and_getting():\\n    record = Data()\\n    record.dynamic_attribute = \\\"Dynamic Value\\\"\\n    assert record.dynamic_attribute == \\\"Dynamic Value\\\"\\n\\n\\ndef test_str_and_dir_methods():\\n    record = Data(text_key=\\\"text\\\", data={\\\"text\\\": \\\"Test Text\\\", \\\"key\\\": \\\"value\\\"})\\n    assert \\\"Test Text\\\" in str(record)\\n    assert \\\"key\\\" in dir(record)\\n    assert \\\"data\\\" in dir(record)\\n\\n\\ndef test_dir_includes_data_keys():\\n    record = Data(data={\\\"text\\\": \\\"Hello\\\", \\\"new_attr\\\": \\\"value\\\"})\\n    dir_output = dir(record)\\n\\n    # Check for standard attributes\\n    assert \\\"data\\\" in dir_output\\n    assert \\\"text_key\\\" in dir_output\\n    assert \\\"__add__\\\" in dir_output  # Checking for a method\\n\\n    # Check for dynamic attributes from data\\n    assert \\\"text\\\" in dir_output\\n    assert \\\"new_attr\\\" in dir_output\\n\\n    # Optionally, verify that dynamically added attributes are listed\\n    record.dynamic_attr = \\\"dynamic\\\"\\n    assert \\\"dynamic_attr\\\" in dir_output or \\\"dynamic_attr\\\" in dir(record)  # To account for the change\\n\\n\\ndef test_dir_reflects_attribute_deletion():\\n    record = Data(data={\\\"removable\\\": \\\"I can be removed\\\"})\\n    assert \\\"removable\\\" in dir(record)\\n\\n    # Delete the attribute and check again\\n    del record.removable\\n    assert \\\"removable\\\" not in dir(record)\\n\\n\\ndef test_get_text_with_text_key():\\n    data = {\\\"text\\\": \\\"Hello, World!\\\"}\\n    schema = Data(data=data, text_key=\\\"text\\\", default_value=\\\"default\\\")\\n    result = schema.get_text()\\n    assert result == \\\"Hello, World!\\\"\\n\\n\\ndef test_get_text_without_text_key():\\n    data = {\\\"other_key\\\": \\\"Hello, World!\\\"}\\n    schema = Data(data=data, text_key=\\\"text\\\", default_value=\\\"default\\\")\\n    result = schema.get_text()\\n    assert result == \\\"default\\\"\\n\\n\\ndef test_get_text_with_empty_data():\\n    data = {}\\n    schema = Data(data=data, text_key=\\\"text\\\", default_value=\\\"default\\\")\\n    result = schema.get_text()\\n    assert result == \\\"default\\\"\\n\\n\\ndef test_get_text_with_none_data():\\n    data = None\\n    schema = Data(data=data, text_key=\\\"text\\\", default_value=\\\"default\\\")\\n    result = schema.get_text()\\n    assert result == \\\"default\\\"\\n    assert schema.data == {}\\n\\n\\ndef test_data_concatenation_different_fields():\\n    record1 = Data(data={\\\"text\\\": \\\"Hello\\\"})\\n    record2 = Data(data={\\\"number\\\": 10})\\n    combined = record1 + record2\\n    assert combined.text == \\\"Hello\\\"\\n    expected_number = 10\\n    assert combined.number == expected_number\\n\\n\\ndef test_data_copy():\\n    record1 = Data(data={\\\"text\\\": \\\"Hello\\\", \\\"number\\\": 10})\\n    record2 = copy.deepcopy(record1)\\n    assert record2.text == \\\"Hello\\\"\\n    expected_number = 10\\n    assert record2.number == expected_number\\n    record2.text = \\\"World\\\"\\n    assert record1.text == \\\"Hello\\\"  # Ensure original is unchanged\\n    assert record2.text == \\\"World\\\"\\n\\n\\ndef test_data_field_access():\\n    record = Data()\\n    record.name = \\\"John\\\"\\n    assert \\\"name\\\" in record.data\\n    assert record.data[\\\"name\\\"] == \\\"John\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/test_db_span_path_redaction.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4d6b6139c6f205cf7594a93ee623df8f04e16a859d6cb0db5941c727b1ddb40d\",\"content\":\"\\\"\\\"\\\"A SQLite database path must not leave the process as a span name.\\n\\nSQLAlchemy's instrumentation sets ``db.name`` from the database name, and for SQLite that name\\nis the file path. It builds ``db.operation`` and the span name as ``\\\"<operation> <db.name>\\\"``,\\nso without this the operator's APM shows spans named\\n``SELECT /home/alice/langflow/langflow.db``. SQLite is the default database, so that is the\\ndefault configuration rather than an edge case.\\n\\nThe file name is kept rather than dropped, because someone running more than one SQLite\\ndatabase still has to tell them apart.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport subprocess\\nimport sys\\nimport tempfile\\nfrom pathlib import Path\\n\\nimport pytest\\n\\npytest.importorskip(\\\"opentelemetry.sdk.trace.export.in_memory_span_exporter\\\")\\n\\nfrom lfx.observability import ApplicationOnlySpanProcessor, _shorten_db_path\\n\\n# A directory that gives away the account name, which is the part of a real path worth not\\n# sending. The file name is the part that survives.\\nDB_PATH = \\\"/home/alice/deployments/langflow-prod/langflow.db\\\"\\nDB_FILE = \\\"langflow.db\\\"\\n\\n\\ndef export(name: str, attributes: dict):\\n    \\\"\\\"\\\"Push one span through the processor and return it as the exporter received it.\\\"\\\"\\\"\\n    from opentelemetry.sdk.trace import TracerProvider\\n    from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\n    exporter = InMemorySpanExporter()\\n    provider = TracerProvider()\\n    provider.add_span_processor(ApplicationOnlySpanProcessor(exporter))\\n    try:\\n        span = provider.get_tracer(\\\"opentelemetry.instrumentation.sqlalchemy\\\").start_span(name)\\n        for key, value in attributes.items():\\n            span.set_attribute(key, value)\\n        span.end()\\n        provider.force_flush()\\n        finished = exporter.get_finished_spans()\\n        assert len(finished) == 1, finished\\n        return finished[0]\\n    finally:\\n        provider.shutdown()\\n\\n\\ndef test_the_span_name_carries_the_file_name_not_the_path():\\n    span = export(\\n        f\\\"SELECT {DB_PATH}\\\",\\n        {\\\"db.system\\\": \\\"sqlite\\\", \\\"db.name\\\": DB_PATH, \\\"db.operation\\\": f\\\"SELECT {DB_PATH}\\\"},\\n    )\\n\\n    assert span.name == f\\\"SELECT {DB_FILE}\\\"\\n    assert span.attributes[\\\"db.name\\\"] == DB_FILE\\n    assert span.attributes[\\\"db.operation\\\"] == f\\\"SELECT {DB_FILE}\\\"\\n\\n\\ndef test_no_part_of_the_directory_survives_anywhere_on_the_span():\\n    \\\"\\\"\\\"Serialise the whole span, because the path could hide on an attribute not asserted above.\\\"\\\"\\\"\\n    span = export(\\n        f\\\"SELECT {DB_PATH}\\\",\\n        {\\\"db.system\\\": \\\"sqlite\\\", \\\"db.name\\\": DB_PATH, \\\"db.operation\\\": f\\\"SELECT {DB_PATH}\\\"},\\n    )\\n    dumped = json.dumps({\\\"name\\\": span.name, \\\"attributes\\\": dict(span.attributes)})\\n\\n    assert \\\"alice\\\" not in dumped, dumped\\n    assert \\\"/home\\\" not in dumped, dumped\\n    assert DB_FILE in dumped, \\\"the file name should survive; only the directory is dropped\\\"\\n\\n\\ndef test_other_attributes_are_untouched():\\n    span = export(\\n        f\\\"SELECT {DB_PATH}\\\",\\n        {\\n            \\\"db.system\\\": \\\"sqlite\\\",\\n            \\\"db.name\\\": DB_PATH,\\n            \\\"db.operation\\\": f\\\"SELECT {DB_PATH}\\\",\\n            \\\"db.statement\\\": \\\"SELECT flow.name FROM flow WHERE flow.id = ?\\\",\\n        },\\n    )\\n\\n    assert span.attributes[\\\"db.system\\\"] == \\\"sqlite\\\"\\n    assert span.attributes[\\\"db.statement\\\"] == \\\"SELECT flow.name FROM flow WHERE flow.id = ?\\\"\\n\\n\\ndef test_a_postgres_name_containing_a_separator_is_left_alone():\\n    \\\"\\\"\\\"The gate is db.system, not the shape of the value.\\n\\n    A separator is legal inside a Postgres database name. Shortening one would silently\\n    rename a logical database in the operator's dashboards, which is a worse bug than the\\n    leak this function exists to fix.\\n    \\\"\\\"\\\"\\n    span = export(\\n        \\\"SELECT tenant/archive\\\",\\n        {\\\"db.system\\\": \\\"postgresql\\\", \\\"db.name\\\": \\\"tenant/archive\\\", \\\"db.operation\\\": \\\"SELECT tenant/archive\\\"},\\n    )\\n\\n    assert span.name == \\\"SELECT tenant/archive\\\"\\n    assert span.attributes[\\\"db.name\\\"] == \\\"tenant/archive\\\"\\n\\n\\ndef test_a_path_without_a_sqlite_system_is_left_alone():\\n    \\\"\\\"\\\"No db.system means no evidence it is a file, so nothing is assumed.\\\"\\\"\\\"\\n    span = export(f\\\"SELECT {DB_PATH}\\\", {\\\"db.name\\\": DB_PATH})\\n\\n    assert span.attributes[\\\"db.name\\\"] == DB_PATH\\n\\n\\ndef test_a_logical_database_name_is_left_alone():\\n    \\\"\\\"\\\"Postgres and MySQL report a name with no separator, so nothing should change.\\\"\\\"\\\"\\n    span = export(\\n        \\\"SELECT langflow\\\", {\\\"db.system\\\": \\\"postgresql\\\", \\\"db.name\\\": \\\"langflow\\\", \\\"db.operation\\\": \\\"SELECT langflow\\\"}\\n    )\\n\\n    assert span.name == \\\"SELECT langflow\\\"\\n    assert span.attributes[\\\"db.name\\\"] == \\\"langflow\\\"\\n\\n\\ndef test_a_windows_path_is_shortened_too():\\n    \\\"\\\"\\\"The exporting host and the host that wrote the path need not be the same platform.\\\"\\\"\\\"\\n    windows_path = r\\\"C:\\\\\\\\Users\\\\\\\\alice\\\\\\\\langflow\\\\\\\\langflow.db\\\"\\n    span = export(f\\\"SELECT {windows_path}\\\", {\\\"db.system\\\": \\\"sqlite\\\", \\\"db.name\\\": windows_path})\\n\\n    assert span.attributes[\\\"db.name\\\"] == DB_FILE\\n    assert \\\"alice\\\" not in span.name, span.name\\n\\n\\ndef test_a_span_with_no_db_name_is_unchanged():\\n    span = export(\\\"flow.execute\\\", {\\\"flow_id\\\": \\\"abc\\\", \\\"status\\\": \\\"ok\\\"})\\n\\n    assert span.name == \\\"flow.execute\\\"\\n    assert span.attributes[\\\"flow_id\\\"] == \\\"abc\\\"\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"value\\\", \\\"expected\\\"),\\n    [\\n        (\\\"/a/b/c.db\\\", \\\"c.db\\\"),\\n        (\\\"c.db\\\", \\\"c.db\\\"),\\n        (\\\"langflow\\\", \\\"langflow\\\"),\\n        (\\\":memory:\\\", \\\":memory:\\\"),\\n        (\\\"\\\", \\\"\\\"),\\n        (\\\"/\\\", \\\"\\\"),\\n        (\\\"relative/path/x.db\\\", \\\"x.db\\\"),\\n    ],\\n)\\ndef test_shorten_db_path(value, expected):\\n    assert _shorten_db_path(value) == expected\\n\\n\\n# The end-to-end half. A real SQLite engine and the real instrumentor, in a subprocess because\\n# SQLAlchemyInstrumentor patches globally and the tracer provider is process-wide.\\n\\nPROBE = \\\"\\\"\\\"\\nimport json, os, tempfile\\n\\nfrom opentelemetry import trace\\nfrom opentelemetry.sdk.trace import TracerProvider\\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\nfrom lfx.observability import ApplicationOnlySpanProcessor, instrument_database\\n\\nexporter = InMemorySpanExporter()\\nprovider = TracerProvider()\\nprovider.add_span_processor(ApplicationOnlySpanProcessor(exporter))\\ntrace.set_tracer_provider(provider)\\n\\nimport sqlalchemy as sa\\n\\n# A real file, in a directory whose name is the thing that must not be exported.\\nroot = tempfile.mkdtemp(prefix=\\\"SENTINELDIRQQQ-\\\")\\ndb_file = os.path.join(root, \\\"langflow.db\\\")\\nengine = sa.create_engine(\\\"sqlite:///\\\" + db_file)\\ninstrument_database(engine)\\n\\nwith engine.connect() as conn:\\n    conn.execute(sa.text(\\\"SELECT 1\\\"))\\n\\nprovider.force_flush()\\nspans = [\\n    {\\\"name\\\": s.name, \\\"attributes\\\": {k: str(v) for k, v in (s.attributes or {}).items()}}\\n    for s in exporter.get_finished_spans()\\n]\\nprint(\\\"PROBE_RESULT \\\" + json.dumps({\\\"root\\\": root, \\\"db_file\\\": db_file, \\\"spans\\\": spans}))\\n\\\"\\\"\\\"\\n\\n\\ndef run_probe() -> dict:\\n    import os\\n\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    with tempfile.TemporaryDirectory() as tmp:\\n        probe = Path(tmp) / \\\"probe.py\\\"\\n        probe.write_text(PROBE, encoding=\\\"utf-8\\\")\\n        completed = subprocess.run(  # noqa: S603\\n            [sys.executable, str(probe)], env=env, capture_output=True, text=True, timeout=300, check=False\\n        )\\n    assert completed.returncode == 0, completed.stderr\\n    lines = [ln for ln in completed.stdout.splitlines() if ln.startswith(\\\"PROBE_RESULT \\\")]\\n    assert lines, f\\\"probe printed no result.\\\\nstdout:\\\\n{completed.stdout}\\\\nstderr:\\\\n{completed.stderr}\\\"\\n    return json.loads(lines[0].removeprefix(\\\"PROBE_RESULT \\\"))\\n\\n\\ndef test_a_real_query_exports_no_host_path():\\n    \\\"\\\"\\\"The regression this file exists for, against the real instrumentor rather than a stub.\\\"\\\"\\\"\\n    result = run_probe()\\n    dumped = json.dumps(result[\\\"spans\\\"])\\n\\n    # Asserted before the absence: if the probe produced no database spans at all, \\\"the path is\\n    # not here\\\" would pass while proving nothing.\\n    assert any(s[\\\"attributes\\\"].get(\\\"db.system\\\") == \\\"sqlite\\\" for s in result[\\\"spans\\\"]), result\\n\\n    assert \\\"SENTINELDIRQQQ\\\" not in dumped, dumped\\n    assert result[\\\"root\\\"] not in dumped, dumped\\n    assert \\\"langflow.db\\\" in dumped, \\\"the file name should survive\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/test_db_span_toggle.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"767c0a69bd0791038724ac07b058aec648c18505a70ab4e708cf31bfb9a03d81\",\"content\":\"\\\"\\\"\\\"Database spans are the bulk of the export, so an operator can turn them off.\\n\\nMeasured against a live run: database spans were about 80% of everything exported, roughly\\n50 spans per flow run against a single ``flow.execute``. A commercial APM bills per span\\ningested, so an operator who only wants flow and request health should not have to pay for\\nthe rest of it.\\n\\nThey stay on by default because the volume buys something. In that same run 17% of pool\\ncheckouts took over 50ms and 4% took over 200ms, which is the difference between knowing a\\nflow was slow and knowing it was slow waiting for the database.\\n\\nThe property that matters most here is not the toggle. It is that the toggle can only ever\\n*subtract* from the allowlist, because the allowlist is what keeps prompt-carrying scopes out\\nof the APM. Configuration that could widen it would be an env var that reopens the leak.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport subprocess\\nimport sys\\nimport tempfile\\nfrom pathlib import Path\\n\\nimport pytest\\n\\npytest.importorskip(\\\"opentelemetry.sdk.trace.export.in_memory_span_exporter\\\")\\n\\nfrom lfx.observability import (\\n    APPLICATION_INSTRUMENTATION_SCOPES,\\n    APPLICATION_TRACER_NAME,\\n    DB_INSTRUMENTATION_SCOPE,\\n    ApplicationOnlySpanProcessor,\\n    db_spans_enabled,\\n    exported_span_scopes,\\n)\\n\\nENV_VAR = \\\"LANGFLOW_OTEL_DB_SPANS\\\"\\n\\n\\ndef exported_names(env_value: str | None, scopes: list[str], monkeypatch) -> list[str]:\\n    \\\"\\\"\\\"Emit one span per scope through a freshly built processor, return what got exported.\\n\\n    The processor resolves its scope set at construction, so the environment has to be set\\n    before it is built. Building it inside the helper rather than in a fixture is what makes\\n    that ordering explicit.\\n    \\\"\\\"\\\"\\n    from opentelemetry.sdk.trace import TracerProvider\\n    from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\n    if env_value is None:\\n        monkeypatch.delenv(ENV_VAR, raising=False)\\n    else:\\n        monkeypatch.setenv(ENV_VAR, env_value)\\n\\n    exporter = InMemorySpanExporter()\\n    provider = TracerProvider()\\n    provider.add_span_processor(ApplicationOnlySpanProcessor(exporter))\\n    try:\\n        for scope in scopes:\\n            provider.get_tracer(scope).start_span(f\\\"span-from-{scope}\\\").end()\\n        provider.force_flush()\\n        return [s.name for s in exporter.get_finished_spans()]\\n    finally:\\n        provider.shutdown()\\n\\n\\ndef test_database_spans_are_exported_by_default(monkeypatch):\\n    \\\"\\\"\\\"The default, asserted before any of the absences below mean anything.\\\"\\\"\\\"\\n    exported = exported_names(None, [DB_INSTRUMENTATION_SCOPE], monkeypatch)\\n\\n    assert exported == [f\\\"span-from-{DB_INSTRUMENTATION_SCOPE}\\\"]\\n\\n\\n@pytest.mark.parametrize(\\\"off\\\", [\\\"false\\\", \\\"0\\\", \\\"no\\\", \\\"off\\\", \\\"FALSE\\\", \\\"Off\\\", \\\" false \\\"])\\ndef test_database_spans_are_dropped_when_turned_off(off, monkeypatch):\\n    \\\"\\\"\\\"Paired with the flow span, which must still export.\\n\\n    Without that second scope in the same run, an empty list reads the same whether the\\n    toggle worked or the processor stopped exporting anything at all.\\n    \\\"\\\"\\\"\\n    exported = exported_names(off, [DB_INSTRUMENTATION_SCOPE, APPLICATION_TRACER_NAME], monkeypatch)\\n\\n    assert exported == [f\\\"span-from-{APPLICATION_TRACER_NAME}\\\"]\\n\\n\\n@pytest.mark.parametrize(\\\"value\\\", [\\\"true\\\", \\\"1\\\", \\\"yes\\\", \\\"on\\\", \\\"\\\", \\\"maybe\\\", \\\"flase\\\", \\\"off ish\\\", \\\"2\\\"])\\ndef test_only_a_recognised_false_value_turns_them_off(value, monkeypatch):\\n    \\\"\\\"\\\"A typo must not silently stop telemetry the operator believes is running.\\n\\n    ``flase`` is in the list on purpose. It is the plausible typo, and the failure it would\\n    cause is invisible: telemetry quietly stops and nothing says so.\\n    \\\"\\\"\\\"\\n    exported = exported_names(value, [DB_INSTRUMENTATION_SCOPE], monkeypatch)\\n\\n    assert exported == [f\\\"span-from-{DB_INSTRUMENTATION_SCOPE}\\\"]\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"value\\\",\\n    [\\\"true\\\", \\\"false\\\", \\\"0\\\", \\\"1\\\", \\\"\\\", \\\"garbage\\\", \\\"opentelemetry.instrumentation.openai\\\", \\\"*\\\", \\\"all\\\"],\\n)\\ndef test_configuration_can_only_subtract_from_the_allowlist(value, monkeypatch):\\n    \\\"\\\"\\\"The safety property. No env value may widen the boundary.\\n\\n    Includes a value naming an LLM scope and a couple of wildcard-looking strings, because\\n    the failure worth guarding against is a future parser that treats the variable as a list\\n    of scopes to admit rather than as a boolean.\\n    \\\"\\\"\\\"\\n    monkeypatch.setenv(ENV_VAR, value)\\n\\n    assert exported_span_scopes() <= APPLICATION_INSTRUMENTATION_SCOPES\\n\\n\\ndef test_turning_them_off_removes_exactly_the_database_scope(monkeypatch):\\n    monkeypatch.setenv(ENV_VAR, \\\"false\\\")\\n\\n    assert APPLICATION_INSTRUMENTATION_SCOPES - exported_span_scopes() == {DB_INSTRUMENTATION_SCOPE}\\n\\n\\ndef test_db_spans_enabled_reflects_the_variable(monkeypatch):\\n    monkeypatch.delenv(ENV_VAR, raising=False)\\n    assert db_spans_enabled() is True\\n    monkeypatch.setenv(ENV_VAR, \\\"false\\\")\\n    assert db_spans_enabled() is False\\n\\n\\n# The end-to-end half. A real sqlite engine and the real instrumentor, in a subprocess because\\n# SQLAlchemyInstrumentor patches globally and the tracer provider is process-wide, so an\\n# in-process version of this would leak state into whatever test ran next.\\n\\nPROBE = \\\"\\\"\\\"\\nimport json, sys\\n\\nfrom opentelemetry import trace\\nfrom opentelemetry.sdk.trace import TracerProvider\\nfrom opentelemetry.sdk.trace.export import SimpleSpanProcessor\\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\nfrom lfx.observability import ApplicationOnlySpanProcessor, instrument_database\\n\\nexporter = InMemorySpanExporter()\\nprovider = TracerProvider()\\nprovider.add_span_processor(ApplicationOnlySpanProcessor(exporter))\\ntrace.set_tracer_provider(provider)\\n\\nimport sqlalchemy as sa\\n\\nengine = sa.create_engine(\\\"sqlite://\\\")\\ninstrument_database(engine)\\n\\nwith engine.connect() as conn:\\n    conn.execute(sa.text(\\\"SELECT 1\\\"))\\n\\n# A flow span too, so \\\"nothing exported\\\" and \\\"db spans suppressed\\\" cannot be confused.\\nprovider.get_tracer(\\\"langflow.observability\\\").start_span(\\\"flow.execute\\\").end()\\n\\nprovider.force_flush()\\nnames = [s.name for s in exporter.get_finished_spans()]\\nscopes = [s.instrumentation_scope.name if s.instrumentation_scope else \\\"\\\" for s in exporter.get_finished_spans()]\\nprint(\\\"PROBE_RESULT \\\" + json.dumps({\\\"names\\\": names, \\\"scopes\\\": scopes}))\\n\\\"\\\"\\\"\\n\\n\\ndef run_probe(env_value: str | None) -> dict:\\n    import os\\n\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    env.pop(ENV_VAR, None)\\n    if env_value is not None:\\n        env[ENV_VAR] = env_value\\n    with tempfile.TemporaryDirectory() as tmp:\\n        probe = Path(tmp) / \\\"probe.py\\\"\\n        probe.write_text(PROBE, encoding=\\\"utf-8\\\")\\n        completed = subprocess.run(  # noqa: S603\\n            [sys.executable, str(probe)], env=env, capture_output=True, text=True, timeout=300, check=False\\n        )\\n    assert completed.returncode == 0, completed.stderr\\n    lines = [ln for ln in completed.stdout.splitlines() if ln.startswith(\\\"PROBE_RESULT \\\")]\\n    assert lines, f\\\"probe printed no result.\\\\nstdout:\\\\n{completed.stdout}\\\\nstderr:\\\\n{completed.stderr}\\\"\\n    return json.loads(lines[0].removeprefix(\\\"PROBE_RESULT \\\"))\\n\\n\\ndef test_a_real_query_produces_database_spans_by_default():\\n    \\\"\\\"\\\"The positive control for the test below, run against the real instrumentor.\\\"\\\"\\\"\\n    result = run_probe(None)\\n\\n    assert DB_INSTRUMENTATION_SCOPE in result[\\\"scopes\\\"], result\\n    assert \\\"flow.execute\\\" in result[\\\"names\\\"], result\\n\\n\\ndef test_a_real_query_produces_no_database_spans_when_turned_off():\\n    \\\"\\\"\\\"And the flow span still exports, so the probe is demonstrably still looking.\\\"\\\"\\\"\\n    result = run_probe(\\\"false\\\")\\n\\n    assert DB_INSTRUMENTATION_SCOPE not in result[\\\"scopes\\\"], result\\n    assert \\\"flow.execute\\\" in r";
